window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]=window.__LIBQ["the-gioi-hoan-my"]["q11"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]["artifacts"]={"updatedAt":"2026-07-26","count":116,"artifacts":[{"id":"xuong-tay-chan-tien-cua-ninh-xuyen","name":"Xương tay Chân Tiên của Ninh Xuyên","cn":"","aliases":["Xương tay Tiên đạo của Ninh Xuyên"],"category":"khac","categoryLabel":"Tiên cốt","phamCap":"Chân Tiên","soHuu":["Ninh Xuyên"],"trangThai":"Còn trong tay trái Ninh Xuyên, cưỡng ép vận dụng gây phản phệ nặng","blurb":"Xương tay Chân Tiên nằm trong tay trái Ninh Xuyên, mang dấu ấn nguyên thủy và sức mạnh Tiên đạo. Pháp bảo này từng phá trạng thái miễn dịch pháp lực của Thạch Hạo và xuyên thủng hư không bị Giáo chủ phong cấm, nhưng gây tiêu hao cùng phản phệ cực nặng cho người sử dụng.","detail":"Ninh Xuyên đã đánh thức xương tay Chân Tiên để phá trạng thái miễn dịch pháp lực của Thạch Hạo, tạo ra công kích bằng sức mạnh Tiên đạo đủ khiến các Giáo chủ biến sắc. Sau đó, hắn tiếp tục cưỡng ép vận dụng tiên cốt để xuyên thủng thiên địa, vượt qua hư không bị Giáo chủ phong cấm và đào tẩu. Mỗi lần sử dụng đều làm hao tổn mạnh tinh khí, thần lực và đạo hạnh, đồng thời khiến cánh tay Ninh Xuyên gãy nát. @c1002","phanLoaiPhu":"Tiên cốt","hinhDang":"Xương nằm trong tay trái Ninh Xuyên","uyLuc":"Sức mạnh Tiên đạo của xương tay đủ khiến các Giáo chủ biến sắc.","dacDiem":"Mang dấu ấn nguyên thủy và uy lực lớn, nhưng mỗi lần cưỡng ép vận dụng đều tiêu hao mạnh tinh khí, thần lực, đạo hạnh và khiến cánh tay Ninh Xuyên gãy nát.","chuHienThoi":"Ninh Xuyên","congNang":["Phá trạng thái miễn dịch pháp lực của Thạch Hạo. @c1002","Tạo công kích bằng sức mạnh Tiên đạo. @c1002","Xuyên thủng thiên địa, vượt qua hư không bị Giáo chủ phong cấm để đào tẩu. @c1002"],"chuSoHuu":[{"ten":"Ninh Xuyên","tuChuong":"@c1002","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1002","tabs":{"tienTrinh":[{"chuong":"@c1002","loai":"khai phong","importance":"major","giaiDoan":"Thức tỉnh sức mạnh Tiên đạo","phamCap":"Chân Tiên","text":"Ninh Xuyên đánh thức xương tay để phá miễn dịch pháp lực, sau đó tiếp tục dùng nó xuyên thủng hư không đào tẩu và chịu phản phệ nặng nề.","anchor":"Chính bởi như thế, khi xương tay này thức tỉnh thì đã mạnh mẽ phá đi trạng thái Miễn dịch pháp lực của Thạch Hạo."}]},"nguon":["@c1002"]},{"id":"phap-khi-khong-gian-chua-vong-linh-hai","name":"Pháp khí không gian chứa Vong linh hải","cn":"","category":"phap-bao","categoryLabel":"Pháp khí không gian","phamCap":"Không rõ","soHuu":["Thập Quan vương"],"trangThai":"Đang được Thập Quan vương sử dụng","blurb":"Pháp khí không gian dùng để trấn áp và phóng thích Vong linh hải.","detail":"Thập Quan vương mở pháp khí tại lối ra Tiên cổ, giải phóng Vong linh hải khiến âm vụ, gió lạnh và khí tức tử vong bao trùm chiến trường.","phanLoaiPhu":"Pháp khí không gian","congNang":["Trấn áp Vong linh hải bên trong không gian pháp khí.","Phóng thích Vong linh hải để tạo âm vụ và khí tức tử vong."],"chuHienThoi":"Thập Quan vương","chuSoHuu":[{"ten":"Thập Quan vương","tuChuong":"@c1004","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1004","tabs":{"tienTrinh":[{"chuong":"@c1004","loai":"dùng","importance":"normal","giaiDoan":"Đang sử dụng","text":"Thập Quan vương mở pháp khí không gian và thả Vong linh hải để gây hỗn loạn tại lối ra Tiên cổ.","anchor":"Hắn lấy ra một pháp khí không gian, bên trong có trấn áp hải dương Vong linh này","phamCap":"Không rõ"}]},"nguon":["@c1004"]},{"id":"pha-gioi-phu-mau-vang-cua-thach-hao","name":"Phá Giới phù màu vàng của Thạch Hạo","cn":"","category":"phap-bao","categoryLabel":"Thần phù","phamCap":"Vượt Phá Giới phù thông thường","soHuu":["Thạch Hạo"],"trangThai":"Đã sử dụng","blurb":"Thần phù do nhiều Giáo chủ trong Tiên cổ hợp lực luyện chế cho Thạch Hạo, có khả năng xuyên qua phong tỏa thiên địa.","detail":"Thạch Hạo dùng phù men theo khe hư không để chạy rất xa khỏi lối ra Tiên cổ. Hệ thống đại trận do Giáo chủ bố trí cuối cùng vẫn ép hắn rơi ra ngoài.","phanLoaiPhu":"Phá Giới phù","nguonGoc":"Do mấy vị Giáo chủ trong Tiên cổ hợp lực luyện chế cho Thạch Hạo.","uyLuc":"Mạnh hơn Phá Giới phù thông thường và có thể xuyên qua phong tỏa thiên địa.","congNang":["Phá giới và đưa người sử dụng xuyên qua khu vực bị phong tỏa."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1004","denChuong":"@c1004","cachCoDuoc":"Được các Giáo chủ trong Tiên cổ hợp lực luyện chế cho","trangThai":"Đã sử dụng"}],"capNhatToi":"@c1004","tabs":{"tienTrinh":[{"chuong":"@c1004","loai":"dùng","importance":"normal","giaiDoan":"Đã kích hoạt","text":"Thạch Hạo kích hoạt thần phù để xuyên qua phong tỏa nhưng sau đó bị hệ thống đại trận ép khỏi hư không.","anchor":"Đây là tấm thần phù mà mấy vị Giáo chủ trong Tiên cổ đã hợp lực luyện chế cho hắn","phamCap":"Vượt Phá Giới phù thông thường"}]},"nguon":["@c1004"]},{"id":"doa-hoa-tien-dao-ba-ngan-canh","name":"Đóa hoa Tiên đạo ba ngàn cánh","cn":"","category":"khac","categoryLabel":"Dị vật","phamCap":"Tiên đạo","soHuu":[],"trangThai":"Đang mở thông đạo","blurb":"Đóa hoa Tiên đạo có ba ngàn cánh, mỗi cánh hóa thành một cánh cửa nối với Tiên cổ.","detail":"Dị vật mở các thông đạo đưa thiên tài ba ngàn châu trở lại khu không người. Khu vực quanh những cánh cửa sau đó bị các Giáo chủ phong tỏa để dò tìm Hoang và tranh đoạt tạo hóa.","hinhDang":"Đóa hoa có ba ngàn cánh tỏa khí lành.","congNang":["Biến mỗi cánh hoa thành một cánh cửa nối liền với Tiên cổ.","Đưa thiên tài từ Tiên cổ trở lại khu không người."],"capNhatToi":"@c1004","tabs":{"tienTrinh":[{"chuong":"@c1004","loai":"xuất hiện","importance":"normal","giaiDoan":"Mở thông đạo","text":"Ba ngàn cánh hoa hóa thành các cánh cửa nối với Tiên cổ và đưa các thiên tài trở về.","anchor":"ba ngàn cánh hoa lan tỏa khí lành, mỗi một chiếc lá là một cánh cửa nối liền với Tiên cổ","phamCap":"Tiên đạo"}]},"nguon":["@c1004"]},{"id":"cay-non-the-gioi-thu","name":"Cây non Thế Giới thụ","cn":"","aliases":["Thế Giới Thụ cây non","Thế Giới Thụ cây non của Thập Quan Vương"],"category":"khac","categoryLabel":"Thần thụ non","phamCap":"Không rõ","soHuu":["Thập Quan vương"],"trangThai":"Nguyên vẹn","blurb":"Cây non Thế Giới thụ nằm trong tay Thập Quan vương, tỏa ra đạo tắc mạnh và có khả năng xuyên phá trận pháp phong tỏa. (+) Cây non phát ra Hỗn Độn quang, được Thập Quan Vương dùng để thi triển thế định càn khôn. [CAN-SOAT-GOP] (+) Tiên chủng hoàn mỹ của Thập Quan Vương, mang hình thái cây non và có thể phát ra hỗn độn kiếm mang. [CAN-SOAT-GOP]","detail":"Thập Quan vương dùng cây non phá các trận pháp đang bao vây chiến trường. Đạo tắc của nó được so sánh với xương tay Chân Tiên của Ninh Xuyên, khiến nhiều Giáo chủ cùng chủ nhân Thú hải ra tay tranh đoạt.","phanLoaiPhu":"Thần thụ non","hinhDang":"Cây nhỏ","uyLuc":"Đạo tắc được so sánh với xương tay Chân Tiên của Ninh Xuyên.","dacDiem":"Có thể làm tan vỡ trận pháp phong tỏa.","chuHienThoi":"Thập Quan vương","congNang":["Phá vỡ trận pháp phong tỏa."],"chuSoHuu":[{"ten":"Thập Quan vương","tuChuong":"@c1005","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1005","loai":"dùng","importance":"normal","giaiDoan":"Phá vòng phong tỏa","text":"Thập Quan vương dùng cây non Thế Giới thụ xuyên phá các trận pháp để tìm đường thoát khỏi vòng vây.","anchor":"cây non Thế Giới thụ này lại có thể làm tan vỡ trận pháp","phamCap":"Không rõ"}]},"capNhatToi":"@c1005","nguon":["@c1005","@c1165","@c1206"]},{"id":"cau-da-trang-cua-de-toc","name":"Cầu đá trắng của Đế tộc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo đưa đón","phamCap":"Không rõ","soHuu":["Người của Đế tộc đương đại"],"trangThai":"Nguyên vẹn","blurb":"Cầu đá trắng của Đế tộc có thể vượt qua nhiều tầng trận pháp và đưa người rời khỏi chiến trường rất nhanh.","detail":"Cây cầu trắng như tuyết vắt ngang qua hàng chục trận pháp, dùng sức mạnh nhu hòa đón Thập Quan vương rồi biến mất trước khi các Giáo chủ kịp ngăn cản.","hinhDang":"Cây cầu trắng như tuyết","dacDiem":"Vượt qua hàng chục trận pháp và biến mất gần như tức thời.","chuHienThoi":"Người của Đế tộc đương đại","congNang":["Vượt qua nhiều trận pháp.","Đưa người được tiếp ứng rời khỏi chiến trường."],"chuSoHuu":[{"ten":"Người của Đế tộc đương đại","tuChuong":"@c1005","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1005","loai":"dùng","importance":"normal","giaiDoan":"Tiếp ứng Thập Quan vương","text":"Người của Đế tộc dùng cầu đá trắng vượt qua các trận pháp và đưa Thập Quan vương rời đi.","anchor":"một cây cầu đó trắng như tuyết vắt ngang qua mấy chục trận pháp","phamCap":"Không rõ"}]},"capNhatToi":"@c1005","nguon":["@c1005"]},{"id":"co-phu-tu-phe-tich-tam-the-dong-quan","name":"Cổ phù từ phế tích Tam thế đồng quan","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Cổ phù thần bí","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Rạn nứt","blurb":"Cổ phù Thạch Hạo thu được tại phế tích có Tam thế đồng quan có thể phóng thần quang xuyên thủng một Giáo chủ.","detail":"Thạch Hạo kích hoạt cổ phù trong tình thế bị nhiều Giáo chủ vây giết, khiến thần quang xuyên thủng ông lão La Phù chân cốc. Sau lần sử dụng này, trên phù xuất hiện một vết rạn.","nguonGoc":"Phế tích có Tam thế đồng quan","uyLuc":"Thần quang có thể xuyên thủng thân thể một Giáo chủ.","dacDiem":"Xuất hiện vết rạn sau khi được kích hoạt.","chuHienThoi":"Thạch Hạo","congNang":["Phóng thần quang sắc bén xuyên thủng cường giả cấp Giáo chủ."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1005","denChuong":"","cachCoDuoc":"Thu được tại phế tích có Tam thế đồng quan","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1005","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Xuyên thủng Giáo chủ","text":"Cổ phù phóng thần quang xuyên thủng ông lão La Phù chân cốc rồi xuất hiện một vết rạn.","anchor":"bên trên xuất hiện một vết rạn nứt, hiển nhiên là có quan hệ với lần sử dụng vừa rồi","phamCap":"Không rõ"}]},"capNhatToi":"@c1005","nguon":["@c1005"]},{"id":"dien-dong-tien-dien","name":"Điện đồng Tiên điện","cn":"","aliases":["Điện đồng của Tiên điện","Tiên điện đồng","Điện đồng cổ của Tiên điện","Tiên điện bằng đồng"],"category":"phap-bao","categoryLabel":"Pháp bảo kiến trúc","phamCap":"Không rõ","soHuu":["Tiên điện","Lão Giáo chủ Tiên điện"],"trangThai":"Còn nguyên, bị đánh bật nhiều lần","blurb":"Một tòa điện đồng của Tiên điện có khí hỗn độn dâng trào. Nhân vật số hai của Tiên điện bước ra từ bên trong để đối đầu Tề Đạo Lâm.","detail":"Điện đồng chấn động giữa cuộc đối đầu quanh Thạch Hạo, phóng ra khí hỗn độn và trở thành nơi nhân vật số hai của Tiên điện hiện thân.","phanLoaiPhu":"Pháp bảo kiến trúc","dacDiem":"Khi chấn động, điện đồng làm khí hỗn độn dâng trào.","chuHienThoi":"Tiên điện","capNhatToi":"@c1006","congNang":["Là nơi cường giả của Tiên điện hiện thân.","Dùng phù văn và bản thể điện đồng để phòng ngự."],"chuSoHuu":[{"ten":"Tiên điện","tuChuong":"@c1006","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"},{"ten":"Lão Giáo chủ Tiên điện","tuChuong":"@c1014","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1006","loai":"xuất hiện","importance":"normal","giaiDoan":"Nhân vật số hai hiện thân","text":"Điện đồng chấn động, khí hỗn độn dâng trào và nhân vật số hai của Tiên điện bước ra đối đầu Tề Đạo Lâm.","anchor":"một tòa điện đồng chấn động, khí hỗn độn dâng trào"},{"chuong":"@c1014","loai":"dùng","importance":"normal","giaiDoan":"Chống đỡ Chân Hoàng ấn","text":"Điện đồng được dùng phòng thủ nhưng liên tục bị Chân Hoàng ấn đánh bật và áp chế.","anchor":"Tiên điện bằng đồng bị đánh văng ra ngoài, mặc dù phù văn của thứ này đầy trời thế nhưng vẫn bị Liễu Thần áp chế.","phamCap":"Không rõ"}]},"nguon":["@c1006","@c1014"]},{"id":"sung-trau-cua-nguoi-ho-dao-thien-nhan-toc","name":"Sừng trâu của người Hộ Đạo Thiên Nhân tộc","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Nguyên vẹn, đã đổi chủ","blurb":"Chiếc sừng đen khổng lồ bị Tề Đạo Lâm chém lìa khỏi bản thể người Hộ Đạo Thiên Nhân tộc rồi giao cho Thạch Hạo. Nó được dùng làm vật liệu chế tạo tù và.","detail":"Chiếc sừng vốn thuộc về người Hộ Đạo Thiên Nhân tộc, bị Tề Đạo Lâm chém lìa và trao cho Thạch Hạo tại @c1007. Khi được giao, sừng vẫn còn dính máu và được dự định chế thành tù và.","phanLoaiPhu":"Sừng linh thú","hinhDang":"Sừng đen khổng lồ, dính máu","chuHienThoi":"Thạch Hạo","dacDiem":"Chiếc sừng đen khổng lồ, còn dính máu và có thể được chế thành tù và.","congNang":["Dùng làm vật liệu chế tạo tù và. @c1007"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1007","denChuong":"","cachCoDuoc":"Được Tề Đạo Lâm giao sau khi chém khỏi bản thể đối phương","trangThai":"đang sở hữu"}],"capNhatToi":"@c1007","tabs":{"tienTrinh":[{"chuong":"@c1007","loai":"đổi chủ","importance":"major","giaiDoan":"Được chém lấy và giao cho Thạch Hạo","text":"Tề Đạo Lâm chém lìa chiếc sừng khỏi bản thể người Hộ Đạo Thiên Nhân tộc rồi giao cho Thạch Hạo làm tù và.","anchor":"Đồ nhi, giữ lấy để làm tù và mà chơi.","phamCap":"Không rõ"}]},"nguon":["@c1007"]},{"id":"chien-xa-co-cua-chu-nhan-thien-quoc","name":"Chiến xa cổ của chủ nhân Thiên quốc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến xa","phamCap":"Không rõ","soHuu":["Chủ nhân Thiên quốc"],"trangThai":"đang sử dụng","blurb":"Chiến xa cổ đỏ đậm do chủ nhân Thiên quốc điều khiển trong cuộc vây giết Côn Bằng tử.","detail":"Chiến xa phủ dấu vết đao kiếm của vô số trận chiến, hiện ra cảnh máu chảy, hài cốt và oan hồn bị biến thành xa nô.","phanLoaiPhu":"Chiến xa cổ","hinhDang":"Chiến xa đỏ đậm phủ đầy dấu vết đao kiếm.","uyLuc":"Từng nghiền nát mặt trăng, đâm cháy mặt trời và đè nát tinh không.","dacDiem":"Tích tụ cảnh tượng máu chảy, hài cốt và những oan hồn bị biến thành xa nô.","chuHienThoi":"Chủ nhân Thiên quốc","congNang":["Nghiền ép mục tiêu bằng sức mạnh của chiến xa @c1008","Tích tụ oan hồn thành xa nô @c1008"],"chuSoHuu":[{"ten":"Chủ nhân Thiên quốc","tuChuong":"@c1008","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1008","tabs":{"tienTrinh":[{"chuong":"@c1008","loai":"dùng","importance":"normal","giaiDoan":"Mở màn cuộc vây giết","text":"Chủ nhân Thiên quốc điều khiển chiến xa cổ tham gia cuộc vây giết Côn Bằng tử.","anchor":"nó từng nghiền nát mặt trăng, đâm cháy mặt trời, đè nát tinh không","phamCap":"Không rõ"}]},"nguon":["@c1008"]},{"id":"sat-kiem-mau-mau","name":"Sát kiếm màu máu","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Thần kiếm","phamCap":"Không rõ","soHuu":["Chủ nhân Thiên quốc"],"trangThai":"đang sử dụng","blurb":"Thanh sát kiếm màu máu được chủ nhân Thiên quốc dùng trực diện công kích Côn Bằng tử.","detail":"Khi chém xuống, sát kiếm phát ra kiếm quang mênh mông tựa một dải thiên hà trút xuống chiến trường.","phanLoaiPhu":"Sát kiếm","hinhDang":"Thanh kiếm mang màu máu.","uyLuc":"Kiếm quang khi chém xuống rộng lớn như một dải thiên hà.","dacDiem":"Thiên về sát phạt trực diện.","chuHienThoi":"Chủ nhân Thiên quốc","congNang":["Chém giết trực diện bằng kiếm quang như thiên hà @c1008"],"chuSoHuu":[{"ten":"Chủ nhân Thiên quốc","tuChuong":"@c1008","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1008","tabs":{"tienTrinh":[{"chuong":"@c1008","loai":"dùng","importance":"normal","giaiDoan":"Công kích Côn Bằng tử","text":"Chủ nhân Thiên quốc dùng sát kiếm màu máu chém chính diện về phía Côn Bằng tử.","anchor":"sát kiếm màu máu bổ tới tựa như một dải thiên hà mênh mông trút xuống","phamCap":"Không rõ"}]},"nguon":["@c1008"]},{"id":"kiem-than-cua-coc-chu-kiem-coc","name":"Kiếm thần của cốc chủ Kiếm cốc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Thần kiếm","phamCap":"Không rõ","soHuu":["Cốc chủ Kiếm cốc"],"trangThai":"đang sử dụng","blurb":"Thần kiếm của cốc chủ Kiếm cốc được sử dụng trong cuộc vây giết Côn Bằng tử.","detail":"Cốc chủ Kiếm cốc vung thanh kiếm với uy thế như chém lìa cửu trùng thiên, đồng thời dùng nó làm phương tiện diễn hóa Kiếm giới.","phanLoaiPhu":"Thần kiếm","uyLuc":"Một lần vung kiếm mang uy thế như chém lìa cửu trùng thiên.","dacDiem":"Có thể dùng làm phương tiện thi triển Kiếm giới.","chuHienThoi":"Cốc chủ Kiếm cốc","congNang":["Thi triển Kiếm giới để bao phủ đối thủ @c1008","Phát động kiếm kích có uy thế chém lìa cửu trùng thiên @c1008"],"chuSoHuu":[{"ten":"Cốc chủ Kiếm cốc","tuChuong":"@c1008","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1008","tabs":{"tienTrinh":[{"chuong":"@c1008","loai":"dùng","importance":"normal","giaiDoan":"Diễn hóa Kiếm giới","text":"Cốc chủ Kiếm cốc dùng kiếm thần chém xuống và diễn hóa Kiếm giới trấn áp Côn Bằng tử.","anchor":"thanh kiếm trong tay hắn vung mạnh, tựa như chém lìa cửu trùng thiên","phamCap":"Không rõ"}]},"nguon":["@c1008"]},{"id":"long-chau-cua-mon-chu-yeu-long-dao-mon","name":"Long châu của môn chủ Yêu Long đạo môn","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ","phamCap":"Không rõ","soHuu":["Môn chủ Yêu Long đạo môn"],"trangThai":"đang sử dụng","blurb":"Viên Long châu được môn chủ Yêu Long đạo môn phun ra để công kích Côn Bằng tử.","detail":"Long châu hóa thành bảo cụ thảo phạt nhưng bị thứ thân Côn Bằng tử dùng một quyền mang áo nghĩa Côn Bằng đánh trúng.","phanLoaiPhu":"Long châu","dacDiem":"Có thể được phun ra từ miệng khi chủ nhân hóa thành cự long.","chuHienThoi":"Môn chủ Yêu Long đạo môn","congNang":["Hóa thành bảo cụ để trực tiếp thảo phạt đối thủ @c1008"],"chuSoHuu":[{"ten":"Môn chủ Yêu Long đạo môn","tuChuong":"@c1008","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1008","tabs":{"tienTrinh":[{"chuong":"@c1008","loai":"dùng","importance":"normal","giaiDoan":"Đối đầu thứ thân Côn Bằng tử","text":"Môn chủ Yêu Long đạo môn phun Long châu hóa thành bảo cụ thảo phạt, sau đó nó va chạm với quyền mang áo nghĩa Côn Bằng.","anchor":"hắn há miệng phun ra một viên Long châu rồi hóa thành bảo cụ thảo phạt","phamCap":"Không rõ"}]},"nguon":["@c1008"]},{"id":"doan-canh-lieu-vang-tien-co","name":"Đoạn cành liễu vàng Tiên cổ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Di vật Tế Linh","phamCap":"Không rõ","soHuu":["Liễu Thần"],"trangThai":"Được Liễu Thần thu giữ @c1009","blurb":"Đoạn cành liễu vàng Tiên cổ là một phần cổ tổ Tế Linh từng trầm miên trong dãy núi được các tộc bản địa tại di địa Tiên cổ bảo vệ. Sau khi giết Huyết Bức và giao chiến với Tiên điện đồng, nó được Liễu Thần thu nhỏ thành đoạn cây cầm tay làm vũ khí @c1009.","detail":"Đây không phải bản thể Liễu Thần hay một cây cổ thụ hoàn chỉnh, mà là một đoạn cành vàng từng ở trạng thái trầm miên trong di địa Tiên cổ. Nó được các tộc bản địa bảo vệ, có khả năng tự mình tham chiến, từng phóng lá vàng giết Huyết Bức và nghênh chiến Tiên điện đồng. Sau cuộc giao chiến trên chiến trường, đoạn cành được Liễu Thần thu nhỏ, cầm trong tay làm vũ khí @c1009.","phanLoaiPhu":"Di vật của cổ tổ Tế Linh","hinhDang":"Cành liễu màu vàng, có thể thu nhỏ thành một đoạn cây cầm tay.","nguonGoc":"Dãy núi được các tộc bản địa trong di địa Tiên cổ bảo vệ.","uyLuc":"Uy lực mạnh nhất đã thể hiện là dùng lá vàng giết một Giáo chủ và trực tiếp giao chiến với Tiên điện đồng.","dacDiem":"Là đoạn cành liễu màu vàng, không phải cổ thụ hoàn chỉnh; từng trầm miên trong di địa Tiên cổ và về sau được thu nhỏ thành vũ khí cầm tay của Liễu Thần.","chuHienThoi":"Liễu Thần","congNang":["Phóng lá vàng tấn công và giết đối thủ.","Trực tiếp giao chiến với pháp bảo và cường giả cấp Giáo chủ.","Có thể thu nhỏ thành một đoạn cây để Liễu Thần cầm làm vũ khí @c1009."],"chuSoHuu":[{"ten":"Di dân Tiên cổ","tuChuong":"@c1009","denChuong":"@c1009","cachCoDuoc":"Bảo vệ trong dãy núi tại di địa Tiên cổ","trangThai":"đã chuyển sang tay Liễu Thần"},{"ten":"Liễu Thần","tuChuong":"@c1009","denChuong":"","cachCoDuoc":"Vẫy tay thu nhỏ và thu vào tay","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1009","loai":"đổi chủ","importance":"major","giaiDoan":"Được Liễu Thần thu vào tay","text":"Sau khi giao chiến trên chiến trường, đoạn cành vàng được Liễu Thần thu nhỏ thành một đoạn cây cầm tay.","anchor":"nó vẫy tay thu nhỏ lại cành liễu màu vàng kia, hóa thành một đoạn cây nhỏ nằm trong tay mình","phamCap":"Không rõ"}]},"capNhatToi":"@c1009","nguon":["@c1009"]},{"id":"than-kiem-cua-coc-chu-kiem-coc","name":"Thần kiếm của Cốc chủ Kiếm cốc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Thần kiếm","phamCap":"Không rõ","soHuu":["Cốc chủ Kiếm cốc"],"trangThai":"Bị bẻ gãy @c1009","blurb":"Thần kiếm là vũ khí được Cốc chủ Kiếm cốc mang tới chiến trường để công kích cành liễu vàng. Trong lúc giao chiến, thanh kiếm bị Liễu Thần dùng đoạn cành vàng bẻ gãy @c1009.","detail":"Cốc chủ Kiếm cốc mang thần kiếm ép tới chiến trường và dùng nó tấn công cành liễu vàng. Khi Liễu Thần thật xuất hiện, đoạn cành vàng của Liễu Thần đã bẻ gãy thanh kiếm giữa lúc Cốc chủ Kiếm cốc phát động công kích @c1009.","phanLoaiPhu":"Kiếm","chuHienThoi":"Cốc chủ Kiếm cốc","dacDiem":"Vũ khí của Cốc chủ Kiếm cốc, đã bị đoạn cành vàng của Liễu Thần bẻ gãy @c1009.","chuSoHuu":[{"ten":"Cốc chủ Kiếm cốc","tuChuong":"@c1009","denChuong":"","cachCoDuoc":"","trangThai":"vật phẩm đã hư hỏng"}],"tabs":{"tienTrinh":[{"chuong":"@c1009","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị Liễu Thần bẻ gãy","text":"Thần kiếm bị Liễu Thần dùng đoạn cành vàng bẻ gãy giữa lúc Cốc chủ Kiếm cốc tấn công.","anchor":"thần kiếm trong tay hắn bị bẻ ngãy","phamCap":"Không rõ"}]},"capNhatToi":"@c1009","nguon":["@c1009"],"congNang":["Được Cốc chủ Kiếm cốc dùng làm vũ khí công kích cành liễu vàng @c1009."]},{"id":"gi-dong-nguyen-rua-cua-tien-dien","name":"Gỉ đồng nguyền rủa của Tiên điện","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật nguyền rủa","phamCap":"Không rõ","soHuu":["Chí tôn Tiên điện"],"trangThai":"Bị Liễu Thần hóa giải phần xâm nhập vào cành vàng","blurb":"Lớp gỉ đồng mang nguyền rủa bong khỏi điện đồng thành mưa sáng xanh lục. Nó ăn mòn cành vàng và uy hiếp đạo quả của người bị xâm nhập.","detail":"Chí tôn Tiên điện kích phát lớp gỉ này để buộc các cành vàng nhả điện đồng. Liễu Thần cưỡng ép toàn bộ nguyền rủa hội tụ vào một cành rồi thiêu nổ cành ấy để hóa giải.","phanLoaiPhu":"Vật nguyền rủa","hinhDang":"Gỉ đồng hóa thành mưa sáng xanh lục","uyLuc":"Có thể ăn mòn cành vàng và uy hiếp đạo quả của người trúng phải.","dacDiem":"Rất khó thoát khỏi sau khi đã xâm nhập cơ thể.","chuHienThoi":"Chí tôn Tiên điện","capNhatToi":"@c1011","congNang":["Mang nguyền rủa ăn mòn và uy hiếp đạo quả của người bị xâm nhập @c1011.","Buộc các cành vàng của Liễu Thần nhả điện đồng, giúp chí bảo thoát khỏi khống chế @c1011."],"chuSoHuu":[{"ten":"Chí tôn Tiên điện","tuChuong":"@c1011","denChuong":"","cachCoDuoc":"Đi kèm điện đồng của Tiên điện","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1011","loai":"xuất hiện","importance":"normal","giaiDoan":"Kích phát từ điện đồng","text":"Gỉ đồng bong khỏi điện đồng thành mưa sáng xanh lục, ăn mòn cành vàng và giúp chí bảo thoát khỏi sự khống chế của Liễu Thần.","anchor":"Đây chính là gỉ đồng nguyền rủa của Tiên điện"}]},"nguon":["@c1011"]},{"id":"chuong-vo-chung","name":"Chuông Vô Chung","cn":"","aliases":["Chuông cổ chữ Vô"],"category":"phap-bao","categoryLabel":"Chí bảo cổ","phamCap":"Chí bảo cổ bị hư hao","soHuu":["Bóng người điều khiển chuông Vô Chung","Chủ nhân đương đại của chuông Vô Chung"],"trangThai":"Bị phong tỏa tạm thời","blurb":"Chuông Vô Chung là chí bảo cổ không thuộc kỷ nguyên hiện tại, trên thân mang hai chữ cổ Vô và Chung. Dù không hoàn mỹ, chuông vẫn có thể phối hợp với điện đồng giáp kích Liễu Thần và từng được dùng để cứu viện lão Giáo chủ Tiên điện.","detail":"Ban đầu chỉ thấy chữ Vô, về sau chữ Chung hiện ra bên cạnh, xác nhận tên đầy đủ của pháp bảo là Chuông Vô Chung (@c1012). Chuông có liên hệ với áo nghĩa chữ Vô, phát ra pháp tắc khiến vật chất hữu hình tiêu tan; uy lực của nó từng làm Liễu Thần lảo đảo, nhưng ảnh hưởng sau đó bị các đồ án thờ cúng trên cơ thể Liễu Thần hóa giải. Chí bảo này còn phối hợp với điện đồng để giáp kích đối thủ và từng được vận dụng cứu viện lão Giáo chủ Tiên điện, song bị Côn Bằng do lá liễu hóa thành vây kín (@c1014).","phanLoaiPhu":"Chuông cổ","hinhDang":"Chuông lớn mang hai chữ cổ Vô và Chung","nguonGoc":"Không thuộc kỷ nguyên hiện tại","uyLuc":"Dù không hoàn mỹ, Chuông Vô Chung vẫn có thể khiến Liễu Thần lảo đảo.","dacDiem":"Thân chuông mang hai chữ cổ Vô và Chung, trong đó chữ Chung hiện ra bên cạnh chữ Vô để xác nhận tên đầy đủ; pháp bảo có liên hệ với áo nghĩa chữ Vô và không thuộc kỷ nguyên hiện tại.","chuHienThoi":"Bóng người điều khiển chuông Vô Chung","congNang":["Phát ra áo nghĩa chữ Vô, khiến vật chất hữu hình tiêu tan.","Phối hợp với điện đồng để giáp kích đối thủ (@c1012).","Phát tiếng chuông để công kích và cứu viện; từng được dùng cứu viện lão Giáo chủ Tiên điện (@c1014)."],"chuSoHuu":[{"ten":"Bóng người điều khiển chuông Vô Chung","tuChuong":"@c1012","denChuong":"","cachCoDuoc":"Chưa rõ","trangThai":"Đang điều khiển"},{"ten":"Chủ nhân đương đại của chuông Vô Chung","tuChuong":"@c1014","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1012","loai":"khai phong","importance":"major","giaiDoan":"Lộ tên Vô Chung","phamCap":"Chí bảo cổ bị hư hao","text":"Chữ Chung hiện ra bên cạnh chữ Vô, xác nhận tên đầy đủ của chuông là Vô Chung. Chí bảo cổ tiếp tục phối hợp với điện đồng vây công Liễu Thần.","anchor":"Hai chữ này ghép lại là: Vô Chung!"},{"chuong":"@c1014","loai":"dùng","importance":"normal","giaiDoan":"Cứu viện và bị phong tỏa","text":"Chuông Vô Chung được dùng cứu viện lão Giáo chủ Tiên điện nhưng bị Côn Bằng do lá liễu hóa thành vây kín, khiến tiếng chuông ngừng lại.","anchor":"âm ngân vang của chuông lớn cũng ngừng lại, bởi vì những con Côn Bằng màu vàng do lá liễu hóa thành đều vây kín và nhấn chìm lấy thứ này","phamCap":"Không rõ"}]},"capNhatToi":"@c1012","nguon":["@c1012","@c1014"]},{"id":"quan-tai-thuy-tinh-cua-chi-ton-tien-dien","name":"Quan tài thủy tinh của chí tôn Tiên điện","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phong kín","phamCap":"Chưa xác định","soHuu":["Chí tôn Tiên điện"],"trangThai":"Bị nổ tung","blurb":"Quan tài thủy tinh được chí tôn Tiên điện dùng để tự niêm phong chân thân và duy trì sức sống.","detail":"Quan tài lao vào Liễu Thần nhưng bị đánh bật rồi nổ tung, để lộ ông lão tóc trắng là chân thân chí tôn Tiên điện ở bên trong.","phanLoaiPhu":"Vật tự phong","hinhDang":"Quan tài bằng thủy tinh","uyLuc":"Có thể lao vào đối thủ trước khi bị đánh bật.","dacDiem":"Dùng để niêm phong chân thân nhằm duy trì sức sống.","chuHienThoi":"Chí tôn Tiên điện","congNang":["Niêm phong thân thể của chí tôn Tiên điện để duy trì sức sống."],"chuSoHuu":[{"ten":"Chí tôn Tiên điện","tuChuong":"@c1012","denChuong":"@c1012","cachCoDuoc":"Chưa rõ","trangThai":"Đã bị phá hủy"}],"tabs":{"tienTrinh":[{"chuong":"@c1012","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Quan tài nổ tung","phamCap":"Chưa xác định","text":"Quan tài thủy tinh dùng để tự niêm phong chí tôn Tiên điện bị đánh bật rồi nổ tung, để lộ chân thân của lão.","anchor":"vì duy trì sức sống cho nên tự niêm phong bản thân trong quan tài này"}]},"capNhatToi":"@c1012","nguon":["@c1012"]},{"id":"dinh-co-ho-the-cua-mot-giao-chu","name":"Đỉnh cổ hộ thể của một Giáo chủ","cn":"","category":"phap-bao","categoryLabel":"Pháp khí hộ thể","phamCap":"","soHuu":["Giáo chủ bị Liễu Thần đánh chết"],"trangThai":"Bị hủy","blurb":"Chiếc đỉnh cổ được một Giáo chủ sử dụng làm pháp khí hộ thể khi đối đầu Liễu Thần. Tuy nhiên, đỉnh đã bị một chưởng của Liễu Thần đánh nổ thành hàng trăm mảnh.","detail":"Đỉnh cổ được vị Giáo chủ đưa ra để che chắn và bảo vệ bản thân trước bàn tay của Liễu Thần. Pháp khí này không thể chống đỡ đòn đánh, bị một chưởng phá hủy thành hàng trăm mảnh @c1013.","phanLoaiPhu":"Pháp khí hộ thể","chuHienThoi":"Không còn","congNang":["Che chắn và bảo vệ người sử dụng @c1013."],"chuSoHuu":[{"ten":"Giáo chủ bị Liễu Thần đánh chết","tuChuong":"@c1013","denChuong":"@c1013","cachCoDuoc":"","trangThai":"Bị hủy cùng lúc chủ nhân tử vong"}],"capNhatToi":"@c1013","tabs":{"tienTrinh":[{"chuong":"@c1013","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","phamCap":"","text":"Đỉnh cổ được dùng để hộ thể nhưng bị một chưởng của Liễu Thần đánh nổ thành hàng trăm mảnh.","anchor":"chiếc đỉnh cổ này liền nổ tung hóa thành hàng trăm mảnh vỡ"}]},"nguon":["@c1013"],"dacDiem":"Một chiếc đỉnh cổ dùng làm pháp khí hộ thể; đã bị đánh nổ thành hàng trăm mảnh @c1013."},{"id":"phap-chi-tien-co-tu-vuc-ngoai","name":"Pháp chỉ Tiên cổ từ vực ngoại","cn":"","category":"khac","categoryLabel":"Pháp chỉ","phamCap":"Không rõ","soHuu":["Chủ nhân pháp chỉ từ vực ngoại"],"trangThai":"Đã truyền đạt lời cầu tình","blurb":"Tờ pháp chỉ cổ xưa mang văn tự kỷ nguyên Tiên cổ, được gửi từ vực ngoại tới Liễu Thần.","detail":"Pháp chỉ hơi hư tổn, bay tới gần Liễu Thần để truyền đạt lời xin tha cho lão Giáo chủ Tiên điện và chủ nhân chuông Vô Chung.","phanLoaiPhu":"Pháp chỉ truyền tin","hinhDang":"Tờ pháp chỉ cổ xưa, hơi hư tổn","dacDiem":"Ghi văn tự thuộc kỷ nguyên Tiên cổ.","chuHienThoi":"Chủ nhân pháp chỉ từ vực ngoại","congNang":["Truyền đạt lời cầu tình bằng văn tự kỷ nguyên Tiên cổ."],"chuSoHuu":[{"ten":"Chủ nhân pháp chỉ từ vực ngoại","tuChuong":"@c1014","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đã sử dụng"}],"capNhatToi":"@c1014","tabs":{"tienTrinh":[{"chuong":"@c1014","loai":"xuất hiện","importance":"normal","giaiDoan":"Bay tới cầu tình","text":"Pháp chỉ từ vực ngoại hạ xuống gần Liễu Thần để truyền đạt lời xin tha cho hai cường giả.","anchor":"Đây là một tấm pháp chỉ từ từ hạ xuống và bay về phía gần Liễu Thần, hiển nhiên là đang muốn nó đọc.","phamCap":"Không rõ"}]},"nguon":["@c1014"]},{"id":"bua-co-khong-tron-ven","name":"Búa cổ không trọn vẹn","cn":"","category":"phap-bao","categoryLabel":"Binh khí cổ","phamCap":"Không rõ","soHuu":[],"trangThai":"Không rõ","blurb":"Chiếc búa cổ không nguyên vẹn xuất hiện từ cuối chân trời trong ánh sáng hỗn độn.","detail":"Búa cổ rung động như chào Liễu Thần và khắc văn tự cổ vào hư không để giao lưu. Chương chưa xác nhận chủ nhân của nó hay quan hệ trực tiếp với người gửi pháp chỉ.","phanLoaiPhu":"Binh khí cổ","hinhDang":"Búa lớn không trọn vẹn","dacDiem":"Được bao phủ bởi ánh sáng hỗn độn và có thể khắc văn tự cổ vào hư không.","congNang":["Dùng văn tự cổ khắc trong hư không để giao lưu."],"capNhatToi":"@c1014","tabs":{"tienTrinh":[{"chuong":"@c1014","loai":"xuất hiện","importance":"normal","giaiDoan":"Giao lưu với Liễu Thần","text":"Búa cổ không trọn vẹn cuốn tới trong ánh sáng hỗn độn và dùng văn tự cổ giao lưu với Liễu Thần.","anchor":"một cái búa lớn xuất hiện, thứ này cũng không có trọn vẹn, nó mang theo ánh sáng hỗn độn từ cuối chân trời cuốn tới","phamCap":"Không rõ"}]},"nguon":["@c1014"]},{"id":"doan-canh-lieu-cung-te-tai-tien-co","name":"Đoạn cành liễu cúng tế tại Tiên cổ","cn":"","category":"khac","categoryLabel":"Vật dẫn dấu ấn","phamCap":"Không rõ","soHuu":["Liễu Thần"],"trangThai":"Dấu ấn đã thức tỉnh và sắp tiêu tán","blurb":"Đoạn cành liễu được dân bản địa Tiên cổ cúng tế, bên trong lưu giữ dấu ấn chiến đấu của Liễu Thần. Khi thức tỉnh, dấu ấn có thể hóa thành Liễu Thần trong thời gian hữu hạn trước khi tiêu tán.","detail":"Đây là đoạn cành liễu được dân bản địa Tiên cổ cúng tế và dùng làm vật dẫn lưu giữ dấu ấn chiến đấu của Liễu Thần. Hóa thân Liễu Thần hiện diện trong trận chiến thực chất do dấu ấn bên trong đoạn cành thức tỉnh, không phải chân thân của Liễu Thần; trạng thái này chỉ duy trì trong thời gian hữu hạn rồi tiêu tán. @c1014","phanLoaiPhu":"Vật dẫn dấu ấn chiến đấu","hinhDang":"Đoạn cành liễu","nguonGoc":"Được dân bản địa Tiên cổ cúng tế","dacDiem":"Lưu giữ dấu ấn chiến đấu thay vì chân thân Liễu Thần; dấu ấn sau khi thức tỉnh chỉ tồn tại trong thời gian hữu hạn.","chuHienThoi":"Liễu Thần","congNang":["Lưu giữ dấu ấn chiến đấu của Liễu Thần và cho phép dấu ấn thức tỉnh, hóa thành Liễu Thần trong thời gian hữu hạn. @c1014"],"chuSoHuu":[{"ten":"Liễu Thần","tuChuong":"@c1014","denChuong":"","cachCoDuoc":"Dấu ấn chiến đấu được lưu lại trong cành liễu cúng tế","trangThai":"Dấu ấn đã thức tỉnh"}],"capNhatToi":"@c1014","tabs":{"tienTrinh":[{"chuong":"@c1014","loai":"khai phong","importance":"major","giaiDoan":"Hé lộ vật dẫn hóa thân","text":"Đoạn cành liễu được xác nhận là vật dẫn lưu dấu ấn chiến đấu đang hóa thành Liễu Thần, nhưng dấu ấn chỉ tồn tại trong thời gian hữu hạn.","anchor":"Chỉ là một dấu ấn chiến đầu từng lưu lại ở trong đoạn cành liễu mà những dân bản địa trong Tiên cổ cúng tế mà thôi","phamCap":"Không rõ"}]},"nguon":["@c1014"]},{"id":"huyet-dich-ma-ton-o-ac-ma-dao","name":"Huyết dịch Ma tôn ở Ác Ma đảo","cn":"","aliases":[],"category":"khac","categoryLabel":"Thần vật","phamCap":"Không rõ","soHuu":["Đại ma thần"],"trangThai":"Đang tẩm bổ Đại ma thần","blurb":"Huyết dịch Ma tôn lấy từ Ác Ma đảo, có tác dụng bồi bổ và cường hóa thể phách.","detail":"Huyết dịch tiếp tục tẩm bổ thân thể Đại ma thần, khiến thể phách và khí lực của ông ngày càng mạnh mẽ.","phanLoaiPhu":"Huyết dịch thần vật","nguonGoc":"Ác Ma đảo","uyLuc":"Giúp thân thể Đại ma thần ngày càng mạnh mẽ hơn.","dacDiem":"Có khả năng tẩm bổ lâu dài cho thể phách.","chuHienThoi":"Đại ma thần","congNang":["Tẩm bổ và cường hóa thể phách của Đại ma thần."],"chuSoHuu":[{"ten":"Đại ma thần","tuChuong":"@c1017","denChuong":"","cachCoDuoc":"Huyết dịch từ Ma tôn tại Ác Ma đảo","trangThai":"đang sử dụng"}],"capNhatToi":"@c1017","tabs":{"tienTrinh":[{"chuong":"@c1017","loai":"dùng","importance":"normal","giaiDoan":"Tẩm bổ thân thể","text":"Huyết dịch Ma tôn tiếp tục tẩm bổ Đại ma thần và khiến thân thể ông ngày càng mạnh hơn.","anchor":"còn có huyết dịch Ma tôn ở Ác Ma đảo tẩm bổ, ngày càng mạnh mẽ hơn","phamCap":"Không rõ"}]},"nguon":["@c1017"]},{"id":"cot-thuan-vo","name":"Cốt thuẫn vỡ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo phòng ngự","phanLoaiPhu":"Thuẫn bằng xương","phamCap":"Không rõ","soHuu":[],"trangThai":"hong","hinhDang":"Một mảnh cốt thuẫn với bề mặt chi chít vết nứt.","dacDiem":"Bị vỡ nát và còn dính máu đã khô.","blurb":"Mảnh thuẫn bằng xương được tìm thấy dưới tro tàn tại tiểu viện cũ của Hỏa Linh Nhi. Tình trạng vỡ nát và dấu máu khô cho thấy nơi đây từng xảy ra chiến đấu.","detail":"Thạch Hạo đào được cốt thuẫn từ khu đất cháy đen của tiểu viện. Trên mặt thuẫn có nhiều vết nứt xen lẫn vật chất màu đen và dấu máu đã khô, khiến hắn lo Hỏa Linh Nhi từng gặp nguy hiểm tại đây.","capNhatToi":"@c1018","tabs":{"tienTrinh":[{"chuong":"@c1018","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện trong tro tàn","phamCap":"Không rõ","text":"Thạch Hạo tìm thấy mảnh cốt thuẫn vỡ dưới tro tàn của tiểu viện, trên thuẫn có nhiều vết nứt và dấu vết của máu khô.","anchor":"một miếng cốt thuẫn xuất hiện, bên trên chi chít vết nứt xem kẽ là một chút vật chất màu đen"}]},"nguon":["@c1018"]},{"id":"than-phu-mau-vang-cua-chin-dai-giao-chu","name":"Thần phù màu vàng của chín đại Giáo chủ","cn":"","category":"khac","categoryLabel":"Phù lục","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo nắm giữ","blurb":"Thần phù màu vàng do chín đại Giáo chủ luyện riêng cho Thạch Hạo, có khả năng xuyên qua nhiều đại trận.","detail":"Phù lục phối hợp với khả năng dẫn đường của Đả Thần Thạch, giúp nhóm Thạch Hạo tiến vào cấm địa Thiên Nhân tộc mà không gặp nguy hiểm lớn.","phanLoaiPhu":"Thần phù xuyên trận","hinhDang":"Tấm phù màu vàng","nguonGoc":"Do chín đại Giáo chủ luyện riêng cho Thạch Hạo.","chuHienThoi":"Thạch Hạo","congNang":["Xuyên thấu nhiều đại trận."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1021","denChuong":"","cachCoDuoc":"Được chín đại Giáo chủ luyện riêng.","trangThai":"đang giữ"}],"capNhatToi":"@c1021","tabs":{"tienTrinh":[{"chuong":"@c1021","loai":"dùng","importance":"normal","giaiDoan":"Xuyên qua đại trận","text":"Thần phù màu vàng giúp nhóm Thạch Hạo vượt qua hệ thống đại trận bảo vệ cấm địa Thiên Nhân tộc.","anchor":"một tấm thần phù màu vàng mà chín vị đại Giáo chủ đã cố ý luyện riêng cho hắn, thứ này có thể xuyên thấu rất nhiều đại trận"}]},"nguon":["@c1021"]},{"id":"cot-kinh-do-dich","name":"Cốt kính dò địch","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Cổ bảo","phanLoaiPhu":"Cốt kính","phamCap":"Cổ bảo","soHuu":["Hỏa Linh Nhi"],"chuHienThoi":"Hỏa Linh Nhi","trangThai":"Đang được Hỏa Linh Nhi giữ","blurb":"Cốt kính dò địch là một cổ bảo có khả năng tìm kiếm địch thủ tương tự thiên nhãn. Vật này vốn do nhóm Chân Thần canh giữ bên ngoài Thiên Chi Thành sử dụng, sau đó bị Thạch Hạo đoạt lấy và giao cho Hỏa Linh Nhi.","detail":"Nhóm Chân Thần canh giữ bên ngoài Thiên Chi Thành từng dùng cốt kính để dò tìm kẻ địch. Sau khi đánh phế họ và phá hủy các bảo cụ chống trả, Thạch Hạo đoạt cốt kính rồi tặng lại cho Hỏa Linh Nhi, khiến pháp bảo đổi chủ. @c1022","congNang":["Tìm kiếm, dò xét địch thủ theo cách tương tự thiên nhãn. @c1022"],"chuSoHuu":[{"ten":"Hỏa Linh Nhi","tuChuong":"@c1022","denChuong":"","cachCoDuoc":"Được Thạch Hạo giao sau khi hắn đoạt từ nhóm Chân Thần.","trangThai":"dang-co"}],"capNhatToi":"@c1022","tabs":{"tienTrinh":[{"chuong":"@c1022","loai":"đổi chủ","importance":"major","giaiDoan":"Thuộc về Hỏa Linh Nhi","text":"Thạch Hạo đoạt cốt kính từ nhóm Chân Thần canh giữ và giao cho Hỏa Linh Nhi.","anchor":"Đồ chơi này cũng hay hay, có thể sử dụng như là thiên nhãn, là một cổ bảo đó","phamCap":"Cổ bảo"}]},"nguon":["@c1022"],"dacDiem":"Cổ bảo dạng cốt kính."},{"id":"luoi-cat-tinh-than-cua-mac-la","name":"Lưới cát tinh thần của Mạc La","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ","phanLoaiPhu":"Lưới","vatLieu":"Cát tinh thần","phamCap":"","soHuu":["Mạc La"],"chuHienThoi":"Mạc La","trangThai":"Bị phá hủy","blurb":"Lưới cát tinh thần là bảo cụ hình lưới của Mạc La, được luyện từ những hạt cát tinh thần và có khả năng bao phủ, thu lấy vạn vật núi sông. Trong trận chiến ngoài Thiên Chi Thành, nó bị bảo thuật Lôi Đế đánh rách nát, cháy đen và hoàn toàn phá hủy @c1022.","detail":"Sau khi mất sự che chở của Thiên Chi Thành, Mạc La tung Lưới cát tinh thần để đối phó Thạch Hạo. Chiếc lưới lớn vốn có thể bao phủ và thu lấy vạn vật núi sông, nhưng đã bị lôi điện từ bảo thuật Lôi Đế đánh rách nát, làm cháy đen nhiều chỗ rồi phá hủy hoàn toàn @c1022.","congNang":["Bao phủ và thu lấy vạn vật núi sông."],"dacDiem":"Bảo cụ hình lưới của Mạc La, được luyện từ những hạt cát tinh thần; cuối cùng bị bảo thuật Lôi Đế đánh rách nát, cháy đen và phá hủy hoàn toàn @c1022.","chuSoHuu":[{"ten":"Mạc La","tuChuong":"@c1022","denChuong":"@c1022","cachCoDuoc":"Do Mạc La luyện thành.","trangThai":"da-huy"}],"capNhatToi":"@c1022","tabs":{"tienTrinh":[{"chuong":"@c1022","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","text":"Lưới cát tinh thần bị bảo thuật Lôi Đế đánh rách nát, cháy đen và hoàn toàn phá hủy.","anchor":"chiếc lưới lớn trở nên rách rưới cháy đen nhiều chỗ, hoàn toàn bị phá hủy","phamCap":""}]},"nguon":["@c1022"]},{"id":"thien-chi-thanh-phap-khi","name":"Thiên Chi Thành","cn":"","category":"phap-bao","categoryLabel":"Cổ thành kiêm pháp khí","phanLoaiPhu":"Chí bảo của Thiên Nhân tộc","phamCap":"Không rõ","soHuu":["Thiên Nhân tộc"],"trangThai":"Đang được vận hành","blurb":"Tổ địa của Thiên Nhân tộc đồng thời là một cổ thành đã được tế luyện thành chí bảo, có thể hóa thành bảo cụ khổng lồ để truy kích và trấn áp kẻ địch.","detail":"Sáu đại Thiên Nhân thời Thái cổ tìm thấy cổ thành này, sau đó nhiều đời dùng thiên tài địa bảo tế luyện. Khi được điều động chống Thạch Hạo, Thiên Chi Thành bộc phát cốt văn và thần uy đủ giết một Thiên Thần bình thường nếu đánh trúng, nhưng không thể xuyên thủng sự phòng ngự của Vạn Linh đồ.","nguonGoc":"Được sáu đại Thiên Nhân thời Thái cổ tìm thấy và được nhiều đời Thiên Nhân tộc tế luyện.","uyLuc":"Một đòn đánh trúng có thể giết Thiên Thần bình thường.","dacDiem":"Vừa là thành trì và tổ địa, vừa có thể hóa thành một bảo cụ khổng lồ.","chuHienThoi":"Thiên Nhân tộc","congNang":["Hóa thành bảo cụ khổng lồ để trấn áp và truy kích mục tiêu."],"chuSoHuu":[{"ten":"Thiên Nhân tộc","tuChuong":"@c1023","denChuong":"","cachCoDuoc":"Sáu đại Thiên Nhân thời Thái cổ tìm thấy rồi nhiều đời tế luyện.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1023","tabs":{"tienTrinh":[{"chuong":"@c1023","loai":"dùng","importance":"normal","giaiDoan":"Truy kích Thạch Hạo","phamCap":"Không rõ","text":"Thiên Nhân tộc điều động toàn bộ cổ thành hóa thành bảo cụ khổng lồ để truy kích và trấn áp Thạch Hạo.","anchor":"Thiên Chi Thành bắt đầu di chuyển, hóa thành một bảo cụ thật lớn đánh về phía Thạch Hạo"}]},"nguon":["@c1023"]},{"id":"ngoc-thach-thu","name":"Ngọc thạch thư","cn":"","category":"khac","categoryLabel":"Vật phẩm truyền thừa","phamCap":"Tạo hóa Tiên cổ","soHuu":[],"trangThai":"Không rõ","blurb":"Bốn bộ ngọc thạch thư được mang về từ tiên gia chiến trường, bên trong ghi chép Tiên Đạo kinh văn. (+) Vật phẩm tạo hóa hiếm có nằm trong khu tạo hóa Tiên cổ. [CAN-SOAT-GOP]","detail":"Chỉ một số nhân tài hàng đầu từng nhìn thấy Ngọc thạch thư và khoảng mười người đoạt được. Hiểu Nguyệt tiên tử từng tiến vào khu tạo hóa nhưng cuối cùng bỏ lỡ cơ hội giành một bộ.","phanLoaiPhu":"Vật phẩm truyền thừa","nguonGoc":"Khu tạo hóa Tiên cổ","dacDiem":"Tạo hóa hiếm, chỉ một số ít thiên kiêu hàng đầu có cơ hội tiếp cận.","capNhatToi":"@c1026","nguon":["@c1026","@c1149"],"aliases":["Bốn bộ ngọc thạch thư"],"tabs":{}},{"id":"chien-xa-than-dong-nam-mau","name":"Chiến xa thần đồng năm màu","cn":"","aliases":["Chiến xa năm màu"],"category":"phap-bao","categoryLabel":"Bí bảo phi hành","phamCap":"","soHuu":["Viên Thiên","Lâm Thiên","Thạch Hạo"],"trangThai":"Đã thần phục Thạch Hạo","blurb":"Chiến xa được chế tạo từ thần đồng năm màu, vận hành bằng phù văn mà không cần thú kéo, có tốc độ đủ sức xé rách hư không. Từng do Viên Thiên điều khiển tiến vào Thanh thành, nó sau đó được Thông Tí thần viên mượn để chạy trốn nhưng rơi vào tay Thạch Hạo.","detail":"Chiến xa thần đồng năm màu có thân xe chạm hình thần ma và vạn thú, khi vận hành có thể hiển hóa nhật nguyệt, sơn hà cùng bóng mờ thần ma. Viên Thiên từng điều khiển chiến xa xé rách hư không, bay vào Thanh thành rồi hạ xuống ngọn núi gãy màu đen; dù bị ngọn núi này quấy nhiễu, chiến xa vẫn hạ xuống an toàn. Về sau, Thông Tí thần viên mượn xe làm phương tiện chạy trốn, nhưng bị Thạch Hạo bắt giữ và áp chế toàn bộ dị tượng của chiến xa. @c1027 @c1028","phanLoaiPhu":"Bí bảo phi hành","hinhDang":"Chiến xa chạm hình thần ma và vạn thú","vatLieu":"Thần đồng năm màu","uyLuc":"Khi được điều khiển phi hành, chiến xa có tốc độ đủ sức xé rách hư không. @c1027","dacDiem":"Được chế tạo từ thần đồng năm màu, không cần thú kéo, vận hành bằng phù văn và chạm hình thần ma cùng vạn thú.","chuHienThoi":"Viên Thiên","capNhatToi":"@c1027","congNang":["Phi hành bằng phù văn mà không cần thú kéo, với tốc độ đủ xé rách hư không. @c1027","Dùng làm phương tiện di chuyển và chạy trốn. @c1027 @c1028","Hiển hóa nhật nguyệt, sơn hà và bóng mờ thần ma."],"chuSoHuu":[{"ten":"Viên Thiên","tuChuong":"@c1027","denChuong":"","cachCoDuoc":"","trangThai":"Đang sử dụng"},{"ten":"Lâm Thiên","tuChuong":"@c1028","denChuong":"@c1028","cachCoDuoc":"Là chủ nhân ban đầu được xác nhận.","trangThai":"đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c1028","denChuong":"","cachCoDuoc":"Bắt giữ và luyện cho chiến xa thần phục.","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1027","loai":"dùng","importance":"normal","giaiDoan":"Giáng xuống Thanh thành","text":"Viên Thiên điều khiển chiến xa xé rách hư không, bay vào Thanh thành và hạ xuống ngọn núi gãy màu đen.","anchor":"là một chiếc chiến xa được chế tạo từ thần đồng năm màu"},{"chuong":"@c1028","loai":"đổi chủ","importance":"major","giaiDoan":"Thần phục Thạch Hạo","phamCap":"Cấp Giáo chủ","text":"Chiến xa được Thông Tí thần viên mượn để chạy trốn nhưng bị Thạch Hạo bắt giữ, áp chế mọi dị tượng và luyện cho thần phục.","anchor":"phù văn và tiên khí không ngừng đan xen, chiếc chiến xa này đã bị thần phục"}]},"nguon":["@c1027","@c1028"]},{"id":"ken-lenh-cua-chang-trai-sung-trau","name":"Kèn lệnh của chàng trai sừng trâu","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"","soHuu":["Chàng trai đầu mọc sừng trâu"],"trangThai":"Bị bẻ gãy","blurb":"Kèn lệnh của chàng trai sừng trâu là pháp khí công kích bằng chấn động âm thanh, có thể phát ra tiếng kèn rung trời và làm hư không nứt toác. Khi được dùng để khiêu chiến Viên Thiên, tiếng kèn bị tiếng gầm của đối phương lấn át, sau đó pháp khí bị bẻ gãy trong giao chiến.","detail":"Pháp khí dạng kèn lệnh này thuộc về chàng trai đầu mọc sừng trâu và được dùng để tấn công Viên Thiên. Nó phát ra âm thanh rung trời, tạo chấn động mạnh đến mức khiến hư không nứt toác; tuy nhiên, Viên Thiên đã dùng tiếng gầm lấn át tiếng kèn rồi bẻ gãy pháp khí trong cuộc giao chiến. @c1027","phanLoaiPhu":"Pháp khí âm thanh","hinhDang":"Kèn lệnh","uyLuc":"Âm thanh phát ra có thể làm hư không nứt toác.","dacDiem":"Pháp khí dạng kèn lệnh, dùng tiếng kèn để công kích bằng chấn động âm thanh; đã bị Viên Thiên bẻ gãy. @c1027","chuHienThoi":"Chàng trai đầu mọc sừng trâu","capNhatToi":"@c1027","congNang":["Phát ra âm thanh rung trời, dùng chấn động âm thanh để công kích và làm hư không nứt toác."],"chuSoHuu":[{"ten":"Chàng trai đầu mọc sừng trâu","tuChuong":"@c1027","denChuong":"","cachCoDuoc":"","trangThai":"Pháp khí đã bị bẻ gãy"}],"tabs":{"tienTrinh":[{"chuong":"@c1027","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị bẻ gãy","text":"Kèn lệnh được dùng tấn công Viên Thiên nhưng bị đối phương bẻ gãy trong cuộc giao chiến.","anchor":"tay cầm một chiếc kèn lệnh nhẹ nhàng thổi một cái, tiếng vù vù rung trời","phamCap":""}]},"nguon":["@c1027"]},{"id":"vong-than-nam-mau","name":"Vòng thần năm màu","cn":"","aliases":[],"category":"khac","categoryLabel":"Pháp khí hoặc thần thông chưa xác định","phamCap":"","soHuu":["Chân Thần từng vào di địa Tiên cổ"],"trangThai":"Không rõ","blurb":"Một vòng thần năm màu được dùng để phát ra thần quang ngũ hành tấn công Viên Thiên.","detail":"Chân Thần từng vào di địa Tiên cổ phun vòng thần này ra trong cuộc khiêu chiến. Thần quang ngũ hành không đánh trúng Viên Thiên.","phanLoaiPhu":"Vật phẩm hoặc thần thông ngũ hành chưa xác định","hinhDang":"Vòng thần năm màu","uyLuc":"Phát ra thần quang ngũ hành để công kích.","dacDiem":"Được phun ra từ miệng người sử dụng.","chuHienThoi":"Chân Thần từng vào di địa Tiên cổ","capNhatToi":"@c1027","congNang":["Phóng thần quang ngũ hành tấn công mục tiêu."],"chuSoHuu":[{"ten":"Chân Thần từng vào di địa Tiên cổ","tuChuong":"@c1027","denChuong":"","cachCoDuoc":"","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1027","loai":"dùng","importance":"normal","giaiDoan":"Tấn công Viên Thiên","text":"Vòng thần năm màu phát ra thần quang ngũ hành tấn công Viên Thiên nhưng bị né tránh.","anchor":"hắn há miệng phun ra một vòng thần năm màu phát ra thần quang ngũ hành","phamCap":""}]},"nguon":["@c1027"]},{"id":"chen-ruou-bang-da-ngoc","name":"Chén rượu bằng đá ngọc","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật dụng","phamCap":"Bình thường","soHuu":["Thạch Hạo"],"trangThai":"Không rõ","blurb":"Chén rượu bằng đá ngọc bình thường được Thạch Hạo dùng như binh khí để áp đảo Thông Tí thần viên.","detail":"Thạch Hạo lần lượt ném chén rượu cắt đứt móng vuốt vàng và dùng một chén khác chặn cứng Thông Tí quyền, qua đó làm bàn tay thần viên be bét máu và biến dạng.","phanLoaiPhu":"Chén rượu","hinhDang":"Chén rượu","vatLieu":"Đá ngọc","dacDiem":"Bản thân chỉ là vật dụng bình thường, sức áp đảo đến từ người sử dụng.","chuHienThoi":"Thạch Hạo","congNang":["Được dùng để cắt đứt móng vuốt vàng của Thông Tí thần viên.","Được dùng để chặn cứng Thông Tí quyền."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1028","denChuong":"","cachCoDuoc":"Chén rượu đang được sử dụng khi giao chiến.","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1028","loai":"dùng","importance":"normal","giaiDoan":"Áp đảo Thông Tí thần viên","phamCap":"Bình thường","text":"Thạch Hạo dùng những chén rượu bình thường để phá móng vuốt và chặn đứng Thông Tí quyền.","anchor":"chén rượu này cũng chỉ là một chén rượu bằng đá ngọc bình thường"}]},"capNhatToi":"@c1028","nguon":["@c1028"]},{"id":"roi-dong-nam-mau","name":"Roi đồng năm màu","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không rõ","soHuu":["Lâm Thiên"],"trangThai":"Mất cảm ứng với chiến xa","blurb":"Pháp khí được Lâm Thiên dùng để kiểm tra chiến xa năm màu. Roi mất cảm ứng với xe sau khi chiến xa bị người khác luyện hóa.","detail":"Lâm Thiên truyền thần lực vào roi đồng năm màu và dựa vào liên hệ giữa hai pháp khí để kiểm tra chiến xa. Việc roi không còn cảm ứng giúp hắn xác định chiến xa đã bị người khác luyện hóa.","phanLoaiPhu":"Pháp khí điều khiển chiến xa","congNang":["Cảm ứng và kiểm tra tình trạng của chiến xa năm màu."],"dacDiem":"Mất liên hệ với chiến xa khi chiếc xe bị người khác luyện hóa.","chuHienThoi":"Lâm Thiên","chuSoHuu":[{"ten":"Lâm Thiên","tuChuong":"@c1029","denChuong":"","cachCoDuoc":"Đã sở hữu khi xuất hiện","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1029","tabs":{"tienTrinh":[{"chuong":"@c1029","loai":"dùng","importance":"normal","giaiDoan":"Kiểm tra chiến xa","text":"Lâm Thiên truyền thần lực vào roi và phát hiện pháp khí này đã mất cảm ứng với chiến xa năm màu.","anchor":"chiếc roi đồng này đã mất cảm ứng với chiến xa kia rồi"}]},"nguon":["@c1029"]},{"id":"chien-thuyen-tim","name":"Chiến thuyền tím","cn":"","category":"phap-bao","categoryLabel":"Pháp khí phi hành","phamCap":"Không rõ","soHuu":["Lâm Thiên"],"trangThai":"Đang sử dụng","blurb":"Chiến thuyền màu tím chở Lâm Thiên cùng bốn cường giả trẻ tuổi vực ngoại. Nó có thể phi hành và xé hư không để di chuyển.","detail":"Lâm Thiên và bốn người đồng hành bước lên chiến thuyền tím rồi xé hư không rời đi. Cuối chương, chiến thuyền khởi hành cùng hướng với đoàn Thạch Hạo.","phanLoaiPhu":"Chiến thuyền phi hành","hinhDang":"Thuyền màu tím","congNang":["Phi hành trên không.","Xé hư không để di chuyển."],"chuHienThoi":"Lâm Thiên","chuSoHuu":[{"ten":"Lâm Thiên","tuChuong":"@c1029","denChuong":"","cachCoDuoc":"Đã sử dụng khi xuất hiện","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1029","tabs":{"tienTrinh":[{"chuong":"@c1029","loai":"dùng","importance":"normal","giaiDoan":"Lên đường dự hẹn","text":"Chiến thuyền tím chở Lâm Thiên và bốn người đồng hành xé hư không rời đi, cùng hướng với đoàn Thạch Hạo.","anchor":"Bọn họ phóng lên trời cao, đạp lên trên một chiếc thuyền tím rồi xé ra hư không rời đi."}]},"nguon":["@c1029"]},{"id":"chien-thuyen-tu-kim","name":"Chiến thuyền tử kim","cn":"","category":"phap-bao","categoryLabel":"Chiến thuyền","phamCap":"Không rõ","soHuu":["Lâm Thiên","Bốn người trẻ tuổi đi cùng Lâm Thiên"],"trangThai":"nguyên vẹn","blurb":"Chiến thuyền tử kim chở Lâm Thiên và bốn người trẻ tuổi tới Kỳ Lân lĩnh.","detail":"Chiến thuyền xuyên qua hư không từ phía chân trời, tỏa ánh tím mạnh mẽ làm tan mây khi tiến tới vùng núi.","hinhDang":"Chiến thuyền mang sắc tử kim.","dacDiem":"Tỏa ánh tím mạnh mẽ khi xuất hiện.","congNang":["Xuyên qua hư không để chuyên chở người."],"chuSoHuu":[{"ten":"Lâm Thiên","tuChuong":"@c1030","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1030","loai":"xuất hiện","importance":"normal","giaiDoan":"Tới Kỳ Lân lĩnh","text":"Chiến thuyền tử kim chở Lâm Thiên cùng bốn người trẻ tuổi xuyên hư không tới Kỳ Lân lĩnh.","anchor":"Ở phía chân trời có một chiếc chiến thuyền tử kim đang xuyên qua hư không tới đây","phamCap":"Không rõ"}]},"capNhatToi":"@c1030","nguon":["@c1030"]},{"id":"truong-thuong-den-cua-lam-thien","name":"Trường thương đen của Lâm Thiên","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Lâm Thiên"],"trangThai":"hư tổn","blurb":"Trường thương đen là binh khí được Lâm Thiên sử dụng trong các cuộc giao chiến tại Kỳ Lân lĩnh. Nó có thể đâm nát hư không, phá vỡ các đại tinh do Thiên đồ diễn hóa, nhưng đã bị Thạch Hạo chặt đứt một phần trong lần giao chiến thứ hai.","detail":"Nguồn gốc của trường thương đen chưa được xác định. Lâm Thiên dùng binh khí này để công kích trực diện, từng đâm nát hư không và phá các đại tinh do Thiên đồ của Ninh Xuyên diễn hóa. Khi Lâm Thiên đánh lén Thạch Hạo, đối phương dùng chưởng thay đao chặt đứt một phần trường thương @c1030.","hinhDang":"Một thanh trường thương màu đen.","uyLuc":"Có thể đâm nát hư không và phá vỡ các đại tinh trong Thiên đồ.","dacDiem":"Trường thương màu đen của Lâm Thiên; bị Thạch Hạo dùng chưởng thay đao chặt đứt một phần trong lần giao chiến thứ hai @c1030.","congNang":["Dùng để công kích trực diện.","Có thể đâm nát hư không.","Có thể phá vỡ các đại tinh do Thiên đồ diễn hóa."],"chuSoHuu":[{"ten":"Lâm Thiên","tuChuong":"@c1030","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu, đã hư tổn"}],"tabs":{"tienTrinh":[{"chuong":"@c1030","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị chặt gãy","text":"Sau khi Lâm Thiên đánh lén, Thạch Hạo dùng chưởng thay đao chặt đứt một phần trường thương đen.","anchor":"Thạch Hạo dùng chưởng thay đao chặt đứt một phần của thanh trường thương đen kia","phamCap":"Không rõ"}]},"capNhatToi":"@c1030","nguon":["@c1030"]},{"id":"chien-xa-nam-mau","name":"Chiến xa năm màu","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo phi hành","phanLoaiPhu":"Chiến xa","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Nguyên vẹn","blurb":"Chiến xa năm màu từng thuộc về Lâm Thiên và được dùng để chở Thông Tí thần viên. Sau cuộc giao tranh, Thạch Hạo trả thần viên cho Lâm Thiên nhưng giữ chiến xa làm chiến lợi phẩm.","detail":"Chiến xa năm màu là pháp bảo phi hành từng do Lâm Thiên sử dụng để chở Thông Tí thần viên. Sau khi Lâm Thiên thất bại trước Thạch Hạo, Thạch Hạo trả lại thần viên nhưng giữ chiến xa, khiến pháp bảo này đổi chủ @c1031. Phẩm cấp và các năng lực cụ thể khác chưa được nêu rõ.","chuSoHuu":[{"ten":"Lâm Thiên","tuChuong":"@c1031","denChuong":"@c1031","cachCoDuoc":"Là chủ cũ của chiến xa khi chở Thông Tí thần viên.","trangThai":"Đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c1031","denChuong":"","cachCoDuoc":"Thu hồi chiến xa sau khi trả Thông Tí thần viên cho Lâm Thiên.","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1031","loai":"đổi chủ","importance":"major","giaiDoan":"Thuộc về Thạch Hạo","text":"Sau khi trả Thông Tí thần viên cho Lâm Thiên, Thạch Hạo giữ chiến xa năm màu làm chiến lợi phẩm.","anchor":"hắn cũng chẳng hề khách sáo thu hồi lại chiến xa năm màu","phamCap":"Không rõ"}]},"capNhatToi":"@c1031","nguon":["@c1031"],"dacDiem":"Chiến xa có năm màu; từng thuộc về Lâm Thiên, sau đó trở thành chiến lợi phẩm của Thạch Hạo @c1031.","congNang":["Dùng làm phương tiện phi hành và chuyên chở; từng chở Thông Tí thần viên."]},{"id":"giot-nuoc-ky-di-muon-mau","name":"Giọt nước kỳ dị muôn màu","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật chất thần bí","phamCap":"Không rõ","soHuu":[],"trangThai":"khong-ro","blurb":"Một giọt nước muôn màu tồn tại trong Cấm khu, có khả năng giết chết chí cường giả.","detail":"Vật chất kỳ dị này được dùng để chứng minh hiểm họa trong Cấm khu không thể chỉ đánh giá bằng cảnh giới tu hành.","phanLoaiPhu":"Vật chất Cấm khu","hinhDang":"Giọt nước muôn màu","uyLuc":"Có thể giết chết chí cường giả.","dacDiem":"Mang màu sắc muôn hình muôn vẻ và ẩn chứa sức sát thương cực lớn.","congNang":["Giết chết chí cường giả trong Cấm khu. @c1032"],"capNhatToi":"@c1032","tabs":{"tienTrinh":[{"chuong":"@c1032","loai":"xuất hiện","importance":"normal","giaiDoan":"Được dùng làm ví dụ về hiểm họa Cấm khu","text":"Giọt nước kỳ dị muôn màu được tiết lộ là vật chất có thể giết chết chí cường giả.","anchor":"một giọt nước kỳ dị với muôn màu muôn vẻ có thể giết chết chí cường giả"}]},"nguon":["@c1032"]},{"id":"canh-co-kho-phat-kiem-khi","name":"Cành cỏ khô phát kiếm khí","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật chất thần bí","phamCap":"Không rõ","soHuu":[],"trangThai":"khong-ro","blurb":"Một cành cỏ khô bình thường trong Cấm khu nhưng có thể phát ra kiếm khí tuyệt thế chém lìa ngôi sao.","detail":"Vẻ ngoài tầm thường của cành cỏ hoàn toàn trái ngược với kiếm khí có sức phá hủy thiên thể mà nó phóng ra.","phanLoaiPhu":"Vật chất Cấm khu","hinhDang":"Cành cỏ khô bình thường","uyLuc":"Kiếm khí phát ra có thể chém lìa ngôi sao.","dacDiem":"Bề ngoài giống cỏ khô thông thường nhưng ẩn chứa kiếm khí tuyệt thế.","congNang":["Phát ra kiếm khí tuyệt thế có thể chém lìa ngôi sao. @c1032"],"capNhatToi":"@c1032","tabs":{"tienTrinh":[{"chuong":"@c1032","loai":"xuất hiện","importance":"normal","giaiDoan":"Được dùng làm ví dụ về hiểm họa Cấm khu","text":"Cành cỏ khô được tiết lộ có thể phóng kiếm khí tuyệt thế chém lìa ngôi sao.","anchor":"một cành cỏ khô bình thường lại có thể phát ra kiếm khí tuyệt thế chém lìa ngôi sao"}]},"nguon":["@c1032"]},{"id":"thanh-duoc-tuu","name":"Thánh dược tửu","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Linh tửu","phamCap":"Không rõ","soHuu":["Đại ma thần"],"trangThai":"Được dùng trong bữa tiệc","blurb":"Linh tửu có hương thơm được mang ra trong bữa tiệc gia đình tại Ma châu.","detail":"Đại ma thần dùng Thánh dược tửu để khoản đãi Thạch Hạo và Hỏa Linh Nhi khi hai người tới Ma châu.","capNhatToi":"@c1033","nguon":["@c1033"]},{"id":"thit-thien-than","name":"Thịt Thiên Thần","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Cấp Thiên Thần","soHuu":["Đại ma thần"],"trangThai":"Đã dùng mở tiệc","blurb":"Nguyên liệu lấy từ những sinh linh cấp Thiên Thần mà Thạch Hạo từng để lại cho tổ phụ.","detail":"Số thịt gồm thịt Giao, Long Tước và hoàng kim Hạc, được hầm và nướng để dùng trong bữa tiệc tại Ma châu.","capNhatToi":"@c1033","nguon":["@c1033"]},{"id":"bo-doan-tu-dong-phu-tien-gia","name":"Bồ đoàn từ động phủ tiên gia","cn":"","category":"khac","categoryLabel":"Vật phẩm tu luyện","phanLoaiPhu":"Bồ đoàn hỗ trợ tu luyện","phamCap":"Không rõ","soHuu":["Ba đại chí tôn vực ngoại"],"trangThai":"Nguyên vẹn","hinhDang":"Bồ đoàn bện bằng thần thảo trắng lấp lánh","vatLieu":"Thần thảo trắng","nguonGoc":"Động phủ tiên gia","blurb":"Bồ đoàn lấy từ động phủ tiên gia, có khả năng giúp người ngồi nhanh chóng tĩnh tâm.","detail":"Khi Thạch Hạo vừa ngồi xuống, lòng hắn nhanh chóng yên lặng và tiến vào trạng thái không linh gần với ngộ đạo. Bồ đoàn được bện bằng thần thảo trắng lấp lánh và có tiếng tụng kinh vang lên.","congNang":["Giúp người ngồi tĩnh tâm và tiến gần trạng thái ngộ đạo."],"dacDiem":"Bện bằng thần thảo trắng lấp lánh và phát ra tiếng tụng kinh.","chuHienThoi":"Ba đại chí tôn vực ngoại","chuSoHuu":[{"ten":"Ba đại chí tôn vực ngoại","tuChuong":"@c1035","denChuong":"","cachCoDuoc":"Được lấy từ động phủ tiên gia","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1035","loai":"dùng","importance":"normal","giaiDoan":"Hỗ trợ tĩnh tâm","text":"Thạch Hạo ngồi trên bồ đoàn và nhanh chóng tiến vào trạng thái không linh gần với ngộ đạo.","anchor":"hắn chỉ vừa mới ngồi xuống thì đã khiến lòng trở nên yên lặng","phamCap":"Không rõ"}]},"capNhatToi":"@c1035","nguon":["@c1035"]},{"id":"doan-mau-dong-gay","name":"Đoạn mâu đồng gãy","cn":"","aliases":["Chiến mâu đồng gãy"],"category":"than-khi","categoryLabel":"Tàn binh Tiên khí","phamCap":"Tàn binh Tiên khí","soHuu":[],"trangThai":"Gãy, còn giữ ý chí Tiên đạo","blurb":"Một đoạn chiến mâu đồng gỉ sét cắm sâu trong Tròng mắt, là tàn binh còn lại sau khi một Tiên khí vỡ nát. Khi thức tỉnh, đoạn mâu bong lớp gỉ, hiện cổ ngữ rực rỡ và bộc phát ý chí Tiên đạo, chấn Tròng mắt thành hai nửa từ bên trong.","detail":"Đoạn mâu đồng gãy từng xuyên thủng, cắm sâu và khiến Tròng mắt trọng thương trong Cấm khu. Tuy chỉ là tàn binh của một Tiên khí đã vỡ nát, nó vẫn lưu giữ ý chí Tiên đạo; đến khi khai phong, lớp gỉ trên thân bong ra, cổ ngữ phát sáng, sức mạnh bộc phát ngay bên trong cơ thể Tròng mắt và phá hủy đối phương từ nội tại. @c1036","phanLoaiPhu":"Chiến mâu đồng gãy","hinhDang":"Một đoạn chiến mâu đồng bị gãy và phủ lớp gỉ sét.","vatLieu":"Đồng","nguonGoc":"Tàn binh còn lại sau khi một Tiên khí vỡ nát.","uyLuc":"Khi ý chí Tiên đạo bộc phát từ bên trong, đoạn mâu có thể chấn Tròng mắt thành hai nửa. @c1036","dacDiem":"Là đoạn chiến mâu bằng đồng đã gãy và phủ gỉ; khi thức tỉnh, lớp gỉ bong ra, để lộ cổ ngữ rực rỡ cùng ý chí Tiên đạo còn sót lại.","chuHienThoi":"Không rõ","congNang":["Mang ý chí Tiên đạo còn sót lại của một Tiên khí đã vỡ nát. @c1036","Bong lớp gỉ, làm hiện cổ ngữ rực rỡ khi thức tỉnh. @c1036","Áp chế và phá hủy Tròng mắt từ bên trong cơ thể. @c1036"],"chuSoHuu":[],"capNhatToi":"@c1036","tabs":{"tienTrinh":[{"chuong":"@c1036","loai":"khai phong","importance":"major","giaiDoan":"Ý chí Tiên đạo thức tỉnh","text":"Đoạn mâu đồng bong lớp gỉ, hiện cổ ngữ và bộc phát ý chí Tiên đạo từ bên trong Tròng mắt, cuối cùng chấn sinh linh này thành hai nửa.","anchor":"Tàn binh như ngươi là do Tiên khí sau khi vỡ nát lưu lại, có ý chí Tiên đạo!","phamCap":"Tàn binh Tiên khí"}]},"nguon":["@c1036"]},{"id":"kiem-thai-dai-la","name":"Kiếm thai Đại La","cn":"","aliases":["Tiên kiếm Đại La"],"category":"phap-bao","categoryLabel":"Tiên kiếm","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"nguyên vẹn","blurb":"Kiếm thai Đại La là cổ kiếm được lấy từ Tiên cổ, từng bị Ngũ Quan vương đánh mất và được đồn do thiên địa sinh ra trong cổ quáng. Kiếm mang dấu tích hiện cảnh phi tiên, có thể cộng hưởng với tàn khí Tiên đạo và từng được Thạch Hạo dùng để triển khai Luân hồi, chém gãy đại kích đỏ lòm rồi tiêu diệt một thủ lĩnh Thiên Thần.","detail":"Kiếm thai Đại La được lấy từ Tiên cổ, từng bị Ngũ Quan vương đánh mất và được đồn là vật do thiên địa sinh ra trong cổ quáng. Khi Thạch Hạo vung kiếm, dấu tích trên thân kiếm hiện ra cảnh phi tiên; kiếm thai cộng hưởng với đoạn mâu đồng gãy, kích phát tàn khí tự hủy, thiêu sạch dấu ấn Tiên đạo và khiến tàn linh của Tròng mắt vừa tiếp xúc đã hóa thành tro @c1037. Những người dự hội còn nhận xét nó rất giống một thanh kiếm từng được tổ sư của họ đề cập @c1038. Về sau, Thạch Hạo lấy kiếm thai làm vật dẫn triển khai phù văn Luân hồi, chém gãy đại kích đỏ lòm và tiêu diệt thủ lĩnh một toán Thiên Thần @c1042.","phanLoaiPhu":"Kiếm thai","nguonGoc":"Được lấy từ Tiên cổ, từng bị Ngũ Quan vương đánh mất và được đồn do thiên địa sinh ra trong cổ quáng.","uyLuc":"Uy lực mạnh nhất đã thể hiện là chém gãy đại kích đỏ lòm và tiêu diệt thủ lĩnh một toán Thiên Thần khi được dùng để triển khai Luân hồi @c1042.","dacDiem":"Trên thân kiếm có dấu tích hiện cảnh phi tiên, có khả năng cộng hưởng với tàn khí Tiên đạo; hình dáng còn được nhận xét rất giống một thanh kiếm từng được tổ sư của những người dự hội đề cập @c1037-@c1038.","chuHienThoi":"Thạch Hạo","congNang":["Cộng hưởng với đoạn mâu đồng gãy, kích phát tàn khí tự hủy và tự thiêu dấu ấn Tiên đạo @c1037.","Khiến tàn linh của Tròng mắt lập tức hóa thành tro khi tiếp xúc @c1037.","Làm vật dẫn để Thạch Hạo triển khai phù văn Luân hồi @c1042.","Chém gãy đại kích đỏ lòm và tiêu diệt thủ lĩnh một toán Thiên Thần @c1042."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1037","denChuong":"","cachCoDuoc":"Đã sở hữu từ trước","trangThai":"đang sở hữu"},{"ten":"Ngũ Quan vương","tuChuong":"@c1037","denChuong":"@c1037","cachCoDuoc":"Từng sở hữu trong Tiên cổ theo thông tin được nhắc lại.","trangThai":"Đã đánh mất"}],"capNhatToi":"@c1037","tabs":{"tienTrinh":[{"chuong":"@c1037","loai":"khai phong","importance":"major","giaiDoan":"Lộ năng lực dị thường","text":"Kiếm thai Đại La cộng hưởng với đoạn mâu đồng gãy, kích phát tàn khí tự hủy và thiêu tàn linh Tròng mắt thành tro.","anchor":"Một luồng tàn linh của Tròng mắt bay ra rồi đánh thẳng lên trên kiếm thai, kết quả, chỉ trong nháy mắt đã hóa thành tro bụi"},{"chuong":"@c1038","loai":"xuất hiện","importance":"normal","giaiDoan":"Lai lịch bị nghi ngờ","text":"Kiếm thai được những người dự hội nhận xét là rất giống một thanh kiếm từng được tổ sư đề cập, dù họ tạm xem nó là hàng mô phỏng.","anchor":"thanh kiếm này rất giống với thanh kiếm mà tổ sư từng đề cập qua","phamCap":"Không rõ"},{"chuong":"@c1042","loai":"dùng","importance":"normal","giaiDoan":"Chém thủ lĩnh Thiên Thần","phamCap":"Không rõ","text":"Thạch Hạo dùng kiếm thai triển khai Luân hồi, chém gãy đại kích đỏ lòm và diệt thủ lĩnh toán Thiên Thần.","anchor":"Được chế tạo từ rất nhiều loại tiên kim"}]},"nguon":["@c1037","@c1038","@c1042"]},{"id":"hat-giong-xanh-biec-cua-thanh-tien","name":"Hạt giống xanh biếc của Thanh Tiên","cn":"","aliases":[],"category":"khac","categoryLabel":"Hạt giống niết bàn","phamCap":"Không rõ","soHuu":["Thanh Tiên"],"trangThai":"Được chôn gần tàn trận","blurb":"Hạt giống xanh biếc như ngọc thạch do Thanh Tiên niết bàn hóa thành sau khi suy yếu. Hạt giống vẫn duy trì sự sống và ý thức của Thanh Tiên, sau đó được Thạch Hạo chôn gần nơi có khí tức Hỗn Độn Thanh Liên.","detail":"Sau khi niết bàn, Thanh Tiên hóa thành một hạt giống xanh biếc nhưng vẫn còn ý thức và có thể truyền âm. Theo nguyện vọng của Thanh Tiên, Thạch Hạo đem hạt giống chôn gần nơi lưu lại khí tức Hỗn Độn Thanh Liên. @c1037","hinhDang":"Hạt giống xanh biếc tựa ngọc thạch.","nguonGoc":"Do Thanh Tiên niết bàn hóa thành.","dacDiem":"Có hình dạng hạt giống xanh biếc như ngọc thạch; vẫn có thể truyền âm sau khi Thanh Tiên hóa thành hạt giống.","chuHienThoi":"Thanh Tiên","congNang":["Duy trì sự sống và ý thức của Thanh Tiên sau khi niết bàn. @c1037","Cho phép Thanh Tiên tiếp tục truyền âm trong trạng thái hạt giống. @c1037"],"chuSoHuu":[{"ten":"Thanh Tiên","tuChuong":"@c1037","denChuong":"","cachCoDuoc":"Là hình thái niết bàn của chính Thanh Tiên.","trangThai":"Được chôn gần khí tức Hỗn Độn Thanh Liên"}],"capNhatToi":"@c1037","tabs":{"tienTrinh":[{"chuong":"@c1037","loai":"xuất hiện","importance":"major","giaiDoan":"Niết bàn thành hạt giống","text":"Thanh Tiên hóa thành hạt giống xanh biếc vẫn còn ý thức, sau đó được Thạch Hạo chôn gần nơi có khí tức Hỗn Độn Thanh Liên.","anchor":"cũng không hề tuyệt diệt mà lại hóa thành một hạt giống xanh biếc tựa như ngọc thạch"}]},"nguon":["@c1037"]},{"id":"chien-y-chan-vu-phuong-hoang","name":"Chiến y chân vũ phượng hoàng","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến y","phamCap":"Không rõ","soHuu":["Hoàng nữ mặc y phục năm màu"],"trangThai":"nguyên vẹn","blurb":"Bộ chiến y hộ thân do chân vũ phượng hoàng hóa thành, được Hoàng nữ mặc khi tới thịnh hội.","detail":"Chiến y mỏng như lụa, tỏa ánh sáng năm màu và lan truyền khí chất siêu nhiên quanh Hoàng nữ.","phanLoaiPhu":"Chiến y hộ thân","hinhDang":"Mỏng như một lớp lụa, tỏa ánh sáng năm màu.","vatLieu":"Chân vũ phượng hoàng","dacDiem":"Do chân vũ phượng hoàng hóa thành và mang khí chất siêu nhiên.","congNang":["Bảo vệ người mặc như một bộ chiến y hộ thân."],"chuHienThoi":"Hoàng nữ mặc y phục năm màu","chuSoHuu":[{"ten":"Hoàng nữ mặc y phục năm màu","tuChuong":"@c1038","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1038","tabs":{"tienTrinh":[{"chuong":"@c1038","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Hoàng nữ mặc","text":"Chiến y do chân vũ phượng hoàng hóa thành xuất hiện trên người Hoàng nữ tại thịnh hội.","anchor":"đó chính là một bộ chiến y do chân vũ của phượng hoàng hóa thành","phamCap":"Không rõ"}]},"nguon":["@c1038"]},{"id":"kiem-pha-tien-kim-quang-minh","name":"Kiếm pha tiên kim Quang Minh","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo kiếm mô phỏng","phamCap":"Không rõ","soHuu":["Chàng trai lưng mang kiếm tiên kim Quang Minh"],"trangThai":"nguyên vẹn","blurb":"Một thanh kiếm mô phỏng binh khí của Tiên vương, thuộc sở hữu của chàng trai cùng dự thịnh hội.","detail":"Chủ nhân thừa nhận thanh kiếm là hàng mô phỏng, nhưng bên trong có trộn sáu lạng tiên kim Quang Minh.","phanLoaiPhu":"Bảo kiếm mô phỏng","vatLieu":"Pha sáu lạng tiên kim Quang Minh","nguonGoc":"Mô phỏng binh khí của một vị Tiên vương.","dacDiem":"Bên trong trộn sáu lạng tiên kim Quang Minh.","chuHienThoi":"Chàng trai lưng mang kiếm tiên kim Quang Minh","chuSoHuu":[{"ten":"Chàng trai lưng mang kiếm tiên kim Quang Minh","tuChuong":"@c1038","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1038","tabs":{"tienTrinh":[{"chuong":"@c1038","loai":"xuất hiện","importance":"normal","giaiDoan":"Hé lộ vật liệu","text":"Chủ nhân giới thiệu thanh kiếm là bản mô phỏng binh khí Tiên vương và cho biết nó có pha tiên kim Quang Minh.","anchor":"bên trong có trộn lẫn sáu lạng tiên kim Quang Minh","phamCap":"Không rõ"}]},"nguon":["@c1038"]},{"id":"chuong-lon-cua-vo-chung","name":"Chuông lớn của Vô Chung","cn":"","aliases":["Đại chuông của Vô Chung","Chiếc chuông thời gian của Vô Chung"],"category":"phap-bao","categoryLabel":"Chuông","phamCap":"Không rõ","soHuu":["Vô Chung"],"trangThai":"nguyên vẹn","blurb":"Chiếc đại chuông đưa Vô Chung vượt ngang chân trời tới thịnh hội Nam Hải.","detail":"Đại chuông phát ra tiếng ngân nhẹ nhàng, khiến người nghe có cảm giác được dẫn dắt tiến vào trạng thái ngộ đạo.","phanLoaiPhu":"Chuông","congNang":["Phát tiếng chuông nhẹ nhàng gợi người nghe ngộ đạo."],"uyLuc":"Có thể vượt ngang chân trời và đưa Vô Chung tới Nam Hải Tử Trúc lâm.","dacDiem":"Tiếng chuông nhẹ nhàng mang ý vị dẫn dắt ngộ đạo.","chuHienThoi":"Vô Chung","chuSoHuu":[{"ten":"Vô Chung","tuChuong":"@c1038","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1038","tabs":{"tienTrinh":[{"chuong":"@c1038","loai":"dùng","importance":"normal","giaiDoan":"Đưa Vô Chung tới hội","text":"Đại chuông vượt ngang chân trời tới Nam Hải và phát tiếng ngân nhẹ nhàng gợi người nghe ngộ đạo.","anchor":"tiếng chuông rất nhẹ nhàng như muốn người khác ngộ đạo","phamCap":"Không rõ"}]},"nguon":["@c1038"]},{"id":"cung-dien-ngoc-tren-lung-ran-tam-dau","name":"Cung điện ngọc trên lưng rắn tám đầu","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Cung điện","phamCap":"Không rõ","soHuu":["Chân Tiên cưỡi rắn tám đầu"],"trangThai":"nguyên vẹn","blurb":"Một tòa cung điện bằng ngọc được rắn tám đầu cõng tới vùng biển Nam Hải.","detail":"Cung điện nằm trên lưng sinh linh tám đầu và tỏa ánh sáng lung linh khi chở Chân Tiên bay vào khu vực thịnh hội.","phanLoaiPhu":"Cung điện di chuyển","hinhDang":"Tòa cung điện bằng ngọc tỏa sáng.","vatLieu":"Ngọc","dacDiem":"Được rắn tám đầu cõng trên lưng.","chuHienThoi":"Chân Tiên cưỡi rắn tám đầu","chuSoHuu":[{"ten":"Chân Tiên cưỡi rắn tám đầu","tuChuong":"@c1038","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1038","tabs":{"tienTrinh":[{"chuong":"@c1038","loai":"xuất hiện","importance":"normal","giaiDoan":"Được đưa tới Nam Hải","text":"Cung điện ngọc được rắn tám đầu cõng trên lưng khi đưa một Chân Tiên tới thịnh hội.","anchor":"trên lưng của nó có cõng một tòa cung điện bằng ngọc","phamCap":"Không rõ"}]},"nguon":["@c1038"]},{"id":"mo-hinh-vu-tru-cua-hoang-nu","name":"Mô hình vũ trụ của Hoàng nữ","cn":"","category":"khac","categoryLabel":"Tiên chủng","phamCap":"Không rõ","soHuu":["Hoàng nữ mặc y phục năm màu"],"trangThai":"Đã dung hợp vào cơ thể Hoàng nữ","blurb":"Mô hình vũ trụ được Hoàng nữ tìm thấy, luyện hóa và dung hợp vào cơ thể để làm Tiên chủng. Nhờ con đường này, nàng tu thành ba luồng tiên khí.","detail":"Vật này mang hình thức ban đầu của một vũ trụ. Sau khi tìm được, Hoàng nữ đã luyện hóa rồi dung hợp nó vào cơ thể, biến nó thành Tiên chủng của bản thân; nhờ đó, nàng tu thành ba luồng tiên khí. @c1039","phanLoaiPhu":"Tiên chủng","hinhDang":"Mô hình vũ trụ","dacDiem":"Mang hình thức ban đầu của một vũ trụ.","chuHienThoi":"Hoàng nữ mặc y phục năm màu","congNang":["Sau khi được luyện hóa và dung hợp vào cơ thể, có thể làm Tiên chủng, giúp Hoàng nữ tu thành ba luồng tiên khí. @c1039"],"chuSoHuu":[{"ten":"Hoàng nữ mặc y phục năm màu","tuChuong":"@c1039","denChuong":"","cachCoDuoc":"Tìm được rồi luyện hóa và dung hợp vào cơ thể","trangThai":"đang sở hữu"}],"capNhatToi":"@c1039","tabs":{"tienTrinh":[{"chuong":"@c1039","loai":"đổi chủ","importance":"major","giaiDoan":"Dung hợp thành Tiên chủng","text":"Hoàng nữ xác nhận đã luyện hóa mô hình vũ trụ và dung hợp nó vào cơ thể làm Tiên chủng.","anchor":"Ta từng tìm được một tấm mô hình vũ trụ rồi luyện hóa, dung hợp vào trong cơ thể mình","phamCap":"Không rõ"}]},"nguon":["@c1039"]},{"id":"bao-kiem-tien-kim-quang-minh","name":"Bảo kiếm tiên kim Quang Minh","cn":"","category":"phap-bao","categoryLabel":"Bảo kiếm","phamCap":"Không rõ","soHuu":["Chàng trai lưng mang kiếm tiên kim Quang Minh"],"trangThai":"Nguyên vẹn","blurb":"Bảo kiếm được luyện từ tiên kim Quang Minh, do một thanh niên Tiên cổ mang theo khi luận bàn với Thạch Hạo.","detail":"Thanh niên đeo kiếm sau lưng và cầm nó trong lúc luận bàn đạo pháp với Thạch Hạo. Chương này xác nhận vật liệu của kiếm nhưng chưa thể hiện uy lực cụ thể.","phanLoaiPhu":"Bảo kiếm","vatLieu":"Tiên kim Quang Minh","chuHienThoi":"Chàng trai lưng mang kiếm tiên kim Quang Minh","chuSoHuu":[{"ten":"Chàng trai lưng mang kiếm tiên kim Quang Minh","tuChuong":"@c1039","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1039","tabs":{"tienTrinh":[{"chuong":"@c1039","loai":"xuất hiện","importance":"normal","giaiDoan":"Mang theo khi luận đạo","text":"Bảo kiếm tiên kim Quang Minh xuất hiện trong tay chàng trai khi hắn luận bàn với Thạch Hạo.","anchor":"thanh niên cầm bảo kiếm được luyện từ tiên kim Quang Minh luận bàn với Thạch Hạo","phamCap":"Không rõ"}]},"nguon":["@c1039"]},{"id":"hoang-cot-nam-mau","name":"Hoàng cốt năm màu","cn":"","aliases":[],"category":"khac","categoryLabel":"Di cốt","phamCap":"","soHuu":["Hoàng nữ mặc y phục năm màu"],"trangThai":"đã được mai táng","blurb":"Đoạn di cốt lấp lánh năm màu còn lưu khí tức quen thuộc của Hoàng nữ.","detail":"Thạch Hạo tìm thấy Hoàng cốt dưới vùng đất hoang tàn tại Nam Hải Tử Trúc lâm. Hắn nhận ra chủ nhân nhờ khí tức quen thuộc rồi chôn đoạn xương trong một ngôi mộ riêng.","phanLoaiPhu":"di cốt","hinhDang":"Một khúc xương lấp lánh ánh sáng năm màu.","dacDiem":"Còn lưu khí tức của Hoàng nữ.","chuHienThoi":"Hoàng nữ mặc y phục năm màu","capNhatToi":"@c1041","congNang":[],"chuSoHuu":[{"ten":"Hoàng nữ mặc y phục năm màu","tuChuong":"@c1041","denChuong":"@c1041","cachCoDuoc":"Di cốt của chính nàng.","trangThai":"được Thạch Hạo mai táng"}],"tabs":{"tienTrinh":[{"chuong":"@c1041","loai":"xuất hiện","importance":"normal","giaiDoan":"Được tìm thấy và mai táng","text":"Thạch Hạo tìm thấy Hoàng cốt dưới đất, nhận ra khí tức của Hoàng nữ và chôn nó trong một ngôi mộ riêng.","anchor":"nó là của Hoàng nữ! Đã từng luận bàn, từng giao lưu"}]},"nguon":["@c1041"]},{"id":"tam-da-thu-rach","name":"Tấm da thú rách","cn":"","aliases":[],"category":"khac","categoryLabel":"Di vật nguy hiểm","phamCap":"","soHuu":[],"trangThai":"tự bay sâu vào núi rừng","blurb":"Tấm da thú rách còn sót những sợi lông có thể hóa thành thần châm màu vàng.","detail":"Những thần châm do lông thú biến thành xuyên thủng núi non, mặt đất và hư không. Thạch Hạo không thể tiếp cận thu giữ, còn tấm da dường như tự tạo cuồng phong rồi bay sâu vào núi rừng.","phanLoaiPhu":"di vật từ sinh linh chưa rõ","hinhDang":"Một tấm da thú đã rách, trên bề mặt còn sót lông thú.","uyLuc":"Thần châm vàng có thể xuyên thủng vật cản và đe dọa cả tu sĩ cấp Giáo chủ.","dacDiem":"Dường như có thể tự tạo cuồng phong để di chuyển.","capNhatToi":"@c1041","congNang":["Các sợi lông thú có thể hóa thành thần châm màu vàng xuyên thủng núi non và hư không."],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1041","loai":"xuất hiện","importance":"normal","giaiDoan":"Tập kích trong Cấm khu","text":"Lông trên tấm da thú hóa thành thần châm vàng tập kích Thạch Hạo, sau đó tấm da tự bay sâu vào núi rừng.","anchor":"có những cọng lông thú rớt xuống và hóa thành những thần châm màu vàng"}]},"nguon":["@c1041"]},{"id":"than-moc-chay-den-chua-loi-dien","name":"Thần mộc cháy đen chứa lôi điện","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Vật liệu Lôi đạo nguy hiểm","phamCap":"","soHuu":[],"trangThai":"phát nổ khi bị thăm dò","blurb":"Cây thần mộc bị sét đánh cháy đen nhưng vẫn đứng vững, bên trong chứa lôi điện hủy diệt.","detail":"Bề ngoài của thần mộc khiến Thạch Hạo tưởng đây là vật liệu quý để luyện bảo cụ Lôi đạo. Khi một pháp khí được dùng thăm dò từ xa, cây bộc phát lôi điện phá hủy hư không và mặt đất trong phạm vi trăm dặm.","phanLoaiPhu":"thần mộc Lôi đạo","hinhDang":"Một cây thần thụ cháy đen nhưng không đổ.","uyLuc":"Lôi điện bộc phát đủ sức giết tu sĩ cấp Giáo chủ.","dacDiem":"Ẩn chứa sức hủy diệt cực lớn dưới vẻ ngoài của một vật liệu luyện bảo.","capNhatToi":"@c1041","congNang":["Bộc phát lôi điện phá nát hư không và mặt đất trong phạm vi trăm dặm."],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1041","loai":"xuất hiện","importance":"normal","giaiDoan":"Bộc phát lôi điện","text":"Thần mộc phát nổ khi bị pháp khí thăm dò, tạo ra lôi điện đủ sức phá hủy phạm vi trăm dặm.","anchor":"Phạm vi trăm dặm thì hư không nổ tung"}]},"nguon":["@c1041"]},{"id":"dai-kich-do-lom","name":"Đại kích đỏ lòm","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phanLoaiPhu":"Đại kích","phamCap":"Chuẩn Giáo chủ","soHuu":["Thủ lĩnh toán Thiên Thần"],"trangThai":"bị chém gãy","blurb":"Đại kích đỏ lòm của thủ lĩnh toán Thiên Thần là binh khí đạt cấp chuẩn Giáo chủ.","detail":"Binh khí mang phù văn cấp Giáo chủ và từng được đại nhân vật tế luyện. Nó làm suy yếu sức mạnh Luân hồi nhưng cuối cùng bị kiếm thai Đại La chém gãy.","nguonGoc":"Từng được đại nhân vật tế luyện","dacDiem":"Mang phù văn cấp Giáo chủ.","chuHienThoi":"Thủ lĩnh toán Thiên Thần","chuSoHuu":[{"ten":"Thủ lĩnh toán Thiên Thần","tuChuong":"@c1042","denChuong":"@c1042","cachCoDuoc":"","trangThai":"bị chém gãy"}],"tabs":{"tienTrinh":[{"chuong":"@c1042","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị kiếm thai chém gãy","phamCap":"Chuẩn Giáo chủ","text":"Đại kích chống lại kiếm thai Đại La trong cuộc giao chiến nhưng bị chém sâu nhiều lần rồi gãy nát.","anchor":"Là binh khí đạt cấp chuẩn Giáo chủ"}]},"capNhatToi":"@c1042","nguon":["@c1042"]},{"id":"la-bua-mau-den","name":"Lá bùa màu đen","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Phù bảo","phamCap":"Không rõ","soHuu":["Thủ lĩnh toán Thiên Thần"],"trangThai":"đã phát nổ","blurb":"Phù bảo màu đen được thủ lĩnh toán Thiên Thần dùng để ngăn kiếm thai Đại La.","detail":"Khi bị kiếm thai chém trúng, lá bùa phát nổ như một vầng thái dương đen và khiến khí huyết của Thạch Hạo cuộn trào.","uyLuc":"Vụ nổ khiến Thạch Hạo khí huyết cuộn trào.","chuHienThoi":"Thủ lĩnh toán Thiên Thần","congNang":["Phát nổ dữ dội khi bị công kích."],"chuSoHuu":[{"ten":"Thủ lĩnh toán Thiên Thần","tuChuong":"@c1042","denChuong":"@c1042","cachCoDuoc":"","trangThai":"đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1042","loai":"dùng","importance":"normal","giaiDoan":"Phát nổ chặn kiếm","phamCap":"Không rõ","text":"Thủ lĩnh phun lá bùa ra chặn kiếm thai, khiến nó phát nổ như một vầng thái dương đen.","anchor":"Nó ngay lập tức nổ tung tựa như là vầng thái dương đen ngòm nổ mạnh"}]},"capNhatToi":"@c1042","nguon":["@c1042"]},{"id":"qua-trung-ky-lan","name":"Quả trứng Kỳ lân","cn":"","category":"khac","categoryLabel":"Vật phẩm được đồn đại","phamCap":"Không rõ","soHuu":[],"trangThai":"Chưa xác nhận","blurb":"Cơ duyên được đồn là một quả trứng Kỳ lân thuần huyết xuất hiện quanh thành trì gần Biên hoang.","detail":"Lời đồn về quả trứng khiến đông đảo tu sĩ lưu lại tìm kiếm. Chưa xác định quả trứng có quan hệ thế nào với Kỳ lân con màu trắng xuất hiện trong dị tượng.","nguon":["@c1043"]},{"id":"chi-bao-tien-co-cua-ky-lan-con","name":"Chí bảo Tiên cổ của Kỳ lân con","cn":"","category":"phap-bao","categoryLabel":"Chí bảo","phamCap":"Tiên cổ","soHuu":["Kỳ lân con màu trắng"],"trangThai":"Đang được Kỳ lân con mang theo","blurb":"Chí bảo chưa rõ tên và hình dạng, có khả năng che giấu Kỳ lân con khỏi sự tìm kiếm.","detail":"Kỳ lân con dùng vật này để che giấu chân thân và tung tích, khiến những người đang săn tìm nó không thể phát hiện.","congNang":["Ẩn giấu chân thân và tung tích của Kỳ lân con."],"chuHienThoi":"Kỳ lân con màu trắng","chuSoHuu":[{"ten":"Kỳ lân con màu trắng","tuChuong":"@c1044","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1044","loai":"xuất hiện","importance":"normal","giaiDoan":"Che giấu Kỳ lân con","text":"Chí bảo giúp Kỳ lân con giấu chân thân, khiến những người khác không thể tìm được nó.","anchor":"người khác không cách nào tìm được nó đâu, bởi vì trên người nó có một chí bảo Tiên cổ","phamCap":"Tiên cổ"}]},"capNhatToi":"@c1044","nguon":["@c1044"]},{"id":"huyet-te-dan","name":"Huyết Tế Đàn","cn":"","aliases":["Tế đàn máu trong núi đá"],"category":"phap-bao","categoryLabel":"Tế đàn","phamCap":"Không rõ","soHuu":["Các đội Thiên Thần ma hóa trong Cấm khu"],"trangThai":"Đã được kích hoạt","blurb":"Tế đàn nhuộm máu ẩn trong một ngọn núi đá tại Cấm khu. Nó tiếp nhận máu huyết Thiên Thần và làm môi giới liên lạc với sinh linh bên kia Biên hoang.","detail":"Tế đàn lộ ra khi ngọn núi đá nứt toác trong nghi thức triệu gọi. Sau khi nhận huyết tế, nó truyền tới giọng nói của một sinh linh trẻ tuổi từ phía bên kia Biên hoang.","hinhDang":"Tế đàn nhuộm máu đỏ, ẩn trong núi đá","congNang":["Tiếp nhận máu huyết Thiên Thần làm vật hiến tế.","Làm môi giới gọi sinh linh bên kia Biên hoang."],"tabs":{"tienTrinh":[{"chuong":"@c1044","loai":"dùng","importance":"normal","giaiDoan":"Nhận huyết tế","text":"Tế đàn lộ ra từ núi đá, nhận máu huyết Thiên Thần và truyền tới lời đáp của sinh linh bên kia Biên hoang.","anchor":"có một ngọn núi đá nứt toác và lộ ra một tế đàn được nhuộm bởi máu đỏ","phamCap":"Không rõ"}]},"capNhatToi":"@c1044","nguon":["@c1044"]},{"id":"ken-lenh-oc-bien","name":"Kèn lệnh ốc biển","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ (cổ khí chiến tranh)","soHuu":[],"trangThai":"di-tich","blurb":"Cổ khí chiến tranh từ cuộc chiến hơn một kỷ nguyên trước, dấu ấn còn lưu lại tái hiện uy thế làm trời đất tan vỡ và ngân hà run rẩy.","detail":"Kèn lệnh dùng phát lệnh mở màn đại chiến thời Tiên cổ. Dấu ấn của nó tái hiện cảnh trời đất nổ tung, ác điểu và thần thú rơi xuống. Nhiều kèn lệnh cùng vang có thể chấn động cả vũ trụ. Chỉ còn lại dấu ấn tại biển cổ chiến trường trong Cấm khu.","congNang":["Phát lệnh mở màn đại chiến, tạo uy thế làm trời long đất lở và ngân hà run rẩy"],"tabs":{"tienTrinh":[{"chuong":"@c1046","loai":"xuất hiện","importance":"normal","giaiDoan":"Dấu ấn tái hiện tại biển cổ chiến trường","text":"Dấu ấn kèn lệnh tái hiện cảnh trời đất tan vỡ tại vùng biển chắn đường tới Đế thành. Ma nữ giải thích đây là phần mở màn của cuộc chiến hơn một kỷ nguyên trước.","anchor":"Cuộc chiến hơn kỷ nguyên trước, kèn lệnh vang lên thì sẽ có cảnh tượng như thế"}]},"nguon":["@c1046"]},{"id":"tran-hon-chau","name":"Trấn Hồn châu","cn":"镇魂珠","aliases":["Thạch châu của Ma nữ","Thạch châu thần bí của Ma nữ"],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Siêu phàm","soHuu":["Ma nữ"],"trangThai":"dang-co","blurb":"Trấn Hồn châu là viên thạch châu do Ma nữ sở hữu, có khả năng chặn và áp chế tàn hồn trong hài cốt cổ đại. Nó từng thu hút sự chú ý của một khung xương trắng có sức mạnh vượt Thiên Thần, khiến đối phương ngừng tấn công.","detail":"Ma nữ đã sử dụng Trấn Hồn châu khi đối diện khung xương trắng có sức mạnh vượt Thiên Thần. Viên châu chặn đứng bộ xương và thu hút sự chú ý của nó, qua đó khiến di hài ngừng tấn công. @c1046","congNang":["Chặn và áp chế tàn hồn trong hài cốt cổ đại. @c1046","Thu hút sự chú ý của di hài, khiến chúng ngừng tấn công. @c1046"],"chuSoHuu":[{"ten":"Ma nữ","tuChuong":"@c1046","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1046","loai":"dùng","importance":"major","giaiDoan":"Chặn khung xương trắng trong biển dung nham","text":"Ma nữ dùng Trấn Hồn châu chặn đứng khung xương trắng sức mạnh vượt Thiên Thần. Bộ xương bị viên châu thu hút, chăm chú nhìn rồi từ từ nằm xuống biển dung nham và biến mất.","anchor":"Cũng may là Trấn Hồn châu rất siêu phàm"}]},"nguon":["@c1046"],"uyLuc":"Từng chặn đứng một khung xương trắng có sức mạnh vượt Thiên Thần. @c1046","dacDiem":"Một viên thạch châu do Ma nữ sở hữu."},{"id":"tan-binh-duoi-bien-dung-nham","name":"Tàn binh dưới biển dung nham","cn":"","category":"phap-bao","categoryLabel":"Tàn khí","phamCap":"Không rõ","soHuu":[],"trangThai":"Nằm dưới đáy biển dung nham","blurb":"Những mảnh binh khí lạnh lẽo nằm dưới biển dung nham, gần các bộ Đế cốt.","detail":"Tàn binh tỏa ra khí thế đáng sợ, có khả năng xé rách tinh vũ. Thạch Hạo và Ma nữ không dám tiếp cận vì lo việc thu lấy chúng sẽ kích thích Đế cốt và gây ra tai họa.","phanLoaiPhu":"Tàn khí","uyLuc":"Khí thế từ những mảnh binh khí có thể xé rách tinh vũ.","dacDiem":"Dù ở rất xa vẫn có thể cảm nhận sự lạnh lẽo tỏa ra.","congNang":["Tỏa ra khí thế và cảm giác lạnh lẽo từ dưới biển dung nham."],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1047","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện","text":"Thạch Hạo và Ma nữ phát hiện những tàn binh đáng sợ nhưng không dám tiếp cận hay thu lấy.","anchor":"dù cách rất xa thế nhưng vẫn có thể cảm nhận được sự lạnh lẽo toát ra từ chúng","phamCap":"Không rõ"}]},"capNhatToi":"@c1047","nguon":["@c1047"]},{"id":"dai-bong-lang-nha-cua-quai-vat-mot-chan","name":"Đại bổng Lang Nha của quái vật một chân","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Quái vật một chân"],"trangThai":"Theo quái vật một chân biến mất","blurb":"Cây đại bổng dài hàng ngàn trượng do quái vật một chân sử dụng trong cổ thành Chân Hoàng.","detail":"Quái vật một chân dùng đại bổng Lang Nha phá nát hàng loạt nhà cửa và cây ngô đồng. Những kiến trúc có trận pháp sau đó tự khôi phục.","phanLoaiPhu":"Binh khí dạng bổng","hinhDang":"Cây bổng Lang Nha dài hàng ngàn trượng.","uyLuc":"Có thể phá hủy hàng loạt kiến trúc trong cổ thành.","chuHienThoi":"Quái vật một chân","congNang":["Phá hủy nhà cửa và cây ngô đồng trong cổ thành Chân Hoàng."],"chuSoHuu":[{"ten":"Quái vật một chân","tuChuong":"@c1047","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu khi xuất hiện"}],"tabs":{"tienTrinh":[{"chuong":"@c1047","loai":"dùng","importance":"normal","giaiDoan":"Tàn phá cổ thành","text":"Quái vật một chân vung đại bổng Lang Nha để phá hủy hàng loạt kiến trúc và cây ngô đồng.","anchor":"Đại bổng Lang Nha dài tới mấy ngàn tượng vụt sát ngay trên đỉnh đầu bọn họ","phamCap":"Không rõ"}]},"capNhatToi":"@c1047","nguon":["@c1047"]},{"id":"trung-tien","name":"Trứng Tiên","cn":"","aliases":["Quả trứng nghi Phượng Hoàng"],"category":"khac","categoryLabel":"Trứng sinh linh","phamCap":"Không rõ","soHuu":[],"trangThai":"Nằm trong động phủ hỗn độn","blurb":"Quả trứng khổng lồ được phát hiện trong động phủ liên thông với cổ thành Chân Hoàng. Thạch Hạo và Ma nữ nghi nó thuộc về Phượng Hoàng nhưng chưa thể xác nhận.","detail":"Quả trứng nằm giữa hỗn độn khí và tiên quang, tỏa ra sinh cơ cùng lượng lớn tinh khí sinh mệnh. Khí tức của nó khiến Thạch Hạo liên tưởng tới Hoàng nữ từng tu thành ba luồng tiên khí.","phanLoaiPhu":"Trứng sinh linh thần bí","hinhDang":"Quả trứng khổng lồ và lấp lánh.","dacDiem":"Tỏa ra sinh cơ mạnh mẽ và lượng lớn tinh khí sinh mệnh.","congNang":["Tỏa ra sinh cơ và tinh khí sinh mệnh mạnh mẽ."],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1047","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện","text":"Thạch Hạo và Ma nữ phát hiện quả trứng tỏa sinh cơ mạnh mẽ trong động phủ hỗn độn và nghi nó thuộc về Phượng Hoàng.","anchor":"Rất nhanh, bọn họ cảm nhận được một luồng sinh cơ rất mạnh mẽ, từ trong quả trứng ấy tản ra lượng lớn tinh khí sinh mệnh","phamCap":"Không rõ"}]},"capNhatToi":"@c1047","nguon":["@c1047"]},{"id":"giot-mau-trong-van-vat-tho","name":"Giọt máu trong Vạn Vật thổ","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm thần bí","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Đã thức tỉnh khi tới gần Đế thành Cấm khu","blurb":"Giọt máu thần bí được mang ra từ di địa Tiên cổ và từng chôn sâu dưới Vạn Vật thổ. Nó hiện ra trên người Thạch Hạo và thức tỉnh khi hắn tiến gần Đế thành Cấm khu.","detail":"Giọt máu có nguồn gốc từ di địa Tiên cổ, từng được chôn sâu dưới Vạn Vật thổ. Khi Thạch Hạo tiến gần Đế thành Cấm khu, nó hiện ra trên người hắn rồi thức tỉnh, phát ra ánh sáng chiếu rọi chư thiên vạn cổ cùng khí thế xuyên suốt cổ kim. @c1048","congNang":["Phản ứng, hiện ra trên người Thạch Hạo và thức tỉnh khi tới gần Đế thành Cấm khu. @c1048"],"uyLuc":"Khi thức tỉnh, giọt máu phát ra ánh sáng chiếu rọi chư thiên vạn cổ cùng khí thế xuyên suốt cổ kim.","dacDiem":"Từng chôn sâu dưới Vạn Vật thổ; có thể chiếu rọi chư thiên vạn cổ.","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1048","denChuong":"","cachCoDuoc":"Giọt máu được mang khỏi di địa Tiên cổ và từng chôn dưới Vạn Vật thổ.","trangThai":"Đang mang theo"}],"tabs":{"tienTrinh":[{"chuong":"@c1048","loai":"khai phong","importance":"major","giaiDoan":"Thức tỉnh gần Đế thành","text":"Giọt máu hiện ra trên người Thạch Hạo và thức tỉnh khi hắn tiến gần Đế thành Cấm khu.","anchor":"Nó hiện ra trên người của hắn rồi chiếu rọi chư thiên vạn cổ","phamCap":"Không rõ"}]},"capNhatToi":"@c1048","nguon":["@c1048"]},{"id":"bia-da-minh-uoc-thai-co","name":"Bia đá Minh ước Thái cổ","cn":"","category":"khac","categoryLabel":"Bia quy tắc","phamCap":"Không rõ","soHuu":[],"trangThai":"Đặt ngoài Đế thành","blurb":"Bia đá ghi điều kiện tiến vào Đế thành và cảnh báo hậu quả dành cho người cưỡng ép vượt qua.","detail":"Nội dung trên bia xác nhận chỉ người đã ký Minh ước Thái cổ mới được vào Đế thành. Những người khác nếu cố ý vượt qua sẽ bị trận pháp tiêu diệt cả hình lẫn thần.","phanLoaiPhu":"Bia thông báo cấm chế","congNang":["Thông báo quy tắc ra vào Đế thành.","Cảnh báo hậu quả đối với người chưa ký Minh ước Thái cổ."],"dacDiem":"Gắn với điều kiện của Minh ước Thái cổ.","capNhatToi":"@c1049","tabs":{"tienTrinh":[{"chuong":"@c1049","loai":"xuất hiện","importance":"normal","giaiDoan":"Công bố quy tắc cấm thành","text":"Bia đá xác nhận chỉ người đã ký Minh ước Thái cổ mới được phép tiến vào Đế thành.","anchor":"chỉ có người đã ký Minh ước Thái cổ thì mới có thể đi vào","phamCap":"Không rõ"}]},"nguon":["@c1049"]},{"id":"te-dan-thong-suot-hai-gioi","name":"Tế đàn thông suốt hai giới","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn","phamCap":"Không rõ","soHuu":[],"trangThai":"bị phá hủy","blurb":"Tế đàn thông suốt hai giới là phương tiện có khả năng kết nối hai giới, từng nằm trên con đường Thạch Hạo đi tới biên hoang. Thạch Hạo đã phá hủy tế đàn và tiết lộ sự việc với một vị Chí Tôn trung niên, khiến người này chấn động và yêu cầu giữ kín tin tức để tránh gây hoảng loạn.","detail":"Tế đàn từng tồn tại trên đường tới biên hoang và có thể thông suốt hai giới, tạo thành đường vượt qua giữa hai bên. Thạch Hạo đã phá hủy nó, sau đó bí mật báo lại cho vị Chí Tôn trung niên; sự tồn tại của tế đàn khiến vị Chí Tôn này chấn động và yêu cầu hắn giữ kín chuyện nhằm tránh gây hoảng loạn. @c1051","phanLoaiPhu":"Tế đàn vượt giới","congNang":["Kết nối, thông suốt hai giới để tạo đường vượt qua. @c1051"],"chuHienThoi":"Không có","capNhatToi":"@c1051","tabs":{"tienTrinh":[{"chuong":"@c1051","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","text":"Thạch Hạo tiết lộ rằng hắn đã phá hủy tế đàn có thể thông suốt hai giới trên đường tới biên hoang.","anchor":"còn nói ra ở trên đường hủy diệt một toà có thể thông suốt hai giới tế đàn sự","phamCap":"Không rõ"}]},"nguon":["@c1051"],"dacDiem":"Từng nằm trên con đường đi tới biên hoang và đã bị Thạch Hạo phá hủy. @c1051"},{"id":"co-giac-cua-long-nu","name":"Cổ giác của Long nữ","cn":"","category":"phap-bao","categoryLabel":"Bí bảo thông linh","phamCap":"Không rõ","soHuu":["Long nữ"],"trangThai":"Đang được Long nữ sở hữu","blurb":"Một viên cổ giác có khả năng thông linh và hiển lộ cảnh vật.","detail":"Long nữ dùng cổ giác để quan sát cảnh vật từ xa, qua đó phát hiện Ninh Xuyên đã biến mất và biết Trích Tiên cùng Thập Quan vương đang truy theo.","phanLoaiPhu":"Bí bảo thông linh","congNang":["Thông linh và hiển lộ một số cảnh vật tại @c1052."],"dacDiem":"Có thể cung cấp dấu vết về người và sự việc ở nơi khác.","chuHienThoi":"Long nữ","chuSoHuu":[{"ten":"Long nữ","tuChuong":"@c1052","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1052","loai":"dùng","importance":"normal","giaiDoan":"Thông linh truy dấu","text":"Long nữ dùng cổ giác hiển lộ cảnh vật và phát hiện cuộc truy đuổi Ninh Xuyên.","anchor":"trên người nàng có một viên cổ giác, có thể thông linh, lộ ra ra một ít cảnh vật","phamCap":"Không rõ"}]},"capNhatToi":"@c1052","nguon":["@c1052"]},{"id":"xich-huyet-thien-mau","name":"Xích huyết thiên mâu","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"","soHuu":["Kẻ cầm Xích huyết thiên mâu"],"trangThai":"hong","blurb":"Xích huyết thiên mâu là một cây thiên mâu màu đỏ máu, được tu sĩ vực ngoại dùng để ngăn cản Ninh Xuyên. Trong cuộc giao phong, pháp bảo bị Kỳ Lân ấn đánh nổ thành nhiều đoạn, còn mảnh lưỡi quay ngược đâm trọng thương chính người sử dụng.","detail":"Xích huyết thiên mâu xuất hiện trong tay một tu sĩ vực ngoại và được dùng làm binh khí để ngăn cản Ninh Xuyên. Tuy nhiên, nó không chống nổi Kỳ Lân ấn, bị đánh nổ thành nhiều đoạn; sau khi vỡ, mảnh lưỡi sắc quay ngược lại và đâm trọng thương người sử dụng. @c1053","phanLoaiPhu":"Mâu","hinhDang":"Cây mâu màu đỏ máu với lưỡi sắc.","uyLuc":"Không chống nổi Kỳ Lân ấn và bị phá hủy ngay trong cuộc giao phong. @c1053","dacDiem":"Thiên mâu có màu đỏ máu; sau khi bị đánh vỡ, mảnh lưỡi quay ngược đâm trọng thương người sử dụng. @c1053","chuHienThoi":"Kẻ cầm Xích huyết thiên mâu","congNang":["Được dùng làm binh khí để ngăn cản Ninh Xuyên."],"chuSoHuu":[{"ten":"Kẻ cầm Xích huyết thiên mâu","tuChuong":"@c1053","denChuong":"@c1053","cachCoDuoc":"","trangThai":"Binh khí bị phá hủy"}],"tabs":{"tienTrinh":[{"chuong":"@c1053","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị Kỳ Lân ấn phá hủy","phamCap":"","text":"Xích huyết thiên mâu bị Kỳ Lân ấn đánh nổ thành nhiều đoạn, còn mảnh lưỡi quay ngược đâm trọng thương người sử dụng.","anchor":"Đặc biệt thiên mâu lưỡi dao sắc, ngã: cũng toàn mà đi, phù một tiếng đâm vào người kia trong thân thể"}]},"capNhatToi":"@c1053","nguon":["@c1053"]},{"id":"hoang-kim-truong-thuong","name":"Hoàng kim trường thương","cn":"","category":"than-khi","categoryLabel":"Thần binh","phamCap":"Có pha Hoàng Đạo Tiên Kim","soHuu":["Chàng trai tóc vàng"],"trangThai":"Bị phá hủy","blurb":"Hoàng kim trường thương là binh khí của chàng trai tóc vàng, trong thân thương có pha Hoàng Đạo Tiên Kim. Sau khi va chạm với Kiếm thai Đại La, tinh hoa trong thương bị hút sạch, khiến binh khí vỡ thành những mảnh kim loại.","detail":"Hoàng kim trường thương có độ sắc bén đủ để uy hiếp Thiên Thần. Khi giao phong với Kiếm thai Đại La, thân thương bị chém nứt, toàn bộ tinh hoa Hoàng Đạo Tiên Kim bị kiếm thai hấp thu, phần còn lại sau đó vỡ vụn trên mặt đất. @c1054","phanLoaiPhu":"Trường thương","vatLieu":"Có pha Hoàng Đạo Tiên Kim","uyLuc":"Được mô tả đủ sắc bén để đóng đinh Thiên Thần.","dacDiem":"Trong thân thương có pha tinh hoa Hoàng Đạo Tiên Kim; tinh hoa này có thể bị Kiếm thai Đại La hấp thu. Sau khi mất hết tinh hoa, trường thương vỡ thành vụn kim loại. @c1054","chuHienThoi":"Chàng trai tóc vàng","chuSoHuu":[{"ten":"Chàng trai tóc vàng","tuChuong":"@c1054","denChuong":"@c1054","cachCoDuoc":"Không rõ","trangThai":"Mất do binh khí bị phá hủy"}],"congNang":["Dùng làm binh khí công kích, có độ sắc bén đủ để uy hiếp Thiên Thần."],"tabs":{"tienTrinh":[{"chuong":"@c1054","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị hút tinh hoa và phá hủy","text":"Hoàng kim trường thương bị Kiếm thai Đại La hút hết tinh hoa Hoàng Đạo Tiên Kim rồi vỡ thành vụn kim loại.","phamCap":"Có pha Hoàng Đạo Tiên Kim","anchor":"Trường thương vỡ nát, hóa thành rách nát khối kim loại tiết, rơi lã chã trên đất."}]},"capNhatToi":"@c1054","nguon":["@c1054"]},{"id":"tieu-te-dan-hop-tu-ba-manh-tan-cot","name":"Tiểu tế đàn hợp từ ba mảnh tàn cốt","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo truyền tống","phamCap":"Không rõ","soHuu":["Tam đại Chí Cường giả"],"trangThai":"hoàn chỉnh","blurb":"Tiểu tế đàn cỡ nắm tay được hợp thành từ ba mảnh tàn cốt trắng như ngọc. Nó có thể thu toàn bộ đoàn người và truyền tống họ vào khu vực bên trong Đế Thành.","detail":"Ba mảnh tàn cốt do tam đại Chí Cường giả chia nhau bảo quản được ghép lại thành một tế đàn nhỏ, phát ra khí tức thần bí rồi mang toàn bộ đoàn thiên tài biến mất khỏi ngoài cửa thành.","phanLoaiPhu":"Pháp bảo truyền tống","hinhDang":"Tế đàn cỡ nắm tay","vatLieu":"Ba mảnh tàn cốt trắng như ngọc","uyLuc":"Có thể đồng thời thu và truyền tống toàn bộ đoàn người.","dacDiem":"Chỉ hoàn chỉnh khi ba mảnh tàn cốt được ghép lại.","chuHienThoi":"Tam đại Chí Cường giả","capNhatToi":"@c1056","congNang":["Thu toàn bộ đoàn người vào trong tế đàn và truyền tống họ vào thành @c1056"],"chuSoHuu":[{"ten":"Tam đại Chí Cường giả","tuChuong":"@c1056","denChuong":"","cachCoDuoc":"Mỗi người bảo quản một mảnh tàn cốt rồi hợp lại khi cần dùng.","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1056","loai":"dùng","importance":"normal","giaiDoan":"Hợp thành và truyền tống","text":"Ba mảnh tàn cốt hợp thành tiểu tế đàn, thu toàn bộ đoàn người rồi đưa họ vào khu vực bên trong Đế Thành.","anchor":"Toà này tiểu tế đàn rung động, phát sinh khí tức thần bí, lơ lửng ở trong hư không, nó bất quá to bằng nắm tay mà thôi, thế nhưng lúc này lại đem tất cả mọi người đều thu rồi đi tới.","phamCap":"Không rõ"}]},"nguon":["@c1056"]},{"id":"ba-chan-hai-tai-vien-dinh","name":"Ba chân hai tai viên đỉnh","cn":"","aliases":["Đỉnh ba chân hai tai nhuốm máu","Cổ đỉnh từ kỷ nguyên sau"],"category":"phap-bao","categoryLabel":"Pháp bảo","phanLoaiPhu":"Bảo đỉnh","phamCap":"Không rõ","soHuu":[],"trangThai":"Rời khỏi chiến trường sau khi trở nên ảm đạm","hinhDang":"Viên đỉnh có ba chân và hai tai.","vatLieu":"Được tạo thành từ chín loại tiên kim, có thiên địa mẫu khí và hỗn độn.","nguonGoc":"Chưa rõ; từng xuất hiện dưới dạng dấu ấn hư không dưới hắc uyên của di tích Tiên cổ.","uyLuc":"Chỉ một lần rung nhẹ, bảo đỉnh đã khiến Thạch Hạo cảm nhận bản thân cùng thế giới gần như tan vỡ; nó còn có thể chống lại vô thượng lôi kiếp và chém tan Tiên Đạo lôi đình.","dacDiem":"Đỉnh có ba chân hai tai; thân mang ánh sáng của chín loại tiên kim, được thiên địa mẫu khí bao quanh, chứa hỗn độn và dính tinh huyết của nhiều sinh linh chí cao.","chuHienThoi":"Không rõ","congNang":["Thu nạp và luyện hóa lôi đình cùng kiếp quang, trong quá trình đó hiện ra vô số đồ án. @c1057","Phóng thích thiên địa mẫu khí để chữa lành hư không. @c1057","Đối kháng sự phản phệ của quy tắc và chặt đứt liên hệ nhân quả. @c1058","Chém tan Tiên Đạo lôi đình do thiên cơ và nhân quả xuyên kỷ nguyên dẫn tới. @c1058","Xé mở hư không, để lại khe nứt dẫn sang một khu vực có quy tắc đại đạo khác thường. @c1058","Truyền tiếng thần niệm thông qua những giọt huyết trên thân. @c1057"],"chuSoHuu":[],"blurb":"Ba chân hai tai viên đỉnh là một bảo đỉnh có chân thân được tạo thành từ chín loại tiên kim, mang theo thiên địa mẫu khí, hỗn độn và tinh huyết của nhiều sinh linh chí cao. Sau lần xuất hiện dưới dạng dấu ấn hư không, chân thân của đỉnh đã hiện ra trước Thạch Hạo, đối kháng vô thượng lôi kiếp và những lực lượng liên quan đến thiên cơ, quy tắc, nhân quả. Uy thế của bảo đỉnh vượt xa nhận thức của Thạch Hạo ở thời điểm ấy.","detail":"Nguồn gốc của Ba chân hai tai viên đỉnh chưa rõ; trước khi chân thân xuất hiện, dấu ấn hư không của nó từng hiện ra dưới hắc uyên thuộc di tích Tiên cổ. Đến khi gặp lại Thạch Hạo, bảo đỉnh hiện thân với cấu trúc ba chân hai tai, thân đỉnh tỏa ánh sáng của chín loại tiên kim, được thiên địa mẫu khí bao quanh, bên trong chứa hỗn độn và trên thân dính tinh huyết của nhiều sinh linh chí cao. Nó phát ra tiếng thần niệm thông qua những giọt huyết trên thân. Khi cuộc đối thoại dẫn phát vô thượng lôi kiếp, đỉnh thu nạp lôi đình, hiện ra vô số đồ án để luyện hóa kiếp quang, đồng thời phóng thích thiên địa mẫu khí khôi phục hư không. Bảo đỉnh còn đối kháng sự phản phệ của quy tắc, chặt đứt liên hệ nhân quả và chém tan Tiên Đạo lôi đình do thiên cơ cùng nhân quả xuyên kỷ nguyên dẫn tới; sau lần đối k","capNhatToi":"@c1057","tabs":{"tienTrinh":[{"chuong":"@c1057","loai":"xuất hiện","importance":"major","giaiDoan":"Chân thân hiện thế","phamCap":"Không rõ","text":"Chân thân của bảo đỉnh xuất hiện trước Thạch Hạo với ba chân hai tai, chín loại tiên kim, thiên địa mẫu khí, hỗn độn và nhiều loại tinh huyết chí cao. Khi lời nói trong đỉnh dẫn phát thiên kiếp, nó thu nạp và luyện hóa lôi đình, đồng thời dùng mẫu khí khôi phục hư không.","anchor":"Ba chân hai tai viên đỉnh có các loại tiên kim ánh sáng lộng lẫy, càng có thiên địa mẫu khí vờn quanh"},{"chuong":"@c1058","loai":"dùng","importance":"normal","giaiDoan":"Chống lôi đình và rời đi","text":"Cổ đỉnh chém tan Tiên Đạo lôi đình nhưng trở nên ảm đạm vì phản phệ nhân quả. Sau đó, nó xé hư không rời đi và để lại khe nứt dẫn Thạch Hạo tới thế giới phía bên kia.","anchor":"Cái đỉnh này rất mạnh, trảm xuống lôi đình, thế nhưng nó cũng trả giá cái giá rất lớn!"}]},"nguon":["@c1057","@c1058"]},{"id":"hoang-kim-thanh-tham","name":"Hoàng kim thánh tham","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thánh dược","phamCap":"Thánh dược","soHuu":[],"trangThai":"Bị Thạch Hạo vứt bỏ sau khi nhổ lên","blurb":"Một cây thánh tham màu vàng có chủ thể dài hai thước, tỏa tinh khí và thánh quang. Nó sinh trưởng bằng cách cắm rễ trên thi hài cường giả và hấp thu tinh khí.","detail":"Thạch Hạo phát hiện hoàng kim thánh tham trong vùng núi tím và nhổ cây lên. Khi thấy bộ rễ bám vào một thi hài cổ để hút tinh khí, hắn lập tức vứt bỏ nó.","phanLoaiPhu":"Linh dược mọc trên di hài","hinhDang":"Chủ thể dài hai thước, toàn thân màu vàng","nguonGoc":"Sinh trưởng trong vùng núi tím thuộc thế giới bên kia biên hoang","dacDiem":"Cắm rễ trên thi hài cường giả và hấp thu tinh khí để sinh trưởng.","congNang":["Tích tụ tinh khí và thánh quang trong thân cây nhờ hấp thu dưỡng chất từ di hài."],"capNhatToi":"@c1059","tabs":{"tienTrinh":[{"chuong":"@c1059","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện trong vùng núi tím","text":"Thạch Hạo nhổ cây hoàng kim thánh tham rồi phát hiện bộ rễ của nó bám vào thi hài cường giả để sinh trưởng, khiến hắn lập tức vứt bỏ.","anchor":"Này cây hoàng kim thánh tham liền cắm rễ ở này thi hài trên, dựa vào cái này mà mọc ra","phamCap":"Thánh dược"}]},"nguon":["@c1059"]},{"id":"chien-xa-do-ngan-sac-ngo-cong-keo","name":"Chiến xa do Ngân Sắc Ngô Công kéo","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến xa","phamCap":"Không rõ","soHuu":["Thiếu nữ trong chiến xa"],"trangThai":"Đang được sử dụng","blurb":"Một chiến xa bay xuất hiện trên bình nguyên của thế giới bên kia biên hoang. Xe được tám Ngân Sắc Ngô Công dài trăm trượng, ít nhất đạt cấp Thiên Thần, kéo đi.","detail":"Chiến xa bay ngang bầu trời trong lúc Thạch Hạo đang quan sát sinh linh bản địa. Bên trong truyền ra tiếng cười của một thiếu nữ, nhưng chương chưa xác nhận nàng có phải chủ nhân của xe hay không.","phanLoaiPhu":"Chiến xa bay","hinhDang":"Chiến xa được tám Ngân Sắc Ngô Công kéo","dacDiem":"Tám Ngân Sắc Ngô Công dài trăm trượng và đạt ít nhất cấp Thiên Thần kéo xe bay qua bầu trời.","chuHienThoi":"Chưa xác nhận","chuSoHuu":[{"ten":"Thiếu nữ trong chiến xa","tuChuong":"@c1059","denChuong":"","cachCoDuoc":"Chưa rõ","trangThai":"Nghi là người ngồi trong xe"}],"capNhatToi":"@c1059","tabs":{"tienTrinh":[{"chuong":"@c1059","loai":"xuất hiện","importance":"normal","giaiDoan":"Bay qua bình nguyên","text":"Chiến xa được tám Ngân Sắc Ngô Công dài trăm trượng kéo bay ngang bầu trời, bên trong vang ra tiếng cười của một thiếu nữ.","anchor":"tám con trăm trượng trường Ngân Sắc Ngô Công lôi kéo một cái chiến xa, bay ngang qua bầu trời","phamCap":"Không rõ"}]},"nguon":["@c1059"]},{"id":"tan-do-va-khac-da-bat-hu-son","name":"Tàn đồ và khắc đá Bất Hủ Sơn","cn":"","aliases":[],"category":"khac","categoryLabel":"Di vật ghi chép","phamCap":"Không rõ","soHuu":[],"trangThai":"Xuất hiện sau khi Bất Hủ Sơn sống lại","blurb":"Những tàn đồ và hình khắc xuất hiện trên Bất Hủ Sơn sau khi ngọn núi sống lại. Chúng lưu giữ hình ảnh về các sinh vật vô thượng được gọi là Bất Hủ người.","detail":"Di vật được truyền là ghi lại một phần chân tướng cổ đại. Những hình ảnh Thạch Hạo nhìn thấy mô tả các sinh linh cực kỳ mạnh mẽ từng đạt tới trạng thái bất hủ thực sự.","phanLoaiPhu":"Di vật ghi chép cổ sử","nguonGoc":"Bất Hủ Sơn","dacDiem":"Xuất hiện cùng quá trình sống lại của Bất Hủ Sơn và chứa hình ảnh về Bất Hủ người.","congNang":["Lưu giữ những hình ảnh cổ về các sinh vật vô thượng được gọi là Bất Hủ người."],"capNhatToi":"@c1060","tabs":{"tienTrinh":[{"chuong":"@c1060","loai":"xuất hiện","importance":"normal","giaiDoan":"Bất Hủ Sơn sống lại","text":"Các tàn đồ và khắc đá xuất hiện sau khi Bất Hủ Sơn sống lại, để lộ hình ảnh về những sinh vật được mô tả là Bất Hủ người.","anchor":"Dựa theo theo những người khác trong miện giải tình huống đến xem, sống lại sau đích Bất Hủ Sơn, có đại lượng khắc đá sẽ xuất hiện"}]},"nguon":["@c1060"]},{"id":"xe-nho-va-tam-ngan-ngo-mau-bac","name":"Xe nhỏ và tám ngân ngô màu bạc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo phương tiện","phamCap":"","soHuu":["Thiếu nữ được tám ngân ngô kéo xe"],"trangThai":"Đang được mang theo","blurb":"Một chiếc xe do tám ngân ngô màu bạc kéo, thuộc về thiếu nữ trên đỉnh Bất Hủ Sơn. Cả xe lẫn ngân ngô có thể được thu nhỏ để nàng nâng trong lòng bàn tay.","detail":"Thiếu nữ lấy ra chiếc xe cùng tám ngân ngô dưới hình dạng thu nhỏ khi lưu luyến nhìn lại cố thổ trước lúc bước lên cổ lộ.","phanLoaiPhu":"Phương tiện","hinhDang":"Xe do tám ngân ngô màu bạc kéo","dacDiem":"Cả chiếc xe và tám ngân ngô có thể xuất hiện dưới hình dạng thu nhỏ.","chuHienThoi":"Thiếu nữ được tám ngân ngô kéo xe","capNhatToi":"@c1061","congNang":["Có thể thu nhỏ cả chiếc xe và tám ngân ngô để đặt trong lòng bàn tay."],"chuSoHuu":[{"ten":"Thiếu nữ được tám ngân ngô kéo xe","tuChuong":"@c1061","denChuong":"","cachCoDuoc":"","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1061","loai":"xuất hiện","importance":"normal","giaiDoan":"Thu nhỏ trước lúc rời đi","text":"Thiếu nữ thu chiếc xe và tám ngân ngô màu bạc thành dạng nhỏ rồi nâng trong lòng bàn tay.","anchor":"Ở trong tay nàng xuất hiện một chiếc xe nhỏ, nâng ở lòng bàn tay, còn có tám con màu bạc tiểu rết.","phamCap":""}]},"nguon":["@c1061"]},{"id":"bia-da-mo-co-lo","name":"Bia đá mở cổ lộ","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm truyền tống","phamCap":"","soHuu":[],"trangThai":"Còn hoạt động","blurb":"Những bia đá có bi văn và tranh khắc nằm trên đỉnh Bất Hủ Sơn. Người đủ mạnh có thể dùng tiên khí kích hoạt chúng để mở đường tới thế giới của bất hủ giả.","detail":"Bia đá vừa lưu giữ hình khắc cổ xưa vừa là điểm kích hoạt cổ lộ. Khi được tiên khí thúc đẩy, nơi đây phát kim quang và hình thành một con đường màu vàng nối sang thiên địa khác.","phanLoaiPhu":"Vật phẩm truyền tống","hinhDang":"Bia đá có bi văn và tranh khắc","dacDiem":"Cần người có thực lực đủ mạnh vận dụng tiên khí để kích hoạt.","capNhatToi":"@c1061","congNang":["Mở cổ lộ nối Bất Hủ Sơn với thế giới của bất hủ giả."],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1061","loai":"dùng","importance":"normal","giaiDoan":"Mở đường tới thế giới khác","text":"Bia đá được tiên khí kích hoạt để mở cổ lộ dẫn tới nơi bất hủ giả cư trú.","anchor":"Nếu là thực lực bản thân đủ mạnh, có thể thôi thúc tiên khí kích hoạt bia đá, liền có thể mở ra đường nối, đi gặp bất hủ giả.","phamCap":""}]},"nguon":["@c1061"]},{"id":"than-bi-bao-dinh","name":"Thần bí bảo đỉnh","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phanLoaiPhu":"Pháp bảo có linh trí","phamCap":"Không rõ","soHuu":[],"trangThai":"Rời đi sau khi đưa Thạch Hạo trở về","blurb":"Một bảo đỉnh chảy xuôi mẫu khí, có linh trí và có thể trò chuyện. Nó mở đường đưa Thạch Hạo rời dị giới rồi xóa sạch tiết điểm cùng dấu vết qua lại.","detail":"Thần bí bảo đỉnh xuất hiện khi Thạch Hạo không thể tự mở tiết điểm không gian. Nó dẫn hắn vào vùng không gian u ám, hủy dấu vết nối hai thế giới, phá mở hư không đưa hắn về ngoại thành Đế Thành rồi từ biệt.","hinhDang":"Một chiếc đỉnh chảy xuôi mẫu khí","dacDiem":"Có thể nói chuyện, chảy xuôi mẫu khí và thực hiện thủ đoạn xóa dấu vết không gian.","uyLuc":"Có thể phá mở hư không, xóa tiết điểm và tiêu diệt dấu vết qua lại giữa hai thế giới.","congNang":["Mở đường và dẫn người xuyên qua vùng không gian trung chuyển.","Xóa tiết điểm không gian cùng dấu vết qua lại giữa hai thế giới.","Phá mở hư không để đưa Thạch Hạo trở lại thế giới cũ."],"chuSoHuu":[],"capNhatToi":"@c1063","tabs":{"tienTrinh":[{"chuong":"@c1063","loai":"dùng","importance":"normal","giaiDoan":"Đưa Thạch Hạo trở về","text":"Thần bí bảo đỉnh mở thông đạo, dẫn Thạch Hạo rời dị giới, xóa sạch tiết điểm cùng dấu vết qua lại rồi đưa hắn về ngoại thành Đế Thành.","anchor":"một cái đỉnh chảy xuôi mẫu khí, mang theo Thạch Hạo rời đi cái kia quỷ dị mà lại mạnh mẽ thế giới","phamCap":"Không rõ"}]},"nguon":["@c1063"]},{"id":"kim-sac-phap-chi-cua-bat-huu-gia","name":"Kim sắc pháp chỉ của Bất Hủ giả","cn":"","aliases":[],"category":"khac","categoryLabel":"Pháp chỉ","phanLoaiPhu":"Pháp chỉ truyền ý","phamCap":"Không rõ","soHuu":["Bất Hủ"],"trangThai":"Đã giáng xuống Bất Hủ sơn","blurb":"Pháp chỉ màu vàng do Bất Hủ giả truyền tới Bất Hủ sơn thay cho chân thân. Nội dung báo hiệu tiên chiến sắp mở và thời kỳ bình tĩnh kéo dài một kỷ nguyên đã kết thúc.","detail":"Kim sắc pháp chỉ xuất hiện trước các cao thủ dị giới sau khi thần niệm của Bất Hủ giả vượt giới quét tới. Nó truyền đạt ý chỉ về biến cục sắp tới và khiến các thế lực dị giới bắt đầu chuẩn bị chiến tranh với Cửu Thiên.","hinhDang":"Pháp chỉ màu vàng","nguonGoc":"Do Bất Hủ giả truyền tới Bất Hủ sơn","dacDiem":"Có thể thay Bất Hủ giả truyền đạt ý chỉ vượt giới.","congNang":["Truyền đạt ý chỉ của Bất Hủ giả về việc tiên chiến sắp mở."],"chuSoHuu":[{"ten":"Bất Hủ","tuChuong":"@c1063","denChuong":"","cachCoDuoc":"Pháp chỉ do Bất Hủ giả truyền xuống","trangThai":"Đã được sử dụng để truyền ý"}],"capNhatToi":"@c1063","tabs":{"tienTrinh":[{"chuong":"@c1063","loai":"xuất hiện","importance":"normal","giaiDoan":"Báo hiệu tiên chiến","text":"Kim sắc pháp chỉ giáng xuống Bất Hủ sơn, thay Bất Hủ giả truyền tin tiên chiến sắp mở ra.","anchor":"chỉ có một đạo kim sắc pháp chỉ hạ xuống, xuất hiện ở trước mặt mọi người","phamCap":"Không rõ"}]},"nguon":["@c1063"]},{"id":"loi-de-chien-y","name":"Lôi Đế chiến y","cn":"","aliases":["Lôi Đế giáp trụ"],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ (di vật của Lôi Đế)","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo sử dụng","blurb":"Lôi Đế chiến y là chiến y tàn khuyết do Lôi Đế lưu lại, mang nhiều lỗ thủng và dấu vết rỉ sét. Khi Thạch Hạo bị cưỡng ép sưu hồn, chiến y tự thức tỉnh, chuyển từ óng ánh sang đen kịt, bộc lộ ý chí và oán khí riêng cùng nguy cơ hóa thành Hắc Ám Thần giáp. Sau đó, chiến y tiếp tục bảo vệ Thạch Hạo trước những lực lượng nguy hiểm trong cổ khoáng.","detail":"Lôi Đế chiến y là di vật tàn khuyết của Lôi Đế, ban đầu phủ rỉ sét và có nhiều lỗ thủng. Dưới áp lực khi Gia Đức cưỡng ép sưu hồn Thạch Hạo, chiến y tự thức tỉnh: lớp rỉ biến mất, toàn thân trở nên óng ánh, các lỗ thủng sinh ra vòng xoáy thần bí rồi chiến y chuyển thành đen kịt, chặn sự xâm nhập thần hồn và cộng hưởng với cơn phẫn nộ của chủ nhân. Biến đổi này liên quan đến một biến cố oan khuất từng xảy ra tại Đế Thành, khiến chiến y hắc ám hóa và lưu lạc bên ngoài; tình cảnh của Thạch Hạo có nguy cơ khiến quá trình ấy tái diễn. Trong cổ khoáng, chiến y còn chủ động phát sáng, che chở Thạch Hạo trước tiếng gầm cùng các lực lượng nguy hiểm có sức phá hủy mạnh. @c1064 @c1081","congNang":["Bảo vệ người mặc và chặn sự xâm nhập thần hồn, từng ngăn ngón tay sưu hồn của Gia Đức. @c1064","Tự thức tỉnh dưới áp lực, biến đổi trạng thái và cộng hưởng oán khí với sự phẫn nộ của chủ nhân. @c1064","Phòng hộ thân thể trước tiếng gầm, âm ba, sát ý, quy tắc và các lực lượng nguy hiểm có sức phá hủy mạnh. @c1081"],"phanLoaiPhu":"Giáp trụ chiến đấu","hinhDang":"Giáp trụ tàn khuyết với nhiều lỗ thủng","nguonGoc":"Di vật của Lôi Đế, từng xảy ra biến cố hắc ám hóa trong Đế Thành","dacDiem":"Chiến y tàn khuyết, nhiều lỗ thủng và từng phủ rỉ sét; mang ý chí cùng oán khí riêng, có thể chuyển từ trạng thái óng ánh sang đen kịt và đứng trước nguy cơ hóa thành Hắc Ám Thần giáp.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1064","denChuong":"","cachCoDuoc":"Không nêu trong chương","trangThai":"dang-so-huu"}],"tabs":{"tienTrinh":[{"chuong":"@c1064","loai":"khai phong","importance":"major","giaiDoan":"Hồi sinh và hắc ám hóa","text":"Dưới áp lực sưu hồn của Gia Đức, chiến y từ rỉ sét chuyển sang óng ánh rồi đen kịt. Các lỗ thủng sinh ra vòng xoáy thần bí, chặn ngón tay sưu hồn và bảo vệ Thạch Hạo. Người can thiệp cảnh báo nguy cơ hóa thành Hắc Ám Thần giáp, tái diễn biến cố oan khuất năm xưa trong Đế Thành.","anchor":"Lôi Đế chiến y, lại một lần chuyển hướng hắc ám, bị người miễn cưỡng bức bách đến đây!"},{"chuong":"@c1081","loai":"dùng","importance":"normal","giaiDoan":"Phòng hộ trong cổ khoáng","text":"Lôi Đế chiến y phát sáng, bảo vệ Thạch Hạo trước tiếng gầm và các lực lượng nguy hiểm trong cổ khoáng.","anchor":"trên người hắn Lôi Đế chiến y đang phát sáng, đưa đến bảo vệ tác dụng"}]},"capNhatToi":"@c1064","nguon":["@c1064","@c1081"],"uyLuc":"Uy lực phòng hộ mạnh nhất đã thể hiện là chặn được thủ đoạn cưỡng ép sưu hồn của Gia Đức, đồng thời bảo vệ Thạch Hạo trước tiếng gầm và các lực lượng nguy hiểm trong cổ khoáng."},{"id":"nanh-soi-dai-bong-cua-ong-lao-toc-bac","name":"Nanh sói đại bổng của ông lão tóc bạc","cn":"","aliases":["Lang nha bổng"],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Ông lão tóc bạc cầm nanh sói đại bổng"],"trangThai":"Nguyên vẹn","blurb":"Binh khí của ông lão tóc bạc trấn thủ Đế Thành. Một đòn từ đại bổng đánh tan bảo thuật, tiêu diệt cốt văn và phá nát nửa người Gia Đức.","detail":"Ông lão tóc bạc dùng nanh sói đại bổng để trấn áp Gia Đức sau khi hắn tiếp tục đòi sưu xét Nguyên Thần Thạch Hạo. Binh khí áp đảo hoàn toàn sự chống trả của một Chí Cường giả và khiến Gia Đức suýt bị đánh chết.","phanLoaiPhu":"Đại bổng","uyLuc":"Đánh tan bảo thuật, tiêu diệt cốt văn và trọng thương Gia Đức chỉ bằng một đòn.","dacDiem":"Thiên về trấn áp và công kích trực diện.","chuHienThoi":"Ông lão tóc bạc cầm nanh sói đại bổng","congNang":["Trấn áp đối thủ bằng công kích trực diện.","Đánh tan bảo thuật và tiêu diệt cốt văn của Gia Đức."],"chuSoHuu":[{"ten":"Ông lão tóc bạc cầm nanh sói đại bổng","tuChuong":"@c1065","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1065","loai":"dùng","importance":"normal","giaiDoan":"Trấn áp Gia Đức","text":"Ông lão tóc bạc dùng nanh sói đại bổng đánh tan sự chống trả và khiến Gia Đức trọng thương.","anchor":"Nanh sói đại bổng đánh vào Gia Đức trên người, để hắn một tiếng hét thảm","phamCap":"Không rõ"}]},"capNhatToi":"@c1065","nguon":["@c1065"]},{"id":"ba-manh-cot-tiep-dan-de-thanh","name":"Ba mảnh cốt tiếp dẫn Đế Thành","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm trận pháp","phamCap":"Không rõ","soHuu":["Gia Đức","Người áp tải đi cùng Thạch Hạo"],"trangThai":"Đã dung hợp thành trận đài","blurb":"Ba mảnh cốt dùng để mở đường vào khu vực cốt lõi của Đế Thành. Khi hợp nhất, chúng hóa thành trận đài tiếp dẫn Thạch Hạo và những người đi cùng vào nội thành.","detail":"Gia Đức và người áp tải mỗi người lấy ra một mảnh cốt, còn mảnh thứ ba được người trong thành đưa tới. Ba mảnh dung hợp thành trận đài, vượt qua sự ngăn cách giữa ngoại thành và khu vực liên quan tới Thái cổ Minh Ước.","phanLoaiPhu":"Bộ ba mảnh cốt","hinhDang":"Ba mảnh cốt có thể dung hợp","congNang":["Dung hợp thành trận đài tiếp dẫn người vào khu vực cốt lõi của Đế Thành."],"dacDiem":"Cần đủ ba mảnh cốt mới hình thành trận đài.","chuHienThoi":"Không rõ","tabs":{"tienTrinh":[{"chuong":"@c1065","loai":"dùng","importance":"normal","giaiDoan":"Mở đường vào nội thành","text":"Ba mảnh cốt dung hợp thành trận đài và tiếp dẫn nhóm Thạch Hạo vào khu vực cốt lõi của Đế Thành.","anchor":"dung hợp lại cùng nhau, hóa thành trận đài, đem bọn họ tiếp dẫn tiến vào","phamCap":"Không rõ"}]},"capNhatToi":"@c1065","nguon":["@c1065"]},{"id":"dao-dai-xuong-thu","name":"Đạo đài xương thú","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm kiến trúc","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn nguyên vẹn","blurb":"Đạo đài trắng như ngọc nằm trong cổ điện truyền tống tại Vô Lượng Thiên.","detail":"Đạo đài được mài từ một khối xương thú khổng lồ, mang hình thức cổ xưa và là điểm tiếp nhận Thạch Hạo sau hành trình vượt giới.","phanLoaiPhu":"Đạo đài truyền tống","hinhDang":"Đạo đài trắng noãn như ngọc","vatLieu":"Xương của một con thú khổng lồ","dacDiem":"Có hình thức cổ lão và nằm trong cung điện truyền tống rộng lớn.","capNhatToi":"@c1066","nguon":["@c1066"]},{"id":"cua-dong-khong-lo","name":"Cửa đồng khổng lồ","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm kiến trúc","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn nguyên vẹn","blurb":"Cặp cửa đồng khổng lồ ngăn cách đại điện truyền tống với nơi Bạch Mi lão nhân trấn giữ.","detail":"Mỗi cánh cửa cao hơn ngàn dặm, dựng lên đồ sộ như vách núi bên ngoài khu vực đặt đạo đài xương thú.","phanLoaiPhu":"Cửa kiến trúc","hinhDang":"Cặp cửa cao hơn ngàn dặm","vatLieu":"Đồng","dacDiem":"Kích thước khổng lồ như vách núi.","capNhatToi":"@c1066","nguon":["@c1066"]},{"id":"co-dao-dai-mo-phong-dang-tien-dai","name":"Cổ đạo đài mô phỏng Đăng Tiên Đài","cn":"","aliases":["Cổ đạo đài","Bệ đá"],"category":"phap-bao","categoryLabel":"Bí bảo dạng đạo đài","phamCap":"Không rõ","soHuu":[],"trangThai":"Đã hao tổn sức mạnh thần bí","blurb":"Cổ đạo đài mô phỏng Đăng Tiên Đài là một bệ đá có thể cộng hưởng với ba đạo tiên khí của Thạch Hạo. Nó mài giũa, bồi dưỡng tiên khí, trợ giúp kết thành đại đạo chi hoa và mở thông đạo đưa những người bị giam giữ ra ngoài.","detail":"Cổ đạo đài chỉ phát sinh dị tượng khi Thạch Hạo đưa ra đủ ba đạo tiên khí. Sức mạnh thần bí của nó mài giũa, bồi dưỡng và làm lớn mạnh ba đạo tiên khí trong vài chục ngày, sau đó trợ giúp một đạo tiên khí ngưng kết thành đại đạo chi hoa. Sau lần trợ giúp này, bệ đá trở nên ảm đạm vì hao tổn sức mạnh, nhưng vẫn có thể theo pháp ấn của Thạch Hạo phóng ra vô số phù văn, xuyên thủng hư không và hình thành thông đạo màu bạc để đưa những người bị giam giữ ra ngoài. @c1067","phanLoaiPhu":"Đạo đài mô phỏng Đăng Tiên Đài","hinhDang":"Bệ đá cổ","uyLuc":"Có thể phóng vô số phù văn xuyên thủng hư không và hình thành thông đạo màu bạc.","dacDiem":"Mô phỏng Đăng Tiên Đài, cộng hưởng với ba đạo tiên khí và trở nên ảm đạm sau khi hao tổn sức mạnh để trợ giúp tiên khí kết thành đại đạo chi hoa. @c1067","congNang":["Mài giũa, bồi dưỡng và làm lớn mạnh ba đạo tiên khí. @c1067","Hỗ trợ một đạo tiên khí ngưng kết thành đại đạo chi hoa. @c1067","Phóng vô số phù văn xuyên thủng hư không, hình thành thông đạo màu bạc để thoát khỏi vùng giam giữ."],"chuSoHuu":[],"capNhatToi":"@c1067","tabs":{"tienTrinh":[{"chuong":"@c1067","loai":"dùng","importance":"major","giaiDoan":"Trợ kết hoa và mở đường","text":"Cổ đạo đài cộng hưởng với ba đạo tiên khí, trợ giúp Thạch Hạo kết thành đại đạo chi hoa rồi hao tổn sức mạnh thần bí. Sau đó nó phóng vô số phù văn, xuyên thủng hư không và mở thông đạo màu bạc.","anchor":"bệ đá phát sáng, rung động ầm ầm, theo Thạch Hạo động tác mà lao ra vô tận phù văn","phamCap":"Không rõ"}]},"nguon":["@c1067"]},{"id":"truyen-tong-tran-vuot-gioi","name":"Truyền Tống trận vượt giới","cn":"","aliases":[],"category":"khac","categoryLabel":"Trận pháp truyền tống","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang được duy trì","blurb":"Trận pháp có khả năng truyền tống người vượt qua ranh giới giữa các thế giới. Việc duy trì trận cần tiêu hao lượng lớn thiên tài địa bảo.","detail":"Nguyên Thanh lấy việc Thạch Hạo tự ý sử dụng Truyền Tống trận vượt giới, làm tăng gánh nặng cho tế đàn năm màu, làm căn cứ buộc tội hắn.","phanLoaiPhu":"Trận pháp truyền tống","congNang":["Truyền tống người vượt giới."],"dacDiem":"Cần tiêu hao lượng lớn thiên tài địa bảo để duy trì.","capNhatToi":"@c1068","tabs":{"tienTrinh":[{"chuong":"@c1068","loai":"nhắc tới","importance":"normal","giaiDoan":"Trở thành căn cứ buộc tội","text":"Nguyên Thanh viện dẫn mức tiêu hao của Truyền Tống trận vượt giới để buộc tội Thạch Hạo.","anchor":"Các ngươi biết cái kia vượt giới Truyền Tống trận giữ gìn lên cần tiêu hao bao nhiêu thiên tài địa bảo sao?"}]},"nguon":["@c1068"]},{"id":"hoang-huyet-tri","name":"Hoàng Huyết trì","cn":"","aliases":[],"category":"khac","categoryLabel":"Tiên trì tu luyện","phamCap":"Không rõ","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Đang được sử dụng","blurb":"Tiên trì dùng để gột rửa và tăng cường những người tu luyện giành được tư cách tiến vào. Suất sử dụng được dành cho nhóm thiên tài cạnh tranh đứng đầu tại Thiên Thần Thư Viện. (+) Bảo trì được dùng để cứu chữa Mạc Đạo sau khi dấu ấn trong Nguyên Thần phát tác. [CAN-SOAT-GOP]","detail":"Những thiên tài mạnh nhất giành được tư cách tiến vào Hoàng Huyết trì đã hoàn thành tu luyện và xuất quan với sinh mệnh tinh khí mạnh, thu được lợi ích lớn.","phanLoaiPhu":"Tiên trì tu luyện","congNang":["Gột rửa và tăng cường người tu luyện."],"dacDiem":"Tư cách tiến vào dành cho những người cạnh tranh đứng đầu.","chuHienThoi":"Thiên Thần Thư Viện","capNhatToi":"@c1068","chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1068","denChuong":"","cachCoDuoc":"Được bố trí làm tài nguyên tu luyện của thư viện","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1068","loai":"dùng","importance":"normal","giaiDoan":"Đợt gột rửa đầu tiên","text":"Nhóm thiên tài mạnh nhất hoàn thành gột rửa tại Hoàng Huyết trì và thu được lợi ích lớn.","anchor":"Mạnh nhất mấy người liền thu được Hoàng Huyết trì gột rửa tư cách, được lợi ích to lớn"}]},"nguon":["@c1068","@c1149"]},{"id":"xich-huyet-hao","name":"Xích Huyết hào","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo thuyền hải tặc","phanLoaiPhu":"Thuyền vượt tinh không","phamCap":"Không rõ","soHuu":["Chủ nhân Xích Huyết hào"],"trangThai":"Nguyên vẹn","blurb":"Bảo thuyền hải tặc đỏ thẫm nổi danh tại Vô Lượng Thiên, chuyên vượt tinh không và vận chuyển nô lệ tới Thái Sơ cổ quáng.","detail":"Xích Huyết hào dài hàng vạn trượng, đỏ thẫm như máu và mang huyết sát. Dưới sự điều khiển của chủ nhân, bảo thuyền thoát khỏi trường vực do Thái Sơ cổ quáng tạo ra rồi quay lại Thái Sơ tinh sau khi dị động chấm dứt.","hinhDang":"Bảo thuyền đỏ thẫm dài hàng vạn trượng.","dacDiem":"Toàn thuyền đỏ thẫm như máu và mang theo khí tức huyết sát.","chuHienThoi":"Chủ nhân Xích Huyết hào","congNang":["Vượt qua tinh không giữa Vô Lượng Thiên và khu vực Thái Sơ tinh.","Vận chuyển số lượng lớn nô lệ có tu vi tới khu vực khai khoáng."],"chuSoHuu":[{"ten":"Chủ nhân Xích Huyết hào","tuChuong":"@c1069","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1069","tabs":{"tienTrinh":[{"chuong":"@c1069","loai":"dùng","importance":"normal","giaiDoan":"Hành trình tới Thái Sơ tinh","text":"Xích Huyết hào vận chuyển nô lệ qua vùng tàn trận và được chủ nhân điều khiển thoát khỏi trường vực khi Thái Sơ cổ quáng thức tỉnh.","anchor":"Xích huyết hào thuyền hải tặc, ở Vô Lượng Thiên rất nổi danh","phamCap":"Không rõ"}]},"nguon":["@c1069"]},{"id":"ky-thach-do-xet","name":"Kỳ thạch dò xét","cn":"","aliases":[],"category":"khac","categoryLabel":"Bí thạch kiểm tra","phanLoaiPhu":"Kỳ thạch dò xét tiềm năng","phamCap":"Không rõ","soHuu":["Cổ thế gia mua Thạch Hạo"],"trangThai":"Đã vỡ thành bột","blurb":"Kỳ thạch dò xét là bí thạch được Cổ thế gia dùng để kiểm tra sức chiến đấu và tiềm năng của Thạch Hạo. Khi tiến hành dò xét, kỳ thạch phát sáng dữ dội rồi bị hào quang từ cơ thể hắn nghiền thành bột, khiến cao tầng gia tộc phong tỏa khu vực và đặc biệt chú ý tới hắn.","detail":"Kỳ thạch dò xét được Cổ thế gia sử dụng nhằm đánh giá sức chiến đấu và tiềm năng của đối tượng. Trong lần kiểm tra Thạch Hạo, bí thạch xuất hiện phản ứng dữ dội, sau đó không chịu nổi lực lượng phát ra từ cơ thể hắn và bị nghiền vỡ thành bột. Kết quả bất thường này khiến cao tầng gia tộc lập tức phong tỏa khu vực và dành sự chú ý đặc biệt cho Thạch Hạo. @c1070","congNang":["Dò xét sức chiến đấu và tiềm năng của đối tượng. @c1070"],"dacDiem":"Khi dò xét Thạch Hạo, kỳ thạch phát sáng dữ dội nhưng không chịu nổi lực lượng phát ra từ cơ thể hắn, cuối cùng bị nghiền thành bột. @c1070","chuHienThoi":"Cổ thế gia mua Thạch Hạo","chuSoHuu":[{"ten":"Cổ thế gia mua Thạch Hạo","tuChuong":"@c1070","denChuong":"@c1070","cachCoDuoc":"Vật kiểm tra thuộc gia tộc","trangThai":"Đã bị phá hủy"}],"capNhatToi":"@c1070","tabs":{"tienTrinh":[{"chuong":"@c1070","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Vỡ khi dò xét Thạch Hạo","text":"Được dùng để kiểm tra Thạch Hạo nhưng bị hào quang từ cơ thể hắn nghiền vỡ thành bột.","anchor":"Rất nhanh khối này kỳ thạch vỡ nát, bị Thạch Hạo trong cơ thể lao ra hào quang cắn nát, hóa thành bột mịn.","phamCap":"Không rõ"}]},"nguon":["@c1070"]},{"id":"sinh-menh-chi-thach","name":"Sinh mệnh chi thạch","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thiên tài địa bảo","phamCap":"Không rõ","soHuu":[],"trangThai":"Được tìm kiếm trong Thái Sơ cổ quáng","blurb":"Thiên tài địa bảo cực hiếm có khả năng kéo dài tuổi thọ cho nhân vật từ cấp giáo chủ trở lên. Vương tộc giao Thạch Hạo tìm một hoặc hai khối để trao cho tiểu thư mang tiên huyết. (+) Khoáng vật được cho là tồn tại trong Thái Sơ Cổ Quáng. Vương gia từng định đưa Thạch Hạo vào đó khai thác loại tài nguyên này. [CAN-SOAT-GOP]","detail":"Sinh mệnh chi thạch phần nhiều được tìm thấy trong Thái Sơ cổ quáng. Vương tộc dùng nhiệm vụ tìm kiếm vật này làm điều kiện để giúp Thạch Hạo thoát thân phận nô lệ và tới Thiên Thần Thư Viện.","phanLoaiPhu":"Thiên tài địa bảo","nguonGoc":"Phần nhiều nằm trong Thái Sơ cổ quáng","uyLuc":"Có thể đoạt tạo hóa và kéo dài tuổi thọ cho nhân vật từ cấp giáo chủ trở lên.","dacDiem":"Cực kỳ hiếm có.","congNang":["Kéo dài tuổi thọ cho nhân vật từ cấp giáo chủ trở lên."],"capNhatToi":"@c1071","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1071","loai":"xuất hiện","importance":"normal","giaiDoan":"Trở thành điều kiện giao dịch","text":"Vương tộc yêu cầu Thạch Hạo tìm một hoặc hai khối Sinh mệnh chi thạch trong Thái Sơ cổ quáng để đổi lấy tự do và cơ hội tới Thiên Thần Thư Viện.","anchor":"có thể vì là giáo chủ cấp trở lên nhân vật kéo dài tuổi thọ","phamCap":"Không rõ"}]},"nguon":["@c1071","@c1267"]},{"id":"kim-cuong-trac","name":"Kim Cương trác","cn":"","aliases":["Kim Cương trác","Kim Cương trác trên đầu Thạch Hạo"],"category":"phap-bao","categoryLabel":"Pháp khí khống chế","phamCap":"Không rõ","soHuu":["Các trưởng giả Vương tộc tại khu mỏ","Thạch Hạo"],"trangThai":"Đang đeo trên đầu Thạch Hạo","blurb":"Kim Cương trác là pháp khí màu trắng bạc được các trưởng giả Vương tộc đội lên đầu Thạch Hạo sau khi giải gông xiềng và cấm chế, nhằm khống chế hắn trong thời gian làm nhiệm vụ tại Thái Sơ cổ quáng. Pháp bảo này rất khó tháo, có thể càng siết càng chặt, nhưng về sau đã bị Thạch Hạo phá nát.","detail":"Kim Cương trác có màu trắng bạc, trên thân có cốt văn lưu chuyển và có thể phóng lớn để đội lên đầu mục tiêu. Sau khi giải gông xiềng cùng cấm chế cho Thạch Hạo, một trưởng giả Vương tộc đã dùng pháp khí này để trấn áp, ngăn hắn tự ý bỏ trốn và ép hắn phục vụ Vương Hi như một người đào quáng tại Thái Sơ cổ quáng (@c1071, @c1092). Về sau, Kim Cương trác bị Thạch Hạo phá nát.","phanLoaiPhu":"Pháp khí khống chế","hinhDang":"Vòng trắng bạc có cốt văn lưu chuyển","uyLuc":"Có thể trấn áp, kiềm chế và không ngừng siết chặt người đeo, khiến đối phương rất khó tự tháo bỏ.","dacDiem":"Pháp khí màu trắng bạc, có cốt văn lưu chuyển; một khi đã đội lên đầu thì rất khó tháo xuống.","chuHienThoi":"Các trưởng giả Vương tộc tại khu mỏ","congNang":["Có thể phóng lớn rồi đội lên đầu mục tiêu.","Trấn áp, kiềm chế người đeo và càng siết chặt khi cần.","Ngăn người bị khống chế tự ý tháo vòng hoặc bỏ trốn (@c1071).","Khống chế Thạch Hạo, ép hắn làm tôi tớ và phục vụ Vương Hi (@c1092)."],"chuSoHuu":[{"ten":"Các trưởng giả Vương tộc tại khu mỏ","tuChuong":"@c1071","denChuong":"","cachCoDuoc":"Không nêu","trangThai":"Đang dùng để khống chế Thạch Hạo"},{"ten":"Thạch Hạo","tuChuong":"@c1092","denChuong":"","cachCoDuoc":"Bị người Vương gia đeo lên tại Thái Sơ cổ quáng.","trangThai":"Bị ép mang"}],"capNhatToi":"@c1071","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1071","loai":"dùng","importance":"normal","giaiDoan":"Kiềm chế Thạch Hạo","text":"Sau khi giải gông xiềng và cấm chế cho Thạch Hạo, một trưởng giả Vương tộc đội Kim Cương trác lên đầu hắn để đề phòng hắn bỏ trốn.","anchor":"một khi đội ở trên đầu, rất khó gỡ xuống, sẽ càng lặc càng chặt","phamCap":"Không rõ"},{"chuong":"@c1092","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ mục đích khống chế","text":"Nguồn gốc và mục đích của Kim Cương Trác được xác nhận là để ép Thạch Hạo làm tôi tớ cho Vương Hi.","anchor":"trên đầu hắn Kim Cương trác chính là tộc này người ở Thái Sơ cổ quáng cho hắn mang theo, chính là vì thu phục đến cho nữ tử này khi (làm) tôi tớ.","phamCap":"Không rõ"}]},"nguon":["@c1071","@c1092","@c1109","@c1149","@c1267"]},{"id":"thien-thien-bao-y","name":"Thiên thiền bảo y","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo y","phanLoaiPhu":"Đạo bào hộ thể","phamCap":"Không rõ","soHuu":["Lão giả xác ướp mặc đạo bào"],"trangThai":"Nằm trên xác ướp cổ","vatLieu":"Xác thiên thiền","chuHienThoi":"Lão giả xác ướp mặc đạo bào","blurb":"Đạo bào cổ được luyện từ xác thiên thiền và có giá trị vô lượng. Thạch Hạo nhận ra bảo vật nhưng không dám lấy vì khí tức của xác ướp quá mạnh.","detail":"Thiên thiền bảo y nằm trên thi thể một lão giả gần lối vào Thái Sơ cổ quáng. Khí tức còn lại của thi thể khiến Thạch Hạo không thể tiếp cận an toàn, nên hắn từ bỏ ý định lấy bảo y.","dacDiem":"Được tế luyện từ xác thiên thiền.","chuSoHuu":[{"ten":"Lão giả xác ướp mặc đạo bào","tuChuong":"@c1072","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Vẫn nằm trên thi thể"}],"tabs":{"tienTrinh":[{"chuong":"@c1072","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện trong cổ quáng","text":"Thạch Hạo nhận ra đạo bào trên xác ướp được luyện từ xác thiên thiền nhưng từ bỏ ý định lấy đi.","anchor":"ông già này trên người đạo bào kiểu dáng cổ lão, mà lại càng là trong truyền thuyết thiên thiền xác tế luyện mà thành","phamCap":"Không rõ"}]},"capNhatToi":"@c1072","nguon":["@c1072"]},{"id":"mang-nhen-vang","name":"Mạng nhện vàng","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phanLoaiPhu":"Tơ do kim sắc nhện lớn tạo ra","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn trong Thái Sơ cổ quáng","blurb":"Mạng tơ vàng do kim sắc nhện lớn nhả ra khi còn sống, che kín một đoạn cổ động. Tơ cực kỳ bền chắc, khiến Thạch Hạo không thể lấy xuống dù chỉ một sợi.","detail":"Thạch Hạo xem mạng tơ là thiên tài địa bảo hiếm có và thử dùng nhiều cách để thu lấy. Việc tác động vào mạng tơ khiến thi hài kim sắc nhện lớn chuyển động và tấn công hắn.","nguonGoc":"Được kim sắc nhện lớn nhả ra khi còn sống trong Thái Sơ cổ quáng.","hinhDang":"Mạng tơ màu vàng che kín cổ động.","vatLieu":"Tơ nhện vàng.","dacDiem":"Tơ cực kỳ bền chắc, Thạch Hạo không thể kéo xuống dù chỉ một sợi.","congNang":["Che kín một đoạn cổ động trong Thái Sơ cổ quáng."],"dinhDanh":"goc","capNhatToi":"@c1073","tabs":{"tienTrinh":[{"chuong":"@c1073","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện trong cổ động","text":"Thạch Hạo phát hiện mạng tơ vàng do kim sắc nhện lớn tạo ra khi còn sống và không thể lấy xuống dù chỉ một sợi.","anchor":"mặc hắn mọi cách nỗ lực đều không thể kéo xuống dù ột tiểu rễ"}]},"nguon":["@c1073"]},{"id":"truong-sinh-dich-trong-tien-duoc-tri","name":"Trường Sinh Dịch trong tiên dược trì","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Dược dịch","phamCap":"Dược dịch do Trường Sinh Dược lột xác tạo thành","soHuu":["Thạch Hạo"],"trangThai":"Còn hơn nửa lượng trong tiên dược trì","blurb":"Dược dịch hình thành từ sự lột xác của Trường Sinh Dược trong tiên dược trì. Nó có thể dưỡng thần, bổ thân và rèn luyện hình thần, đồng thời xúc tiến quá trình lột xác của Đại đạo chi hoa.","detail":"Trường Sinh Dịch giúp Thạch Hạo tu dưỡng hình thần và thúc đẩy đạo quả trên Đại đạo chi hoa kết thành sinh linh. Dược dịch chỉ đóng vai trò xúc tiến lột xác, không quyết định con đường hay phương hướng đạo quả của người sử dụng.","phanLoaiPhu":"Dược dịch rèn luyện hình thần","nguonGoc":"Hình thành từ sự lột xác của Trường Sinh Dược trong tiên dược trì","uyLuc":"Có thể dưỡng thần, bổ thân và rèn luyện cả hình lẫn thần.","dacDiem":"Xúc tiến sự lột xác nhưng không quyết định bản chất hay phương hướng của đạo quả.","chuHienThoi":"Thạch Hạo","congNang":["Dưỡng thần và bổ thân @c1076","Rèn luyện hình và thần của người sử dụng @c1076","Xúc tiến Đại đạo chi hoa và đạo quả lột xác @c1076"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1076","denChuong":"","cachCoDuoc":"Sử dụng lượng dược dịch còn lại trong tiên dược trì","trangThai":"Đang dùng để bế quan"}],"capNhatToi":"@c1076","tabs":{"tienTrinh":[{"chuong":"@c1076","loai":"dùng","importance":"normal","giaiDoan":"Tẩm bổ đạo quả thứ nhất","text":"Trường Sinh Dịch dưỡng luyện hình thần của Thạch Hạo và xúc tiến Đại đạo chi hoa kết thành sinh linh, sau đó tiếp tục được hắn dùng để bế quan.","anchor":"này trong ao tuy rằng có Trường Sinh dược lột xác, hóa thành Trường Sinh Dịch, có thể dưỡng thần, bổ thân, có thể rèn luyện một người hình cùng thần.","phamCap":"Dược dịch do Trường Sinh Dược lột xác tạo thành"}]},"nguon":["@c1076"]},{"id":"cot-thuyen-cua-thien-than-thu-vien","name":"Cốt thuyền của Thiên Thần Thư Viện","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Phi hành bảo thuyền","phamCap":"Không rõ","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Đang hoạt động","blurb":"Một chiếc phi hành bảo thuyền lớn, trắng sáng như ngọc, được Thiên Thần Thư Viện sử dụng để đưa đoàn hậu bối tới Thái Sơ tinh. Nó có thể vượt tinh không và tránh các dấu vết đại trận còn sót lại.","detail":"Cốt thuyền chở nhiều thiên tài thuộc các chủng tộc cùng hai lão giả hộ đạo. Trong hành trình tới Thái Sơ tinh, nó né qua những dấu vết đại trận còn lưu lại trong khu vực rồi đáp xuống tinh thần này.","phanLoaiPhu":"Phi hành bảo thuyền","hinhDang":"Thuyền lớn trắng sáng như được điêu khắc từ ngọc thạch","uyLuc":"Có thể bay xuyên tinh không và cơ động tránh các dấu vết đại trận.","dacDiem":"Thân thuyền trắng sáng như ngọc, đủ sức chuyên chở một đoàn hậu bối cùng người hộ đạo.","chuHienThoi":"Thiên Thần Thư Viện","congNang":["Phi hành vượt tinh không @c1076","Tránh các dấu vết đại trận còn sót lại trên đường bay @c1076","Chuyên chở đoàn hậu bối và người hộ đạo @c1076"],"chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1076","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1076","tabs":{"tienTrinh":[{"chuong":"@c1076","loai":"dùng","importance":"normal","giaiDoan":"Đưa hậu bối tới Thái Sơ tinh","text":"Cốt thuyền vượt qua tinh không, né các dấu vết đại trận và đưa đoàn Thiên Thần Thư Viện đáp xuống Thái Sơ tinh.","anchor":"Nó bạch xán xán như ngọc thạch khắc thành, né qua rất nhiều tàn lưu ở khu vực này đại trận dấu vết, trực tiếp nhằm phía Thái Sơ Tinh thần.","phamCap":"Không rõ"}]},"nguon":["@c1076"]},{"id":"cuu-hoang-lo","name":"Cửu Hoàng lô","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Hỗn Độn chí bảo","phanLoaiPhu":"Lô hộ thân","phamCap":"Chí bảo pháp khí đứng đầu Vô Lượng Thiên","soHuu":["Trường Sinh gia tộc sở hữu Cửu Hoàng lô","Thiên Thần Thư Viện","Nữ tu áo tím Nguyệt Tê tộc","Bốn nam tu cùng nữ tu Nguyệt Tê tộc"],"hinhDang":"Lô đỏ sẫm cao ba tấc, trên thân có dấu chín Phượng Hoàng và một lỗ thủng xuyên qua.","nguonGoc":"Được đào lên từ Thái Sơ cổ quáng.","uyLuc":"Trường vực do chín Phượng Hoàng tạo thành có thể bảo vệ người sử dụng trước khí tức đủ khiến Thiên Thần sụp đổ.","dacDiem":"Bảo lô màu đỏ sẫm cao ba tấc, mang dấu chín Phượng Hoàng; thân lô có lỗ thủng do một nhân vật vô địch ngoài biên hoang gây ra trong Bất Hủ cuộc chiến, khí linh không còn hiển hiện, đồng thời bảo lô có thể rung động và hô ứng khi trở lại Thái Sơ cổ quáng.","chuHienThoi":"Trường Sinh gia tộc sở hữu Cửu Hoàng lô","trangThai":"Bị xuyên thủng nhưng vẫn có thể vận dụng","blurb":"Cửu Hoàng lô là Hỗn Độn chí bảo được tôn là pháp khí đứng đầu Vô Lượng Thiên, vốn được đào lên từ Thái Sơ cổ quáng. Dù thân lô từng bị đánh xuyên thủng và khí linh không còn hiển hiện, bảo vật vẫn có thể phóng ra chín Phượng Hoàng, tạo trường vực bảo hộ người sử dụng. (+) Trọng khí phối hợp với Thập Giới Đồ để ngăn dấu ấn Bất Hủ giả phát nổ. [CAN-SOAT-GOP]","detail":"Cửu Hoàng lô là một bảo lô màu đỏ sẫm cao ba tấc, trên thân mang dấu chín Phượng Hoàng cùng một lỗ thủng xuyên thân. Trong Bất Hủ cuộc chiến thời cổ, một nhân vật vô địch ngoài biên hoang đã đánh thủng bảo lô, khiến khí linh từ đó không còn hiển hiện. Bảo vật vốn được đào lên từ Thái Sơ cổ quáng; khi được Thiên Thần Thư Viện đưa trở lại nơi này, nó từng rung động dữ dội và hô ứng với cổ khoáng. Trong chuyến thám hiểm của nhóm năm người, chín Phượng Hoàng bay khỏi vách lô, phối hợp với sương hỗn độn hình thành trường vực hộ thân; sau khi ổn định, bảo lô tiếp tục phát xích hà bảo vệ cả đoàn.","congNang":["Phóng ra chín Phượng Hoàng, phối hợp với sương hỗn độn tạo thành trường vực hộ thân, chống lại khí tức đủ khiến Thiên Thần sụp đổ. @c1077","Có thể tự bay ra khỏi Thái Sơ cổ quáng. @c1077"],"chuSoHuu":[{"ten":"Trường Sinh gia tộc sở hữu Cửu Hoàng lô","tuChuong":"@c1077","denChuong":"","cachCoDuoc":"Không được nêu rõ","trangThai":"Chủ sở hữu"},{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1077","denChuong":"","cachCoDuoc":"Được Trường Sinh gia tộc tạm cho mượn","trangThai":"Tạm quản"},{"ten":"Nữ tu áo tím Nguyệt Tê tộc","tuChuong":"@c1077","denChuong":"","cachCoDuoc":"Được trưởng lão giao chấp chưởng trong lượt thăm dò","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1077","loai":"khai phong","importance":"major","giaiDoan":"Hé lộ nguồn gốc và uy năng","phamCap":"Chí bảo pháp khí đứng đầu Vô Lượng Thiên","text":"Thiên Thần Thư Viện đưa Cửu Hoàng lô đến cổ khoáng và tiết lộ nó vốn được đào lên từ chính nơi này. Nhóm năm người kích hoạt chín Phượng Hoàng cùng sương hỗn độn để tạo trường vực hộ thân, giúp họ vượt qua uy áp của thi hài tóc bạc.","anchor":"Nó nguyên vốn là Thái Sơ cổ quáng đào ra bị táng ở nơi này"}]},"capNhatToi":"@c1077","dinhDanh":"goc","nguon":["@c1077","@c1149"]},{"id":"tien-duoc-tri","name":"Tiên dược trì","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Dược trì","phamCap":"Tạo hóa do Trường Sinh dược để lại","soHuu":["Thạch Hạo"],"trangThai":"Được Thạch Hạo bảo vệ","blurb":"Dược trì chứa chất lỏng ngũ sắc do Trường Sinh dược lột xác để lại. Nước thuốc được cho là có khả năng giúp sinh linh thoát thai hoán cốt và niết bàn.","detail":"Tiên dược trì nằm trong cổ khoáng, chứa dược chất có thể thay máu, rèn cốt và khiến nội tạng tái sinh. Sự tồn tại của dược trì còn khiến nhóm truyền nhân Vô Lượng Thiên suy đoán một cây Bất Tử dược chân chính vẫn cắm rễ trong mật địa của cổ khoáng.","phanLoaiPhu":"Dược dịch ngũ sắc","nguonGoc":"Do Trường Sinh dược lột xác để lại trong cổ khoáng.","uyLuc":"Có thể giúp người dùng thoát thai hoán cốt và niết bàn.","dacDiem":"Chất lỏng ngũ sắc tỏa tiên quang và mang dược tính tái sinh mạnh.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1078","congNang":["Thay máu, rèn cốt và tái sinh nội tạng.","Hỗ trợ người dùng lột xác và niết bàn."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1078","denChuong":"","cachCoDuoc":"Phát hiện và bảo vệ dược trì trong cổ khoáng.","trangThai":"Đang bảo vệ"}],"tabs":{"tienTrinh":[{"chuong":"@c1078","loai":"xuất hiện","importance":"normal","giaiDoan":"Bị nhóm Vô Lượng Thiên phát hiện","text":"Năm truyền nhân Vô Lượng Thiên nhận ra chất lỏng ngũ sắc phía sau Thạch Hạo là tiên dược trì và nảy ý định giết hắn để chiếm lấy.","anchor":"bọn họ lập tức đoán được, đây mới thực là tiên dược trì"}]},"nguon":["@c1078"]},{"id":"truong-sinh-duoc-trong-co-khoang","name":"Trường Sinh dược trong cổ khoáng","cn":"","aliases":["Bất Tử dược trong cổ khoáng"],"category":"dan-duoc","categoryLabel":"Bất Tử dược","phamCap":"Trường Sinh dược","soHuu":[],"trangThai":"Chưa được tìm thấy","blurb":"Một cây Trường Sinh dược được cho là vẫn cắm rễ trong mật địa của cổ khoáng. Dấu vết lột xác của nó đã để lại dược chất hình thành tiên dược trì.","detail":"Nhóm truyền nhân Vô Lượng Thiên căn cứ vào tiên dược trì để suy đoán rằng cây thuốc chân chính chưa rời khỏi cổ khoáng. Vị trí cụ thể của nó chưa được phát hiện.","phanLoaiPhu":"Bất Tử dược","nguonGoc":"Ẩn trong một mật địa thuộc cổ khoáng.","dacDiem":"Có thể lột xác và để lại dược chất quý giá.","capNhatToi":"@c1078","congNang":["Lột xác và để lại dược chất hình thành tiên dược trì."],"tabs":{"tienTrinh":[{"chuong":"@c1078","loai":"nhắc tới","importance":"bridge","giaiDoan":"Suy đoán còn ẩn trong cổ khoáng","text":"Nhóm truyền nhân Vô Lượng Thiên cho rằng một cây Bất Tử dược chân chính vẫn cắm rễ trong mật địa của cổ khoáng.","anchor":"nhất định còn có một cây chân chính Bất Tử dược, liền cắm rễ ở này tiên khoáng bên trong một cái nào đó nơi mật địa"}]},"nguon":["@c1078"]},{"id":"dai-dao-chi-hoa-cua-thach-hao","name":"Đại đạo chi hoa của Thạch Hạo","cn":"","aliases":[],"category":"khac","categoryLabel":"Tiên khí biến hóa","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"đang có","blurb":"Đóa hoa đại đạo do một trong ba đạo tiên khí của Thạch Hạo kết thành.","detail":"Đại đạo chi hoa hiện trên đầu Thạch Hạo, khẽ lay động và rải xuống mưa hoa. Nó phá giải đòn tập kích kết hợp tiên khí và thức niệm bảo thuật của nữ tu Nguyệt Tê tộc.","phanLoaiPhu":"Tiên khí kết thành","dacDiem":"Được kết thành từ một trong ba đạo tiên khí của Thạch Hạo.","congNang":["Rải mưa hoa để phá giải tiên khí và thần thức bảo thuật công kích nguyên thần."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1079","denChuong":"","cachCoDuoc":"Một trong ba đạo tiên khí kết thành","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1079","loai":"dùng","importance":"normal","giaiDoan":"Phá Linh Tê ngự nguyệt","text":"Thạch Hạo dùng đại đạo chi hoa phá giải tiên khí và thức niệm bảo thuật của nữ tu Nguyệt Tê tộc.","anchor":"Ngươi có ba đạo tiên khí, có một đạo kết thành đại đạo chi hoa?!","phamCap":""}]},"capNhatToi":"@c1079","nguon":["@c1079"]},{"id":"truong-sinh-duoc-tri","name":"Trường Sinh dược trì","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Dược trì","phanLoaiPhu":"Dược trì chứa thần dịch Trường Sinh Dược","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Đã được thu vào pháp khí","blurb":"Trường Sinh dược trì là dược trì chứa nước thuốc và thần dịch của Trường Sinh Dược trong Thái Sơ cổ quáng. Thạch Hạo đã thu toàn bộ dược trì cùng thần dịch vào pháp khí trước khi tiếp tục tiến sâu tìm Lục Đạo Luân Hồi Thiên Công @c1080.","detail":"Nước thuốc và thần dịch trong Trường Sinh dược trì có thể hỗ trợ Thạch Hạo niết bàn, đồng thời cường hóa thân thể và nguyên thần. Trước khi rời nơi tu hành để tiến sâu hơn, hắn thu toàn bộ dược trì cùng số thần dịch bên trong vào pháp khí @c1080.","congNang":["Hỗ trợ niết bàn.","Cường hóa thân thể và nguyên thần."],"dacDiem":"Chứa nước thuốc và thần dịch của Trường Sinh Dược.","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1080","denChuong":"","cachCoDuoc":"Thu toàn bộ dược trì vào pháp khí trước khi rời nơi tu hành.","trangThai":"dang-co"}],"capNhatToi":"@c1080","tabs":{"tienTrinh":[{"chuong":"@c1080","loai":"đổi chủ","importance":"major","giaiDoan":"Được Thạch Hạo thu lấy","phamCap":"Không rõ","text":"Thạch Hạo thu toàn bộ Trường Sinh dược trì cùng thần dịch vào pháp khí.","anchor":"đem Trường Sinh dược trì trực tiếp thu vào pháp khí bên trong"}]},"nguon":["@c1080"]},{"id":"long-co-su","name":"Lông cổ sư","cn":"","aliases":["Sư mao"],"category":"nguyen-lieu","categoryLabel":"Vật liệu","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Được Thạch Hạo nhặt giữ","blurb":"Vài sợi lông rơi lại sau khi di hài cổ sư biến mất trong bóng tối.","detail":"Các sợi lông cứng hơn thép, có thể phát sáng và phát ra tiếng kim loại khi chịu lực từ Thạch Hạo.","hinhDang":"Vài sợi lông của di hài cổ sư.","vatLieu":"Lông sinh linh cổ xưa, cứng hơn thép.","dacDiem":"Cứng hơn thép, phát sáng và phát tiếng kim loại khi chịu lực.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1081","denChuong":"","cachCoDuoc":"Nhặt trên mặt đất sau khi di hài cổ sư biến mất","trangThai":"dang-so-huu"}],"tabs":{"tienTrinh":[{"chuong":"@c1081","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nhặt trong cổ khoáng","text":"Thạch Hạo nhặt được vài sợi lông cổ sư có độ cứng vượt thép.","anchor":"hắn từ trên mặt đất nhặt được mấy cây sư mao, lại so với thép còn muốn rắn chắc"}]},"capNhatToi":"@c1081","nguon":["@c1081"]},{"id":"mui-ten-gay-mau-den","name":"Mũi tên gãy màu đen","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Hung khí","phamCap":"Không rõ","soHuu":[],"trangThai":"Gãy, còn cắm trong di thể thiếu niên","blurb":"Một nửa mũi tên đen còn cắm trong lỗ thủng sau đầu của di thể thiếu niên. Khí tức quỷ dị của nó khiến người quan sát có cảm giác hồn phách bị hút vào.","detail":"Mũi tên từng xuyên từ sau đầu vào Nguyên Thần của một cao thủ cổ đại. Thạch Hạo nhận thấy nó đen như mực, mang cảm giác quỷ dị và nguy hiểm dù chỉ còn là một đoạn gãy.","phanLoaiPhu":"Mũi tên","hinhDang":"Nửa mũi tên gãy màu đen","uyLuc":"Từng xuyên thủng Nguyên Thần của di thể thiếu niên trong sáu cường giả.","dacDiem":"Chỉ nhìn vào cũng khiến Thạch Hạo cảm thấy hồn phách như bị hút đi.","congNang":["Xuyên thủng Nguyên Thần của mục tiêu."],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1082","loai":"xuất hiện","importance":"normal","giaiDoan":"Phát hiện trên di thể","text":"Thạch Hạo phát hiện nửa mũi tên đen còn cắm sau đầu di thể thiếu niên và nhận định nó đã xuyên thủng Nguyên Thần nạn nhân.","anchor":"này màu đen mũi tên gãy chỉ là nhìn mà thôi, liền muốn đem người hồn phách hút vào đi","phamCap":"Không rõ"}]},"capNhatToi":"@c1082","nguon":["@c1082"]},{"id":"tam-da-thu-tinh-than-chua-ban-thieu-luc-dao","name":"Tấm da thú tinh thần chứa bản thiếu Lục Đạo","cn":"","aliases":[],"category":"khac","categoryLabel":"Ấn ký tinh thần","phanLoaiPhu":"Vật phẩm tinh thần","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Được Thạch Hạo tái hiện để dẫn động cổ điện","hinhDang":"Tấm da thú sách cổ do dấu ấn ý chí tinh thần biến thành","nguonGoc":"Thạch Hạo từng lấy được tại Hư Thần giới","blurb":"Một tấm da thú không có thực thể vật chất, do dấu ấn ý chí tinh thần biến thành. Không gian nhỏ bên trong lưu phần văn tự Lục Đạo không trọn vẹn.","detail":"Thạch Hạo tái hiện những phù văn không trọn vẹn lưu trong tấm da thú, khiến cung điện cổ màu đen và sáu thi thể phát sáng, cộng hưởng. Bản thiếu chỉ dẫn động được tiếng tụng kinh mơ hồ và không thể tự mình gọi ra cổ kinh hoàn chỉnh.","congNang":["Lưu giữ phần văn tự Lục Đạo không trọn vẹn.","Dẫn động sự cộng hưởng của cung điện cổ màu đen và sáu thi thể."],"dacDiem":"Không phải vật thể thật mà là dấu ấn ý chí tinh thần.","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1083","denChuong":"","cachCoDuoc":"Từng thu được tại Hư Thần giới","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1083","loai":"dùng","importance":"normal","giaiDoan":"Dẫn động cổ điện","text":"Thạch Hạo tái hiện bản thiếu trong tấm da thú, khiến cổ điện và sáu thi thể cộng hưởng nhưng chưa thể gọi ra kinh văn hoàn chỉnh.","anchor":"Hắn nghĩ tới rồi một tấm da thú sách cổ, đương nhiên cũng không phải thực thể, mà là tinh thần ý chí dấu ấn biến thành, chiếm được Hư Thần giới.","phamCap":"Không rõ"}]},"capNhatToi":"@c1083","nguon":["@c1083"]},{"id":"tien-kim","name":"Tiên kim","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Vật liệu luyện khí","phamCap":"Vật liệu khiến Chân Tiên và Trường Sinh giả thèm muốn","soHuu":[],"trangThai":"Từng được khai thác trong Thái Sơ cổ quáng","blurb":"Vật liệu luyện khí quý hiếm từng được người xưa khai thác trong Thái Sơ cổ quáng. Tiên kim có thể dùng để đúc binh khí vô thượng.","detail":"Các hình khắc cổ cho thấy hoạt động khai thác tiên kim từng diễn ra với quy mô lớn. Giá trị của vật liệu này thu hút cả Chân Tiên và Trường Sinh giả, nhưng quá trình khai thác sau đó gắn với hàng loạt cái chết ly kỳ và việc phong ấn cổ khoáng.","phanLoaiPhu":"Tiên kim","congNang":["Có thể dùng để đúc binh khí vô thượng."],"dacDiem":"Hiếm quý đến mức Chân Tiên và Trường Sinh giả cũng thèm muốn.","capNhatToi":"@c1085","tabs":{"tienTrinh":[{"chuong":"@c1085","loai":"xuất hiện","importance":"normal","giaiDoan":"Được ghi lại trên khắc đá cổ","text":"Khắc đá trong Thái Sơ cổ quáng cho thấy người xưa từng tổ chức khai thác tiên kim để đúc binh khí vô thượng.","anchor":"có thể đúc vô thượng binh khí"}]},"nguon":["@c1085"]},{"id":"thuoc-nuoc-trong-ao-niet-ban","name":"Thuốc nước trong ao niết bàn","cn":"","aliases":[],"category":"khac","categoryLabel":"Linh dịch","phamCap":"Hiệu lực không kém Chân Hoàng huyết trì","soHuu":["Thạch Hạo"],"trangThai":"Gần cạn sau khi Thạch Hạo hoàn tất niết bàn","blurb":"Linh dịch trong ao giúp Thạch Hạo thoát thai hoán cốt và hoàn thành niết bàn. Học sinh Thiên Thần Thư Viện đánh giá hiệu lực của nó không kém Chân Hoàng huyết trì.","detail":"Thạch Hạo dùng linh dịch để thay máu, đổi da, tái tạo phủ tạng và chân cốt. Khi nhóm học sinh Thiên Thần Thư Viện tìm tới, lượng thuốc nước trong ao đã gần như bị sử dụng hết.","phanLoaiPhu":"Linh dịch hỗ trợ niết bàn","uyLuc":"Có hiệu quả rèn luyện thân thể và hỗ trợ niết bàn không kém Chân Hoàng huyết trì.","dacDiem":"Ao gần như khô cạn sau khi Thạch Hạo sử dụng.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1086","congNang":["Hỗ trợ thoát thai hoán cốt, niết bàn và rèn luyện thân thể."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1086","denChuong":"@c1086","cachCoDuoc":"Tiến vào ao và hấp thu thuốc nước để niết bàn.","trangThai":"Đã sử dụng gần hết"}],"tabs":{"tienTrinh":[{"chuong":"@c1086","loai":"dùng","importance":"normal","giaiDoan":"Hỗ trợ niết bàn","text":"Thuốc nước trong ao giúp Thạch Hạo hoàn tất thoát thai hoán cốt và bị sử dụng gần cạn.","anchor":"Hắn niết bàn là bởi vì thuốc nước kia, không kém hơn chúng ta thư viện Chân Hoàng huyết trì"}]},"nguon":["@c1086"]},{"id":"hoang-huyet","name":"Hoàng Huyết","cn":"","category":"nguyen-lieu","categoryLabel":"Thần huyết","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Bị Thạch Hạo lấy làm chiến lợi phẩm","blurb":"Hoàng Huyết là một lượng thần huyết đỏ tươi trong suốt, được chứa trong bình nhỏ. Sau khi đánh bại một nhóm thiên tài, Thạch Hạo lấy bình này từ một thanh niên và suy đoán đó là máu Phượng Hoàng niết bàn, có thể bắt nguồn từ Hoàng Huyết trì của Thiên Thần Thư Viện. (+) Hoàng Huyết có thể hòa vào thần tuyền để gột rửa thân thể và thúc đẩy một lần lột xác lớn. [CAN-SOAT-GOP]","detail":"Hoàng Huyết có hình thái đỏ tươi trong suốt, tựa ngọn lửa đang nhảy múa. Nó được suy đoán là thần huyết do Phượng Hoàng niết bàn để lại và lấy từ Hoàng Huyết trì thuộc Thiên Thần Thư Viện. Bình Hoàng Huyết sau đó đổi chủ khi Thạch Hạo thu được nó từ một thanh niên thuộc nhóm thiên tài chiến bại. @c1087","phanLoaiPhu":"Máu Phượng Hoàng niết bàn","hinhDang":"Chất lỏng đỏ tươi trong suốt, giống ngọn lửa nhảy múa","nguonGoc":"Được suy đoán lấy từ Hoàng Huyết trì của Thiên Thần Thư Viện","dacDiem":"Thần huyết đỏ tươi trong suốt, tựa ngọn lửa nhảy múa, mang đặc trưng liên quan tới Phượng Hoàng niết bàn.","chuHienThoi":"Thạch Hạo","congNang":[],"chuSoHuu":[{"ten":"Thanh niên mang Hoàng Huyết","tuChuong":"@c1087","denChuong":"@c1087","cachCoDuoc":"Không rõ","trangThai":"Đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c1087","denChuong":"","cachCoDuoc":"Lấy từ thanh niên chiến bại","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1087","loai":"đổi chủ","importance":"major","giaiDoan":"Bị cướp sau trận chiến","text":"Thạch Hạo lấy bình Hoàng Huyết từ một thanh niên thuộc nhóm thiên tài chiến bại.","anchor":"nội hàm Phượng Hoàng niết bàn lưu một trì huyết","phamCap":"Không rõ"}]},"capNhatToi":"@c1087","nguon":["@c1087","@c1111"]},{"id":"bach-cot-bong","name":"Bạch cốt bổng","cn":"","category":"phap-bao","categoryLabel":"Vũ khí","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo sử dụng","blurb":"Một cây gậy xương trắng được Thạch Hạo dùng để trấn áp người phản đối xóa ký ức. Khi được gia trì cốt văn, đòn đánh vào gáy khiến mục tiêu lập tức bất tỉnh.","detail":"Thạch Hạo xoay bạch cốt bổng và gia trì cốt văn lên vũ khí trước khi đánh mạnh vào gáy thanh niên chống lệnh. Đòn đánh tạo điều kiện để hắn trực tiếp xử lý phần dấu ấn thần hồn chứa ký ức.","phanLoaiPhu":"Gậy xương","hinhDang":"Cây gậy bằng xương trắng","uyLuc":"Một đòn có cốt văn đủ khiến thanh niên thiên tài bất tỉnh.","dacDiem":"Có thể được gia trì cốt văn khi công kích.","chuHienThoi":"Thạch Hạo","congNang":["Đánh ngất mục tiêu để người sử dụng xử lý ký ức và dấu ấn thần hồn."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1087","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1087","loai":"dùng","importance":"normal","giaiDoan":"Gia trì cốt văn","text":"Thạch Hạo gia trì cốt văn lên bạch cốt bổng rồi đánh ngất thanh niên phản đối xóa ký ức.","anchor":"Thạch Hạo ra tay, trực tiếp xoay chuyển một cái bạch cốt bổng","phamCap":"Không rõ"}]},"capNhatToi":"@c1087","nguon":["@c1087"]},{"id":"chien-thuyen-mau-xanh-lam","name":"Chiến thuyền màu xanh lam","cn":"","aliases":["Nô lệ thuyền màu lam"],"category":"phap-bao","categoryLabel":"Tinh vực chiến thuyền","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang hoạt động","blurb":"Chiến thuyền vận chuyển tám, chín vạn tu sĩ tới khai thác vùng núi quanh Thái Sơ cổ quáng. Thạch Hạo trà trộn lên thuyền để trở về Vô Lượng Thiên.","detail":"Chiến thuyền màu xanh lam chuyên chở số lượng lớn tu sĩ và có thể vượt tinh vực qua các khe nứt không gian. Sau khi đưa người tới Thái Sơ ngôi sao, thuyền nhận thêm khách hồi hương và trở về Vô Lượng Thiên.","congNang":["Vận chuyển số lượng lớn tu sĩ giữa Thái Sơ ngôi sao và Vô Lượng Thiên @c1089","Vượt tinh vực qua các khe nứt không gian @c1089"],"capNhatToi":"@c1089","nguon":["@c1089"]},{"id":"chien-thuyen-mau-tim-cua-vuong-gia","name":"Chiến thuyền màu tím của Vương gia","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo phi hành","phamCap":"Không rõ","soHuu":["Vương gia"],"trangThai":"Đang hoạt động","blurb":"Chiến thuyền nô lệ màu tím của Vương gia có thể vượt qua hư không và chuyên chở người đường dài.","detail":"Chiến thuyền xuất phát từ Thái Sơ cổ quáng, tiến vào Vô Lượng Thiên rồi đuổi kịp chiến thuyền màu xanh lam để ông lão Vương gia tìm kiếm một nô bộc quan trọng đào tẩu.","phanLoaiPhu":"Chiến thuyền nô lệ","hinhDang":"Thuyền lớn màu tím","chuHienThoi":"Vương gia","congNang":["Vượt qua hư không giữa Thái Sơ cổ quáng và Vô Lượng Thiên.","Chuyên chở người và truy đuổi chiến thuyền khác."],"chuSoHuu":[{"ten":"Vương gia","tuChuong":"@c1090","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1090","tabs":{"tienTrinh":[{"chuong":"@c1090","loai":"dùng","importance":"normal","giaiDoan":"Truy đuổi chiến thuyền xanh lam","text":"Chiến thuyền màu tím vượt hư không từ Thái Sơ cổ quáng tới Vô Lượng Thiên và đuổi theo chiến thuyền màu xanh lam.","anchor":"Khi (làm) Thạch Hạo rời đi chiến thuyền không lâu, một chiếc màu tím thuyền lớn vượt qua hư không, tiến vào mảng đại lục cổ này, đuổi theo chiến thuyền màu xanh lam.","phamCap":"Không rõ"}]},"nguon":["@c1090"]},{"id":"ngoc-kiem-cua-manh-van","name":"Ngọc Kiếm","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Mạnh Vân"],"trangThai":"Đang được sử dụng","blurb":"Thanh kiếm được Mạnh Vân sử dụng khi một mình giao chiến với nhiều học sinh Thiên Thần Thư Viện.","detail":"Trong lúc Mạnh Vân chiến đấu tại sơn môn, Ngọc Kiếm phát ra kiếm quang như cầu vồng.","congNang":["Phát ra kiếm quang như cầu vồng khi giao chiến."],"uyLuc":"Hỗ trợ Mạnh Vân giao chiến và đánh bại nhóm học sinh trấn giữ sơn môn.","chuHienThoi":"Mạnh Vân","chuSoHuu":[{"ten":"Mạnh Vân","tuChuong":"@c1091","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1091","tabs":{"tienTrinh":[{"chuong":"@c1091","loai":"dùng","importance":"normal","giaiDoan":"Giao chiến tại sơn môn","text":"Mạnh Vân dùng Ngọc Kiếm giao chiến với nhiều học sinh Thiên Thần Thư Viện, khiến kiếm quang hiện ra như cầu vồng.","anchor":"cầm trong tay một thanh Ngọc Kiếm, ánh kiếm như cầu vồng","phamCap":"Không rõ"}]},"nguon":["@c1091"]},{"id":"giuong-ky-thach-cua-vuong-hi","name":"Giường kỳ thạch của Vương Hi","cn":"","aliases":[],"category":"khac","categoryLabel":"Kỳ thạch ngộ đạo","phanLoaiPhu":"Giường kỳ thạch","phamCap":"Không rõ","soHuu":["Vương Hi"],"chuHienThoi":"Vương Hi","trangThai":"nguyên vẹn","hinhDang":"Kỳ thạch dài hơn một trượng, sáng óng ánh.","nguonGoc":"Được Vương Hi mang từ Vương gia tới Thanh Hi U Lâm.","blurb":"Kỳ thạch đặt trong tiểu thiên địa riêng của Vương Hi, vừa là giường của nàng vừa có tác dụng hỗ trợ ngộ đạo. Trước Thạch Hạo, chưa từng có người khác đặt chân lên vật này.","detail":"Người ngồi xếp bằng trên kỳ thạch có thể hòa hợp với thiên địa và nhanh chóng tiến vào trạng thái ngộ đạo. Thạch Hạo tưởng đây chỉ là ngộ đạo đài nên vô tình ngồi lên, dẫn đến lời đồn lan rộng trong Thiên Thần Thư Viện.","congNang":["Hỗ trợ người sử dụng hòa hợp với thiên địa và nhanh chóng tiến vào trạng thái ngộ đạo @c1095"],"uyLuc":"Có thể giúp người ngồi trên đó nhanh chóng nhập ngộ đạo cảnh.","dacDiem":"Được đặt tại trung tâm thạch thất riêng của Vương Hi và chưa từng cho người khác đặt chân lên.","chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1095","denChuong":"","cachCoDuoc":"Mang từ Vương gia tới Thiên Thần Thư Viện.","trangThai":"đang sở hữu"}],"capNhatToi":"@c1095","tabs":{"tienTrinh":[{"chuong":"@c1095","loai":"dùng","importance":"normal","giaiDoan":"Bị Thạch Hạo dùng làm ngộ đạo đài","text":"Thạch Hạo ngồi lên kỳ thạch và nhanh chóng hòa hợp với thiên địa, sau đó mới biết đây là giường riêng của Vương Hi.","anchor":"xếp bằng ở phía trên, rõ ràng khả dĩ cùng này thiên địa dung hợp cùng một chỗ, rất nhanh lâm vào ngộ đạo cảnh","phamCap":"Không rõ"}]},"nguon":["@c1095"]},{"id":"tu-phu-dich-ngu-sac","name":"Tử Phủ dịch ngũ sắc","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thiên địa tinh túy","phamCap":"Gần với Tử Phủ tiên vụ nhưng chưa đạt cấp độ truyền thuyết","soHuu":["Thạch Hạo"],"trangThai":"Thuộc về Thạch Hạo","blurb":"Tử Phủ dịch ngũ sắc là một lò chất lỏng màu tím, có sương mù ngũ sắc dâng lên, từng thuộc về hậu duệ Thái cổ ma hùng. Vật này được dùng làm tiền cược và trở thành chiến lợi phẩm của Thạch Hạo sau khi đối phương thua trận tại @c1097.","detail":"Tử Phủ dịch ngũ sắc có phẩm chất bất phàm, gần với Tử Phủ tiên vụ được ghi trong điển tịch nhưng chưa nội hàm tiên khí ở cấp độ truyền thuyết. Tại @c1097, hậu duệ Thái cổ ma hùng đem vật này ra làm tiền cược; sau trận thua, nó đổi chủ và rơi vào tay Thạch Hạo.","phanLoaiPhu":"Thiên địa tinh túy","hinhDang":"Chất lỏng màu tím bốc sương mù ngũ sắc","dacDiem":"Chất lỏng màu tím đựng trong một lò, có từng trận sương mù ngũ sắc dâng lên; phẩm chất gần với Tử Phủ tiên vụ trong điển tịch nhưng chưa nội hàm tiên khí ở cấp độ truyền thuyết.","chuHienThoi":"Thạch Hạo","congNang":["Là thiên tài địa bảo có giá trị đủ để được dùng làm tiền cược tại @c1097."],"chuSoHuu":[{"ten":"Hậu duệ Thái cổ ma hùng","tuChuong":"@c1097","denChuong":"@c1097","cachCoDuoc":"Sở hữu trước trận tỷ thí","trangThai":"Đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c1097","denChuong":"","cachCoDuoc":"Thắng trong trận tỷ thí","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1097","tabs":{"tienTrinh":[{"chuong":"@c1097","loai":"đổi chủ","importance":"major","giaiDoan":"Chiến lợi phẩm của Thạch Hạo","text":"Hậu duệ Thái cổ ma hùng dùng Tử Phủ dịch ngũ sắc làm tiền cược và mất nó vào tay Thạch Hạo sau trận thua.","anchor":"cái kia chất lỏng màu tím bên trong dựng lên từng trận ngũ sắc sương mù","phamCap":"Gần với Tử Phủ tiên vụ nhưng chưa đạt cấp độ truyền thuyết"}]},"dinhDanh":"goc","nguon":["@c1097"]},{"id":"lo-luyen-dan-chua-tu-phu-dich","name":"Lò luyện đan chứa Tử Phủ dịch","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật chứa","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Thuộc về Thạch Hạo","blurb":"Một lò luyện đan tỏa lưu quang và hào quang, bên trong chứa đầy Tử Phủ dịch ngũ sắc. Sau khi đánh bại hậu duệ Thái cổ ma hùng, Thạch Hạo lấy cả lò làm chiến lợi phẩm.","detail":"Lò luyện đan được dùng để chứa và bảo quản Tử Phủ dịch ngũ sắc. Trong trận tỷ thí với hậu duệ Thái cổ ma hùng, Thạch Hạo giành chiến thắng và thu lấy cả lò cùng số Tử Phủ dịch bên trong, khiến pháp bảo này đổi chủ tại @c1097.","phanLoaiPhu":"Vật chứa thiên địa tinh túy","hinhDang":"Lò luyện đan tỏa lưu quang và hào quang","dacDiem":"Tỏa lưu quang và hào quang, bên trong chứa đầy Tử Phủ dịch ngũ sắc.","chuHienThoi":"Thạch Hạo","congNang":["Chứa và bảo quản Tử Phủ dịch ngũ sắc. @c1097"],"chuSoHuu":[{"ten":"Hậu duệ Thái cổ ma hùng","tuChuong":"@c1097","denChuong":"@c1097","cachCoDuoc":"Sở hữu trước trận tỷ thí","trangThai":"Đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c1097","denChuong":"","cachCoDuoc":"Lấy đi sau khi thắng trận","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1097","tabs":{"tienTrinh":[{"chuong":"@c1097","loai":"đổi chủ","importance":"major","giaiDoan":"Chiến lợi phẩm của Thạch Hạo","text":"Thạch Hạo lấy lò luyện đan chứa Tử Phủ dịch sau khi đánh bại hậu duệ Thái cổ ma hùng.","anchor":"Này Tử Phủ dịch là của ta rồi. Thạch Hạo dứt lời, trực tiếp đem lò luyện đan lấy đi","phamCap":"Không rõ"}]},"dinhDanh":"goc","nguon":["@c1097"]},{"id":"chan-hoang-huyet","name":"Chân Hoàng huyết","cn":"","category":"nguyen-lieu","categoryLabel":"Chân huyết cổ Phượng Hoàng","phamCap":"Không rõ","soHuu":["Thạch Hạo","Vương Hi"],"trangThai":"Được Thạch Hạo luyện hóa","blurb":"Chân huyết cổ Phượng Hoàng được dùng cùng dược thảo để hỗ trợ rèn luyện thân thể và Nguyên Thần.","detail":"Thạch Hạo tích lũy mười bốn phần qua các trận khiêu chiến rồi nhận thêm sáu phần từ Vương Hi. Sáu phần được phong ấn trong những khối thủy tinh đỏ rực.","phanLoaiPhu":"Chân huyết","hinhDang":"Được phong ấn trong các khối thủy tinh to bằng nắm đấm","congNang":["Phối hợp dược thảo để rèn luyện thân thể và Nguyên Thần."],"dacDiem":"Hoàng huyết xán lạn được phong ấn trong thủy tinh óng ánh.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1099","denChuong":"@c1099","cachCoDuoc":"Nắm giữ sáu phần hoàng huyết","trangThai":"đã tặng"},{"ten":"Thạch Hạo","tuChuong":"@c1099","denChuong":"","cachCoDuoc":"Thắng khiêu chiến và được Vương Hi tặng","trangThai":"đã luyện hóa"}],"tabs":{"tienTrinh":[{"chuong":"@c1099","loai":"dùng","importance":"normal","giaiDoan":"Tích lũy và luyện hóa","text":"Thạch Hạo gom mười bốn phần Chân Hoàng huyết, nhận thêm sáu phần từ Vương Hi rồi dùng cùng dược thảo để tu luyện.","anchor":"Sáu khối thủy tinh, đều to bằng nắm đấm, óng ánh trong suốt, đỏ tươi ướt át, bên trong phong ấn xán lạn hoàng huyết","phamCap":"Không rõ"}]},"capNhatToi":"@c1099","nguon":["@c1099"]},{"id":"kinh-thu-nguyen-ban-khac-tren-xuong-va-ngoc","name":"Kinh thư nguyên bản khắc trên xương và ngọc","cn":"","category":"khac","categoryLabel":"Bí điển","phamCap":"Không rõ","soHuu":["Vương Hi","Thạch Hạo"],"trangThai":"Được cho mượn để đọc","blurb":"Các bản kinh thư do người lưu kinh tự tay khắc trên xương và ngọc, không phải bản dập.","detail":"Kinh thư còn giữ chân nghĩa nguyên thủy và những dấu ấn tinh thần vụn vỡ của người lưu kinh, được Vương Hi cho Thạch Hạo mượn đọc.","hinhDang":"Kinh văn khắc trên xương và ngọc","nguonGoc":"Do người lưu kinh tự tay khắc","congNang":["Lưu giữ chân nghĩa nguyên thủy và dấu ấn tinh thần vụn vỡ."],"dacDiem":"Không phải bản dập, còn giữ tinh hoa thuần túy của kinh văn.","chuHienThoi":"Vương Hi","chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1099","denChuong":"","cachCoDuoc":"Nắm giữ trong động phủ","trangThai":"chủ sở hữu"},{"ten":"Thạch Hạo","tuChuong":"@c1099","denChuong":"","cachCoDuoc":"Được Vương Hi cho mượn","trangThai":"đang đọc"}],"tabs":{"tienTrinh":[{"chuong":"@c1099","loai":"xuất hiện","importance":"normal","giaiDoan":"Cho mượn đọc","text":"Vương Hi cho Thạch Hạo đọc các kinh thư nguyên bản còn giữ chân nghĩa và dấu ấn tinh thần của người lưu kinh.","anchor":"bởi vì lưu kinh văn giả tự tay khắc, bảo lưu nguyên thủy nhất chân nghĩa","phamCap":"Không rõ"}]},"capNhatToi":"@c1099","nguon":["@c1099"]}]};
